(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("pliny-natural-history-7-b", [{"sp": "HDR", "t": "Naturalis Historia (Libri XX–XXII)"}, {"sp": "HDR", "t": "Liber XX", "st": "20"}, {"sp": "N", "t": "Maximum hine opus naturae ordiemur et cibos suos homini narrabimus faterique cogemus ignota esse per quae vivat. nemo id parvum ac modicum existimaverit, nominum vilitate deceptus. pax secum in his aut bellum naturae dicetur, odia amicitiaeque rerum surdarum ac sensu carentium et, quo magis miremur, omnia ea hominum causa. quod Graeci sympathiam et antipathiam appellavere, quibus cuncta constant, ignes aquis restinguentibus, aquas sole devorante, luna pariente, altero alterius iniuria deficiente sidere atque, ut a sublimioribus recedamus, ferrum ad se trahente magnete lapide et alio rursus abigente a sese, adamanta, ⟨ra⟩rum opum gaudium, Infragil⟨em⟩ omni cetera vi et invictum, sanguine hircino rumpente, quaeque alia in suis locis dicemus paria vel maiora miracu⟨la⟩. tantum venia sit a minimis, sed a salutaribus ordienti primumque ab hortensiis.", "st": "20.1"}, {"sp": "N", "t": "Cucumin silvestrem esse diximus, multo infra magnitudinem sativi. ex eo fit medicamentum, quod vocatur elaterium, suco expresso semini, cuius causa nisi maturius incidatur, semen exilit oculorum etiam periculo. servatur autem decerptus una nocte, postero die inciditur harundine, semenque cinere conditur ad coercendam suci abundantiam, qui expressus suscipitur aqua caelesti atque subsidit, deinde sole cogitur in pastillos ad magnos mortalium usus, obscuritates et vitia oculorum, genarum ulcera. tradunt hoc suco tactis radicibus vitium non attingi uvas ab avibus. radix autem ex aceto cocta podagris inlinitur sucoque dentium dolori medetur, arida cum resina inpetiginem et scabiem quaeque psoram et lichenas vocant, parotidas, panos sanat et cicatricibus colorem reddit, et foliorum sucus auribus surdis cum aceto instillatur.", "st": "20.2"}, {"sp": "N", "t": "Elaterio tempestivus est autumno, nec ullum ex medicamentis longiore aevo durat. incipit a trimatu. si quis recentiore uti velit, pastillos in novo fictili igni lento in aceto domet. melius quo vetustius, fuitque iam cc annis servatum, ut auctor est Theophrastus, et usque ad quinquagesimum lucernarum lumina extinguit. hoc enim veri experimentum est, si admotum, priusquam extinguat, scintillare sursum ac deorsum cogat. pallidum ac leve herbaceo ac scabro melius ac leniter amarum.", "st": "20.3"}, {"sp": "N", "t": "Putant conceptus adiuvari adalligato semine, si terram non adtigerit, partus vero, si in arietis lana alligatum inscientis lumbis fuerit, ita ut protinus ab enixu rapiatur extra domum. ipsum cucumin qui magnificant, nasci praecipuum in Arabia, mox in Arcadia; Cyrenis alii tradunt similem heliotropio cu⟨c⟩u⟨min⟩ inter folia et ramos provenire magnitudine nucis iuglandis, semen autem esse ad speciem scorpionum caudae reflexu⟨m⟩, sed candidum. aliqui etiam ab scorpione cucumim vocant, efficacissimo contra scorpionum ictus et semine et elaterio. est ad purgandam utrimque alvum modus pro portione virium ab dimidio obolo ad solidum; copiosius necat. sic et contra phthiriasim bibitur et hydropicis. inlitum anginas et arterias cum melle aut oleo vetere sanat.", "st": "20.3"}, {"sp": "N", "t": "Multi hunc esse aput nos, qui anguinus vocetur, ab aliis erraticus, arbitrantur, quo decocto sparsa mures non adtingunt. iidem podagris eum et articulariis morbis decoctum in aceto inlinunt praesentaneo remedio, lumborum vero dolores seine sole siccato, dein trito, X̅ XX pondere in hemina aquae dato sanant, ⟨t⟩umores subitos inlito cum lacte mulierum. purgat eas elaterium, sed gravidis abortum facit. suspiriosis prodest, morbo vero regio in nares coniectum. lentigines ac maculas e facie tollit in sole inlitum.", "st": "20.4"}, {"sp": "N", "t": "Multi eadem omnia sativis adtribuunt, magni etiam sine is momenti. namque et eorum semen quantum tres digiti adprehenderint cum cumino tritum potumque in vino tussientibus auxiliatur, et phreneticis in lacte mulieris, et dysintericis acetabuli mensura, purulenta autem expuentibus cum cumino pari pondere, et iocineris vitiis in aqua mulsa. urinam movet ex vino dulci, et in renium dolore clysteribus simul cum cumino infunditur.", "st": "20.5"}, {"sp": "N", "t": "Ei, qui pepones vocantur, refrigerant maxime in cibo et emolliunt alvum. caro eorum epiphoris oculorum aut doloribus inponitur. radix sanat ulcera concreta in modum favi, quae ceria vocant. eadem concitat vomitiones; siccatur, in farina⟨m⟩ tunsa datur quattuor obolis in aqua mulsa, ita ut qui biberit quingentos passus postea ambulet. haec farina et in smegmata adicitur. cortex quoque vomitionem movet, faciem purgat. hoc et folia cuiuscumque sativi inlita. eadem cum melle et epinyctidas sanant, cum vino canis morsus, item multipedae; sepa Graeci vocant, oblongam, pilosis pedibus, pecori praecipue nocivam; morsum tumor insequitur et putrescit locus. ipse cucumis odore defectum animi refovet.—(Coctos deraso cortice ex oleo et aceto ac melle iucundiores esse certum est.)—", "st": "20.6"}, {"sp": "N", "t": "Cucurbita quoque silvestris invenitur, σομφὸς a Graecis appellata, intus inanis, unde et nomen, digitali crassitudine, non nisi in saxosis nascens. huius conmanducatae sucus stomacho admodum prodest.", "st": "20.7"}, {"sp": "N", "t": "Colocynthis vocatur alia, ipsa plena semine, sed minor quam sativa. utilior pallida quam herbacea. arefacta per se inanit alvum. infusa quoque clysteribus intestinorum omnibus vitiis medetur et renium et lumborum et paralysi. eiecto semine aqua mulsa in ea decoquitur ad dimidias; sic tutissimo infunduntur oboli quattuor. prodest stomacho e⟨t⟩ farinae aridae pilulis cum decocto melle sumptis. in morbo regio semina eius VII sumuntur et protinus aqua mulsa. carnes eius cum absinthio ac sale dentium dolorem tollunt, sucus vero cum aceto calefactus mobiles sistit. item spinae et lumborum ac coxendicum dolores, cum oleo si infricetur. praeterea, mirum dictu, semina eius, si fuerint pari numero, in linteo adalligata febribus libera⟨re⟩ dicuntur, quas Graeci periodicas vocant. sativae quoque derasae sucus tepefactus auribus medetur; caro eius interior sine semine clavis pedum et suppurationibus, quae Graeci vocant ἀποστήματα. decoctae autem universae sucus dentium motus stabilit et dolores inhibet; vinum cum ea fervefactum oculorum etiam impetus. folia eius cum recentibus cupressi contusa et inposita, ipsa quoque tosta in argilla ac trita cum adipe anseris vulneribus medetur. nec non ramentis corticis recen⟨tis⟩ podagras refrigerat et ardores capitis, infantium maxime, et ignes sacros vel iisdem strigmentis inpositis vel seminibus. sucus ex strigmentis inlitus cum rosaceo et aceto febrium ardores refrigerat. aridae cinis inpositus mire combusta sanat. Chrysippus medicus damnabat eas in cibis, sed omnium consensu stomacho utilissimae iudicantur et interaneorum vesicarumque exulcerationibus.", "st": "20.8"}, {"sp": "N", "t": "Est et rapo vis medica. perniones fervens inpositum sanat, item frigus pellit e piedibus. aqua decocti eius fervens podagris etiam frigidis medetur, et crudum tusum cum sale cuicumque vitio pedum. semen inlitum et potum in vino contra serpentes et toxica salutare esse proditur, a multis vero antid⟨o⟩ti v⟨i⟩m habere in vino et oleo. Democritus in totum ea abdicavit in cibis propter inflationes, Diocles magnis laudibus tulit, etiam venerem stimulari ab iis professus, item Dionysius, magisque si eruca condirentur; tosta quoque articulorum dolori cum adipe prodes⟨se⟩.", "st": "20.9"}, {"sp": "N", "t": "Silvestre rapum in arvis maxime nascitur, fruticosum, semine candido, duplo maiore quam papaver. hoc ad levigandam cutem in facie totoque corpore utuntur mixta⟨fa⟩rina pari mensura ervi, hordei et tritici et lupini. radix ad omnia inutilis.", "st": "20.10"}, {"sp": "N", "t": "Naporum duas differentias et in medicina Graeci servant. angulosis foliorum caulibus, flore anet⟨i⟩, quod bunion vocant, purgationibus ferminarum et vesicae et urinae utile decoctum, potum ex aqua mulsa vel suci drachma; semen dysintericis tostum tritumque in aqua⟨e⟩ calidae cyathis quattuor. sed urinam inhibet, si non lini semen una bibatur. alterum genus buniada appellant, et raphano et rapo simile, seminis praeclari contra venena. ob id et in antidotis utuntur illo.", "st": "20.11"}, {"sp": "N", "t": "Raphanum et silvestrem esse diximus. laudatissimus in Arcadia, quamquam et alibi nascitur, utilior urinae dumtaxat ciendae, cetero aestuosus. in Italia et armoraciam vocant.", "st": "20.12"}, {"sp": "N", "t": "Et sativi vero praeter ea, quae circa eos dicta sunt, stomachum purgant, pituitam extenuant, urinam concitant, bilem detrahunt. praeterea cortices in vino decocti mane poti ad ternos cyathos conminuunt et eiciunt calculos. iidem in posca decocti contra serpentium morsus inlinuntur. ad tussim etiam mane ieiunis raphanos prodest esse cum melle, semen eorum tostum ipsumque conmanducatum, adliga⟨to⟩ raphano aquam foliis eius decoctis bibere vel sucum ipsius cyathis binis contra phthiriases, phlegmoni ipsos inlinere tusos, livori vero recenti corticem cum melle, veternosis autem quam acerrimos mandere, semenque tostum, dein contritum cum melle suspiriosis. iidem et contra venena prosunt, cerastis et scorpionibus adversantur—vel ipso vel semine infectis manibus inpune tractaveris, inpositoque raphano scorpiones moriuntur—, salutares et contra fungorum aut hyoscyami venena atque, ut Nicander tradit, et contra sanguinem tauri. contra viscum quoque dari Apollodori duo iubent, sed Ci⟨ti⟩eus semen ex aqua tritum, Tarentinus sucum. lienem item extenuant, iocineri prosunt et lumborum doloribus, hydropicis quoque ex aceto aut sinapi sumpti et lethargicis et comitialibus et melancholicis. Praxagoras et iliosis dandos censet, Plistonicus et coeliacis. intestinorum etiam ulcera sanant ac purulenta praecordiorum, si cum melle edantur. quidam ad haec coquere eos luto inlitos malunt; sic et feminas purgari. ex aceto et melle sumpti intestinorum animalia detrahunt, iidem ad tertias decocto eorum poto cum vino enterocelicis prosunt; sanguinem quoque inutilem sic extrahunt. Medius ad haec et sanguinem excreantibus coctos dari iubet, et puerperis ad lactis copiam augendam, Hippocrates capitis mulierum defluvia perfricari raphanis, et super umbilicum inponi contra tormenta volvae. reducunt et cicatrices ad colorem. semen quoque ex aqua inpositum sistit ulcera, quae phagedaenas vocant. Democritus venerem hoc cibo stimulari putat, ob id fortassis voci nocere aliqui tradiderunt. folia, quae in oblongis dumtaxat nascuntur, excitare oculorum aciem dicuntur. ubi vero acrior raphani medicina admota sit, hysopum dari protinus imperant; haec antipathia est. et aurium gravitati sucum raphani instillant. nam vomituris summo cibo esse eos utilissimum est.", "st": "20.13"}, {"sp": "N", "t": "Pastinacae simile hibiscum, quod molochen agrian vocant et aliqui πλειστολοχείαν, ulceribus, cartilagini⟨e⟩t ossibus fractis medetur. folia eius ex aqua pota alvum solvunt; serpentes abigunt, apium, vesparum, crabronum ictibus inlita medentur. radicem eius ante solis ortum erutam involvunt lana coloris, quem nativum vocant, praeterea ovis, quae feminam peperit, strumisque vel suppuratis alligant. quidam ad hunc usum auro effodiendam censent cavendumque, ne terram adtingat. Celsus et podagris, quae sine tumore sint, radicem eius in vino decoctam inponi iubet.", "st": "20.14"}, {"sp": "N", "t": "Alterum genus est staphylinus, quod pastinacam erraticam vocant. eius semen contritum et in vino potum tumentem alvum et suffocationes mulierum doloresque lenit in tantum, ut vulvas corrigat. inlitum quoque e passo ventri earum prosit; et viris vero prosit cum panis portione aequa tritum ex vino potum contra ventris dolores. pellit et urinam, et phagedaenas ulcerum sistit recens cum melle inpositum vel arida farina inspersa. radicem eius Dieuc⟨hes⟩ contra iocineris aut lienis ac lumborum et renium vitia ex aqua mulsa dari iubet, Cleophantus et dysintericis veteribus. Philistio in lacte coquit et ad stranguriam dat radicis uncias quattuor, ex aqua hydropicis, similiter et opisthotonicis et pleuriticis et comitialibus. habentes ear feriri a serpentibus negantur aut, qui ante gustaverint, non laedi; percussis inponitur cum axungia. folia contra cruditates manduntur. Orpheus amatorium inesse staphylino dixit, fortassis quoniam venerem stimulari hoc cibo certum est. ideo conceptus adiuvari aliqui prodiderunt. ad reliqua et sativa pollet, efficacior tamen silvestris magisque in petrosis nata. semen sativae quoque contra scorpionum ictus ex vino aut posca salutare est. radice eius circumscalpti dentes dolore liberantur.", "st": "20.15"}, {"sp": "N", "t": "Syria, in hortis operosissima—u⟨t⟩ique in proVerbi⟨o⟩ Graecis multa Syrorum olera—, simillimam staphylino herbam serit, quam alii gingidion vocant, tenuius tantum et amarius eiusdemque effectus. estur coctum crudumque stomachi magna utilitate; siccat enim ex alto omnes eius umores.", "st": "20.16"}, {"sp": "N", "t": "Siser erraticum sativo simile est et effectu: stomachum excitat, fastidium absterget ex aceto laserpiciato sumptum aut ex pipere et mulso vel ex garo. urinam ciet, ut Ophion credit, et venerem. in eadem sententia est et Diocles; praeterea cordi convenire convalescentium aut post multas vomitiones perquam utile. Heraclides contra argentum vivum dedit et vener⟨em⟩ subinde offensantem aegrisque se recolligentibus. Hicesius ideo stomacho ⟨in⟩utile videri dixit, quoniam nemo tres siseres edendo continuaret, esse tamen utile convalescentibus ad vinum transeuntibus. sativi privatim sucus cum lacte caprino potus sistit alvum.", "st": "20.17"}, {"sp": "N", "t": "Et quoniam plerosque similitudo nominum Graecorum confundit, conteximus et de sili [sed hoc est vulgatae notitiae]. optimum ⟨M⟩assiliense, lato enim grano et fulvo est, secundum Aethiopicum nigrius, Creticum odoratissimum *omnium. radix iucundi odoris est. semen esse et vultures dicuntur. prodest homini ad tussim veterem, rupta, convulsa in vino albo potum, item opisthotonicis et iocinerum vitiis et torminibus et stranguriae duarum aut trium lingularum mensura. sunt et folia utilia, ut quae partus adiuvent etiam quadripedum; hoc maxime pasci dicuntur cervae pariturae. inlinuntur et igni sacro. multumque in summo cibo concoctionibus confert vel folio vel semine. quadripedum quoque alvum sistit sive tritum potui infusum sive mandendo comm⟨e⟩ndatum sale. boum morbis sic tritum infunditur.", "st": "20.18"}, {"sp": "N", "t": "Inula quoque a ieiunis commanducata dentes confirmat. si, ut eruta est, terram non adtingat, condita tussim emendat; radicis vero decoctae sucus t⟨a⟩enias pellit, siccatae autem in umbra farina tussi et convulsis et inflationibus et arteriis medetur. venenatorum morsus abigit. folia ex vino lumborum dolori inlinuntur.", "st": "20.19"}, {"sp": "N", "t": "Cepae silvestres non sunt. sativae olfactu ipso et delacrimatione caligini medentur, magis vero suci inunctione. somnum etiam facere traduntur et ulcera oris sanare commanducatae cum pane, et canis morsus virides ex aceto inlitae aut siccae cum melle… et vino, ita ut post diem tertium solvantur. sic et ⟨at⟩trita sanant. coctam in cinere et epiphoris multi ⟨in⟩posuere cum farina hordeacia et genitalium ulceribus. suco et cicatrices oculorum et albugines et argema inunxere et serpentium morsus et omnia vulnera cum melle; item auricularum… cum lacte mulierum et in iisdem sonitum aut gravitatem emendantes cum adipe anserino aut cum melle stillavere. et ex aqua bibendum dederunt repente obmutescentibus. in dolore quoque ad dentes conluendos instillavere et plagis bestiarum omnium, privatim scorpionum. alopecias fricuere et psoras tusis cepis. coctas dysintericis vescendas dedere et contra lumborum dolores, purgamenta quoque earum cremata in cinerem inlinentes ex aceto serpentium morsibus, ipsasque multipedae ex aceto. reliqua inter medicos mira diversitas. proximi inutiles esse praecordiis et concoctioni inflationemque et sitim facere dixerunt. Asclepiadis schola ad colorem quoque validum profici hoc cibo et, si ieiuni cotidie edant, firmitatem valetudinis custodiri, stomacho utile⟨s⟩ esse, spiritus agitatione ventrem mollire, haemorrhoidas ape⟨ri⟩re subditas pro balanis; sucum cum suco feniculi contra incipientes hy⟨d⟩ropis⟨e⟩s mire proficere, item contra anginas cum rutae et melle; excitari eodem lethargicos.—(Varro quae sale et aceto pis⟨t⟩a est arefactaque, vermiculis non infestari auctor est).—", "st": "20.20"}, {"sp": "N", "t": "Porrum sectivum profluvia sanguinis sistit naribus contrito eo obturatis vel gallae mixto aut mentae, item ex abortu profluvia poto suco. cum lacte mulieris tussi etiam veteri et pectoris ac pulmonis vitiis medetur. inlitis foliis sanantur vari et ambusta et epinyctides— ita vocatur ulcus, qua⟨e⟩et s⟨y⟩ce, in angulo oculi perpetuo umore manans; quidam eodem nomine appellant pusulas liventes ac noctibus inquietantes—et alia ulcera cum melle trit⟨is⟩, vel bestiarum morsus ex aceto, item serpentium aliorumque venenatorum, aurium vero vitia cum felle caprino vel pari mensura mulsi, stridores cum lacte mulieris, capitis dolores, si in nares fundatur dormituris ve⟨l⟩ in aures duobus suci coclearibus, uno mellis. sucus et ad serpentium scorpionumque ictus bibitur cum mero et ad lumborum dolores cum vini hemina potus. sanguinem vero excreantibus et phthisicis et destillationibus longis vel sucus vel ex ipso cibus prodest, item morbo regio vel hydropicis et ad renum dolores, cum tisanae suco acetabuli mensura. idem modus cum melle vulvas purgat. estur vero et contra fungorum venena, inponitur et vulneribus, venerem stimulat, sitim sedat, ebrietates discutit, sed oculorum aciem hebetare traditur, inflationes quoque facere, quae tamen stomacho non noceant ventremque molliant. voci splendorem adfert.", "st": "20.21"}, {"sp": "N", "t": "Capitato maiores ad eadem effectus. sanguinem reicientibus sucus eius cum galla aut turis farina vel acacia datur. Hippocrates et sine alia mixtura dari iubet vulvasque contractas aperire se putat, fecunditatem etiam feminarum hoc cibo augeri. contritum ex melle ulcera purgat. tussim et destillationes thoracis, pulmonis et arteriae vitia sanat, datum in sorbitione tisanae vel crudum praeter capita sine pane, ita ut alternis diebus sumatur, vel si pura excreentur. sic et voci et veneri somnoque multum confert. capita bis aqua mutata cocta alvum emolliunt… sistit fluctiones veteres; cortex decoctus inlitusque inficit canos.", "st": "20.22"}, {"sp": "N", "t": "Alio magna vis, magnae utilitates contra aquarum et locorum mutationes. serpentes abigit et scorpiones odore atque, ut aliqui tradidere, bestias omn⟨e⟩s. ict⟨ib⟩us medetur potu vel cibo vel inlitu, privatim contra haemorrhoidas cum vino redditum vomitu. ac, ne contra araneos mures venenati morsus valere miremur, aconitum, quod alio nomine pardalianches vocatur, debellat, item hyoscyamum, canum morsu⟨s⟩, in quae vulnera cum melle inponitur. ad serpentium quidem ictus ⟨tos⟩tum cum restibus suis efficacissime ex oleo inlinitur, adtritisque corporum partibus, vel si in vesicas intumuerint. quin et suffito eo evocari secundas partus existimat Hippocrates, cinere eius cum oleo capitis ulcera manantia sanitati restituens. suspiriosis coctum, aliqui crudum id dedere; Diocles hydropicis cum centaurio aut in fico duplici ad evacuandam alvum, quod efficacius praestat viride cum coriandro in mero potum; suspiriosis aliqui et tritum in lacte dederunt. Praxagoras et contra morbum regium vino miscuit et contra ⟨i⟩leum in oleo et pulte, sic inlinens strumis quoque. antiqui et insanientibus dabant crudum, Diodes phreneticis elixum. contra anginas tritum in posca gargarizari prodest. dentium dolorem tribus capitibus in aceto tritis inminuit, vel si decocti aqua conluantur addaturque ipsum in cava dentium. auribus etiam instillatur sucus cum adipe anserino. phthiriases et porrigines potum, item infusum cum aceto et nitro conpescit, destillationes cum lacte coctum vel tritum permixtumve caseo molli, quo genere et raucitatem extenuat vel in pisi aut fabae sorbitione. in totum autem coctum utilius est crudo elixumque tosto; sic et voci plus confert. t⟨ae⟩nias et reliqua animalia interaneorum pellit in aceto mulso coctum; tenesmo in pulte medetur; temporum doloribus inlinitur elixum et pusulis coctum, dein cum melle tritum; tussi cum adipe vetusto decoctum vel cum lacte aut, si sanguis etiam excreetur vel pura, sub pruna⟨t⟩o⟨s⟩tum et cum mellis pari modo sumptum; convulsis, ruptis cum sale et oleo. ⟨ite⟩m cum adipe tumores suspectos sanat. extrahit fistulis vitia cum sulpure et resina, etiam harundines cum pice; lepras, lichenas, lentigines exulcerat sanatque cum origano, vel cinis eius ex oleo et garo inlitus; sic et sacros ignes; suggillata aut liventia ad colorem reducit conbustum ex melle. credunt et comitialem morbum sanari, si quis eo in cibis utatur ac potione; quartanas quoque excutere potum caput unum cum laserpici obolo in vino austero, —(tussim et alio modo ac pectorum suppurationes(?) quantaslibet sanat fractae incoctum fabae atque ita in cibo sumptum, donec sanitatem restituat. facit et somnos, atque in totum rubicundiora corpora)—venerem quoque stimulare cum coriandro viridi tritum potumque e mero. vitia eius sunt quod oculos hebetat, inflationes facit, stomachum laedit copiosius sumptum, sitim gignit. cetero contra pituitam et gallinaceis prodest mixtum farre in cibo. iumenta urinam reddere atque non torqueri tradunt, si trito natura tangatur.", "st": "20.23"}, {"sp": "N", "t": "Lactucae sponte nascentis primum genus est eius, quam caprinam vocant, qua pisces in mare deiecta protinus necantur, qui sunt in proximo. huius lac spissatum mox in aceto pondere obolorum duum adiecto aquae uno cyatho hydropicis datur. caule et foliis contusis, asperso sale, nervi incisi sanantur. eadem trita ex aceto conluta matutinis bis mense dentium dolorem prohibent.", "st": "20.24"}, {"sp": "N", "t": "alterumn est genus quod Graeci caesapon vocant. huius folia trita et cum polenta inlita ulceribus medentur. haec in arvis nascuntur; tertium genus in silvis nascensἰσάτιν vocant. huius folia trita cum polenta vulneribus prosunt. quarto infectores lanarum utuntur. simile id erat lapatho silvestri foliis, nisi plura haberet et nigriora. sanguinem sistit, phagedaenas et putrescentia ulcera aut quae serpunt sanat, item tumores ante suppurationem, ignem sacrum radice vel foliis. prodest vel ad lienes pot⟨u.⟩ haec propria singulis.", "st": "20.25"}, {"sp": "N", "t": "Communia autem sponte nascentibus candor, caulis interdum cubitali longitudine, in t⟨hyr⟩so et foliis scabritia. ex iis rotunda folia et brevia habentem sunt qui hieracion vocent, quoniam accipitres scalpendo eam sucoque oculos tinguendo obscuritatem, cum sensere, discutiant. sucus omnibus candidus, viribus quoque papaveri similis; carpitur per messes inciso caule, conditur fictili novo, ad multa praeclarus. sanat omnia oculorum vitia cum lacte mulierum, argema, nubiculas, cicatrices adustionesque omnes, praecipue caligines. inponitur etiam oculis in lana contra epiphoras. idem sucus alvum purgat in posca potus ad duos obolos. serpentium ictibus medetur in vino potus. et folia th⟨y⟩rsique triti ex aceto bibuntur, vulneri inlinuntur, maxime contra scorpionum ictus, contra vero phalangia commixto vino et aceto. aliis quoque venenis resistunt, exceptis quae strangulando necant aut his quae vesicae nocent, item psimithio excepto. inponuntur et ventri ex melle atque aceto ad detrahenda vitia alvi. urinae difficultates sucus emendat. Crateuas eum et hydropicis obolis duobus in aceto et cyatho vini dari iubet. quidam et e sativis colligunt sucum minus efficacem. peculiares earum effectus—pra⟨e⟩ter i⟨a⟩m dictos somnum faciendi veneremque inhibendi, aestum refrigerandi, stomachum purgandi, sanguinem augendi—non pauci restant, quoniam et inflationes discutiunt ructusque lenes faciunt, concoctiones adiuvant, cruditates ipsae numquam faciunt. nec ulla res in cibis magis aviditatem incitat inhibetque eadem. in causa alterutraque modus est: sic et alvum copiosiores solvunt, modicae sistunt. lentitiam pituitae digerunt atque, ut aliqui tradiderunt, sensus purgant, stomachis dissolutis utilissim⟨a⟩e. adiuvantur in eos usus et oxypori obolis, asperitatem addito dulci ad intinctum aceti temperantes, si crassior pituita sit, scillite aut vino abs⟨i⟩nt⟨h⟩ite, si et tussis sentiatur, hysopite admixto. dantur coeliacis cum intubo erratico et ad duritiam praecordiorum. dantur et melancholicis candidae copiosiores et ad vesicae vitia. Praxagoras et dysintericis dedit. ambustis quoque prosunt recentibus, priusquam pusulae fiant, cum sale inlitae. ulcera etiam, quae serpunt, coercent, i⟨n⟩itio cum a⟨phr⟩onitro, mox in vino. tritae igni sacro inlinuntur. convulsa et luxata caulibus tritis cum polenta ex aqua frigida leniunt, eruptiones papularum ex vino et polenta. in cholera quoque coctas patinis dederunt, ad quod utilissimae quam maximi caulis et amarae. quidam et lacte infundunt. defervefacti hi caules et stomacho utilissimi traduntur, sicut somno aestiva maxime lactuca et amara lactensque, quam meconidem vocavimus. hoc lacte et oculorum claritati cum muliebri lacte utilissimum esse praecipitur, dum tempestivo capite inunguantur oculi, et ad vitia, quae frigore in his facta sint. miras et alias invenio laudes: thoracis vitiis prodesse non secus quam habrotonum cum melle Attico; purgari et feminas hoc cibo; semen sativarum contra scorpiones dari; semine trito ex vino poto et libidinum imaginationes in somno conpesci; temptantes aquas non nocere lactucam edentibus. quidam tamen frequentiores in cibo officere claritati oculorum tradiderunt.", "st": "20.26"}, {"sp": "N", "t": "Nec beta sine remediis est utraque: sive candidae sive nigrae radix recens et madefacta suspensa funiculo contra serpentium morsus efficax esse dicitur; candida beta cocta et cum alio crudo sumpta contra t⟨ae⟩n⟨i⟩as; nigrae radices in aqua coctae porriginem tollunt, atque in totum efficacior esse traditur nigra. sucus eius capitis dolores veteres et vertigines, item sonitum aurium sedat infusus iis. ciet urinam, medetur dysintericis iniecta et morbo regio, dolores quoque dentium sedat. inlitus sucus et contra serpentium ictus valet, sed h⟨o⟩c radici dumtaxat expressus. ipsa vero decocta pernionibus occurrit. alba epiphoras sedat fronti inlita, aluminis parvo admixto ignem sacrum sine oleo trita. sic et adustis medetur. et contra eruptiones papularum, coctaque eadem contra ulcera, quae serpunt, inlinitur, et alopeciis cruda et ulceribus, quae in capite manant. sucus eius cum melle naribus inditus caput purgat. coquitur et cum lenticula addito aceto, ut ventrem molliat. validius cocta fluctiones stomachi et ventris sistit.", "st": "20.27"}, {"sp": "N", "t": "Est et beta silvestris quam limonium vocant, alii neuroidem, multum minoribus foliis tenuioribusque ac densioribus; undecim saepe cauli u⟨ni⟩. huius folia ambustis utilia gustantium os adstringunt. semen acetabuli mensura dysintericis prodest. aqua betae radice decocta maculas vestium elui dicunt, item membranarum.", "st": "20.28"}, {"sp": "N", "t": "Intubi quoque non extra remedia sunt. sucus eorum cum rosaceo et aceto capitis dolores lenit idemque cum vino potus iocineris et vesicae; et epiphoris inponitur. erraticum apud nos quidam ambub⟨a⟩iam appellavere. in Aegypto cichorium vocant quod silvestre ⟨e⟩st, sativum autem serim, quod est minus et venosius.", "st": "20.29"}, {"sp": "N", "t": "Cichorium refrigerat in cib⟨o⟩ sumptum vel inlitum collectiones; sucus decocti ventrem solvit, iocineri et renibus et stomacho prodest. item, si in aceto decoquatur, urinae tormina discutit, item morbum regium e mulso, si sine febri sit. vesicam adiuvat. mulierum quidem purgationibus decoctum in aqua adeo prodest, ut emortuos partus trahat. adiciunt Magi suco totius cum oleo perunctos favorabiliores fieri et quae velint facilius impetrar⟨e⟩. quamqu⟨am⟩ idem propter singularem salubritatem aliqui chreston appellant, alii pancration.", "st": "20.30"}, {"sp": "N", "t": "Est et silvestre genus alterum—hedypnoida vocant—, latioris folii. stomachum dissolutum adstringit cocta, crudaque sistit alvum. et dysintericis prodest, magis cum lente. rupta et convulsa utroque genere iuvantur, item genitura quibus valetudinis morbo effluat.", "st": "20.31"}, {"sp": "N", "t": "Seris et ipsa, lactucae simillima, duorum generum est silvestris: melior nigra ⟨e⟩t aestiva, deterior hiberna et candidior. utraque amara, stomacho utilissima; praecipue quem umor vexet cum aceto in cibo refrigerant vel inlitae, discutiuntque et alios quam stomachi. cum polenta silvestrium radices stomachi causa sorbentur, et cardiacis inlinuntur super sinistram mammam et ex aceto. omnes hae et podagricis utiles et sanguinem reicientibus, item quibus genitura ef⟨f⟩luat, alterno dierum potu. Petronius Diodotus, qui ἀνθολογούμενα scripsit, in totum damnavit serim multis modis arguens, sed aliorum omnium opinio resistit.", "st": "20.32"}, {"sp": "N", "t": "Brassicae laudes longum est exsequi, cum et Chrysippus medicus privatim volumen ei dicaverit per singula membra hominis digestum et Dieuches, ante omnes autem Pythagoras, et Cato non parcius celebraverit, cius sententiam vel eo diligentius persequi par est, ut noscatur, qua medicina usus sit annis DC populus Romanus. in tres species divisere eam Graeci antiquissimi: crispam, quam selinada vocaverunt a similitudine apii foliorum, stomacho utilem, alvum modice mollientem; alteram heliam, latis foliis e caule exeuntibus, unde caulodem quidam vocavere, nullius in medicina momenti. tertia est proprie appellata crambe, tenuioribus foliis et simplicibus densissimisque, amarior, sed efficacissima. Cato crispam maxime probat, dein levem grandibus foliis, caule magno. prodesse tradit capitis doloribus, oculorum caligini scintillationique, stomacho, praecordiis crudam ex aceto ac melle, coriandro, ruta, menta, laseris radicula sumptam acetabulis duobus matutino, tantamque esse vim, ut qui terat haec, validiorem fieri se sentiat. ergo vel cum his tritam sorbendam vel ex hoc intinctu sumendam, podagrae autem morbisque articulariis inlini cum ruta ⟨et⟩ coriandro et salis mica e⟨t⟩ hordei farina; aqua quoque eius decocta nervos articulosque mire iuvari, si foveantur. vulnera et recentia et vetera, etiam carcinomata, quae nullis aliis medicamentis sanari possint, foveri prius calida aqua iubet ac bis die tritam inponi. sic etiam fistulas e⟨t⟩ luxata et tumores, quos evocari quosque discuti opus sit. insomnia etiam vigiliasque tollere decoctam, si ieiuni ed⟨i⟩nt quam plurimam ex oleo et sale; tormina, si decocta iterum decoquatur addito oleo, sale, cumino, polenta. si ita sumatur sine pane, magis profuturam. inter reliqua bilem detrahi per vinum nigrum pota. quin et urinam eius, qui brassicam esitaverit, adservari iubet, calefactamque nervis remedio esse. verba ipsius subiciam ad exprimendam sententiam: pueros pusillos, si laves ea urina, numquam debiles fieri. auribus quoque ex vino sucum brassicae tepidum instillari suadet idque etiam tarditati audientium prodesse adseverat, et inpetigines eadem sanari sine ulcere.", "st": "20.33"}, {"sp": "N", "t": "Graecorum quoque opiniones iam et Catonis causa poni convenit, in his dumtaxat, quae ille praetermiserit. biles trahere non percoctam putant, item alvum solvere eandemque bis coctam sistere. vino adversari ut inimicam vitibus, antecedente in cibis caveri ebrietatem, postea sumpta crapulam discuti. hunc cibum et oculorum claritati conferre multum, sucum vero crudae vel angulis tantum tactis cum Attico melle plurimum. facillime concoqui, ciboque eo sensus purgari. Erasistrati schola clamat nihil esse utilius stomacho nervisque, ideo paralyticis et tremulis dari iubet et sanguinem excreantibus. Hippocrates coeliacis et dysintericis bis coctam cum sale, item ad tenesmum et renium causa, lactis quoque ubertatem puerperis hoc cibo fieri iudicans et purgationem feminis. crudus quidem caulis si mandatur, partus quoque emortuos pelli. Apollodorus adversus fungorum venena semen aut sucum bibendum censet, Philistion opisthotonicis sucum ex lacte caprino cum sale et melle. invenio et podagra liberates edendo eam decoctaeque ius bibendo, hoc et cardiacis datum et comitialibus morbis addito sale, item splenicis in vino albo per dies XL et ictericis nec non et phreneticis. raucis crudae sucum gargarizandum bibendumque demonstrat, contra vero singultus cum coriandro et aneto et melle ac pipere ex aceto. inlitam quoque prodesse inflationibus stomachi, item serpentium ictibus et sordidis ulceribus ac vetustis, vel aqua ipsa cum hordeacia farina, sucum ex aceto vel cum feno Graeco. sic aliqui et articulis podagrisque inponunt. epinyctidas et, quidquid aliud serpit in corpore, inposita levat, item repentinas caligines, has et si mand⟨a⟩tur ex aceto; suggillata vero et alios livores pura inlita, lepras et psoras cum alumine rotundo ex aceto. sic e⟨t⟩ fluentes capillos retinet. Epicharmus testium et genitalium malis hanc utilissime inponi, efficacius eandem cum faba trita, item convolsis, cum ruta contra ardores febrium et stomachi vitia, cum rutae semine ad secundas et muris aranei morsus. foliorum aridorum farina alterutra parte exinanit.", "st": "20.34"}, {"sp": "N", "t": "Ex omnibus brassicae generibus suavissima est c⟨y⟩ma, ⟨a⟩t inutilis habetur, difficilis in coquendo et renibus contraria. illud quoque non est omittendum, aquam decoctae ad tot usus laudatam faetere humi effusam. stirpium brassicae aridorum cinis inter caustica intellegitur ad coxendicum dolores cum adipe vetusto, ac cum lasere et aceto inter psilotr⟨a⟩: evulsis inlitus pilis nasci alios prohibet. bibitur et cum oleo subfervefactus vel per se elixus ad convolsa et rupta intus lapsoque ex alto. nulla ergo sunt crimina brassicae? immo vero apud eosdem animae gravitatem facere, dentibus et gingivis nocere. et in Aegypto propter amaritudinem non est⟨ur⟩.", "st": "20.35"}, {"sp": "N", "t": "Silvestris sive erraticae inmenso plus effectus laudat Cato, adeo ut aridae quoque farinae in olfactorio collectae vel odore tantum naribus rapto vitia earum graveolentiamque sanari adfirmet. hanc alii petraeam vocant, inimicissimam vino, quam praecipue vitis fugiat aut, si non possit fugere, moriatur. folia habet⟨te⟩nuia, rotunda, parva, levia, plantis oleris similior, candidior sativa et hirsutior. hanc inflationibus mederi, melancholicis quoque ac vulneribus recentibus cum melle, ita ne solvatur ante diem septimum, strumis, fistulis in aqua contritam Chrysippus auctor est. alii vero conpescere mala corporis, quae serpant—nomas vocant—, item excrescentia absumere, cicatrices ad planum redigere, oris ulcera et tonsillas manducatam et coctam suco gargarizato cum melle tollere, item psoras et lepras veteres, ipsius tribus partibus cum duabus aluminis in aceto acri inlitis. Epicharmus satis esse eam contra canis rabiosi morsum inponi; melius, si cum lasere et aceto acri; necari quoque canes ea, si detur ex carne. semen eius tostum auxiliatur contra serpentes,fungos, tauri sanguinem. folia cocta splenicis in cibo data et cruda inlita cum sulpure et nitro prosunt, item mammarum duritiae. radicum cinis uvae in faucibus tumenti tactu medetur et parotidas cum melle inlitus reprimit, serpentium morsus sanat. virium brassicae unum et magnum argumentum addemus a⟨c⟩ mirabile: crustae occupent intus vasa omnia, in quis aquae fervent, i⟨ta⟩ ut non sit avellere eas; si brassica in his decoquatur, abscedunt.", "st": "20.36"}, {"sp": "N", "t": "Inter silvestres brassicas et lapsana est, pedalis altitudine, hirsutis foliis, sinapi similis, nisi candidior esset flore. coquitur in cibo, alvum lenite⟨r⟩ mollit.", "st": "20.37"}, {"sp": "N", "t": "Marina brassica vehementissime ex omnibus alvum ciet. coquitur propter acrimoniam cum pingui carne, stomacho inimicissima.", "st": "20.38"}, {"sp": "N", "t": "Scillarum in medicina albae ⟨e⟩t feminae nigrae; quae candidissima fuerit, utilissima erit. huic aridis tunicis direptis quod relicum e vivo est, consectum suspenditur lino modicis intervallis. postea arida frusta in cadum aceti quam asperrimi pendentia inmerguntur, ita ne ulla parte vas contingant. *gypso deinde oblitus cadus ponitur sub tegulis totius diei solem accipientibus. *hoc fit ante solstitium, diebus XLVIII*. post eum numerum dierum tollitur vas, scilla eximitur, acetum transfunditur. hoc clariorem oculorum aciem facit, salutare est stomachi, laterum doloribus ⟨ie⟩i⟨u⟩nis sumptum. sed tanta vis est, ut avidius haustum exstinctae animae momento aliquo speciem praebeat. prodest et gingivis et dentibus vel per se commanducata. taenias et reliqua ventris animalia pellit ex aceto et melle sumpta. linguae quoque recens subiecta praestat, ne hydropici sitiant. coquitur pluribus modis: in olla, quae coiciatur in clibanum aut furnum, vel adipe aut luto inlita, v⟨el⟩ frustatim in patinis. et cruda siccatur, deinde conciditur coquiturque in aceto, cum serpentium ictibus inponitur. tosta quoque purgatur et medium eius iterum in aqua coquitur. usus sic coctae ad hydropicos, ad urinam ciendam tribus obolis cum melle et aceto potae, item splenicos et stomachicos, si non sentiant ulcus, quibus innatet cibus, ad tormina, regios morbos, tussim veterem cum suspirio. discutit et foliis strumas quadrinis diebus soluta, furfures capitis et ulcera manantia inlita ex oleo cocta. coquitur et in melle cibi gratia, maxime uti ⟨con⟩coctionem faciat. sic et interiora purgat. rimas pedum sanat in oleo cocta et mixta resinae. semen eius lumborum dolori ex melle inponitur. Pythagoras scillam in limine quoque ianuae suspensam contra malorum medicamentorum introitum p⟨o⟩llere tradit.", "st": "20.39"}, {"sp": "N", "t": "Ceteri bulbi ex aceto et sulpure ulceribus in facie medentur, per se vero triti nervorum contraction⟨i⟩ et ex vino porrigini, cum melle canum morsibus; Erasistrato placet cum pice. idem sanguinem sistere eos tradit inlitos cum melle. alii, si e naribus fluat, coriandrum et farinam adiciunt. Theodorus et lichenas ex aceto bulbis curat, erumpentia in capite cum vino austero aut ovo. et bulbos epiphoris idem inlinit et sicc⟨a⟩e lippitudini media eorum. vitia, quae sunt in facie, rubentes maxime in sole inliti cum melle et nitro emendant, lentiginem cum vino aut cum ⟨a⟩c⟨e⟩to. vulneribus quoque mire prosunt per se aut, ut Damion, ex mulso, si quinto die solvantur. iisdem et auriculas fractas curat et testium pituitas; in articulorum doloribus misce⟨t⟩ et farinam. in vino cocti inliti ventri duritiam praecordiorum emolliunt. dysintericis in vino e⟨x⟩ aqua caelesti temperate dantur, ad convulsa intus cum silphio pilulis fabae magnitudine. ad sudorem tusi inlinuntur. nervis utiles, ideo et paralyticis dantur.⟨l⟩ux⟨a⟩ta in pedibus, qui sunt rufi ex iis, citissime sanant cum melle et sale. venerem maxime Megarici stimulant, hortensii partum cum sapa aut passo sumpti, silvestres interaneorum plagas et vitia cum silphio pilulis devoratis sedant. ⟨ill⟩orum semen contra phalangia bibitur in vino. ipsi ex aceto inlinuntur contra serpentium ictus. semen antiqui bibendum insanientibus dabant. flos bulborum tritus crurum maculas varietatesque igni factas emendat. Diocles hebetari oculos ab his putat. elixos assis minus utiles esse adicit et difficile concoqui ex vi uniuscuiusque naturae.", "st": "20.40"}, {"sp": "N", "t": "B⟨o⟩lbine⟨n⟩ Graeci vocant herbam porraceis foliis, rubicundo bulbo. haec traditur vulneribus mire utilis, dumtaxat recentibus. bulbus, quem vomitorium vocant ab effectu, folia habet nigra, ceteris longiora.", "st": "20.41"}, {"sp": "N", "t": "Inter utilissimos stomacho cibos asparagi traduntur. cumino quidem addito inflationes stomachi colique discutiunt, iidem oculis claritatem adferunt, ventrem leniter molliunt, pectoris et spinae doloribus intestinorumque vitiis prosunt, vino, cum coquuntur, addito. ad lumborum et renium dolores semen obolorum trium pondere, pari cumini bibitur. venerem stimulant, urinam cient utilissime, praeterquam vesica exulcerata, radice quoque plurimorum praedicatione. trita et in vino albo pota calculos quoque exturbat, lumborum et renium dolores sedat. quidam et ad vulvae dolorem radicem cum vino dulci propinant. eadem in aceto decocta contra elephantiasim proficit. asparago trito ex oleo perunctum pungi ab apibus negant.", "st": "20.42"}, {"sp": "N", "t": "Silvestrem asparagum aliqui Libycum vocant, Attici orminum. huius ad supra dicta omnia efficacior vis, et candidiori maior. morbum regium extenuant. veneris causa aquam eorum decoctam bibi iubent ad heminam. idem et semen valet cum aneto ternis utriusque obolis. datur et ad serpentium ictus sucus decoctus; radix miscetur radici marathri inter efficacissima auxilia. si sanguis per urinam reddatur, semen et asparagi et apii et cumini ternis obolis in vini ⟨cyath⟩is duobus Chrysippus dari iubet. set i⟨d⟩ hydropicis contrarium esse, quamvis urinam moveat, docet, item veneri, vesicae quoque nisi decoctum; quae aqua si canibus detur, occidi eos. in vino decoctae radicis sucum, si ore contineatur, dentibus mederi.", "st": "20.43"}, {"sp": "N", "t": "Apio gratia in volgo est. namque rami lactis potionibus per rura innatant et in condimentis peculiarem gratiam habent. praeterea oculis inlitum cum melle, ita ut subinde foveantur ferventi suco decocti, aliisque membrorum epiphoris per se tritum aut cum pane vel polenta inpositum mire auxiliatur. pisces quoque, si aegrotent in piscinis, apio viridi recreantur. verum apud eruditos non aliud erutum terra in maiore sententiarum varietate est. distinguitur sexu. Chrysippus feminam esse dicit crispioribus foliis et duris, crasso caule, sapore acri et fervido; Dionysius… nigriorem, brevem, radicis …, vermiculos gignentem; ambo neutrum ad cibos admittendum, immo omnino nefas, namque id defunctorum epulis feralibus dicatum esse—visus quoque claritati inimicum —[caule feminae vermiculos gigni] ideoque eos, qui ederint, sterilescere, mares feminasve; in puerperiis vero ab eo cibo comitiales fieri qui ubera hauri⟨a⟩nt; innocentiorem tamen esse marem. eaque causa est, ne inter nefastos frutex damnetur. mammarum duritiam inpositis foliis emollit. suaviores aquas potui incoctum praestat. suco maxime radicis cum vino lumborum dolores mitigat, eodem iure instillato gravitatem aurium. semine urinam ciet, menstrua ac secundas partus et si foveantur semine decocto. suggillata reddit colori cum ovi albo inlitum. at ex aqua coctum potumque renibus medetur, in frigida tritum oris ulceribus. semen cum vino vel radix cum veter⟨e⟩ vino vesicae calculos frangunt. semen datur et arquatis ex vino albo.", "st": "20.44"}, {"sp": "N", "t": "Apiastrum Hyginus quidem melissop⟨h⟩yl⟨l⟩um appellat, sed in confessa damnatione est venenatum in Sardinia. contexenda enim sunt omnia ex eodem nomine apud Graecos pendentia.", "st": "20.45"}, {"sp": "N", "t": "Olusatrum, quod hipposelinum vocant, adversatur scorpionibus. poto semine torminibus et interaneis medetur; i⟨t⟩em difficultatibus urinae semen eius decoctum ex mulso potum. radix in vino decocta calculos pellit et lumborum ac lateris dolores. canis rabiosi morsibus potum et inlitum medetur. sucus eius algentes calefacit potus. quartum genus ex eodem aliqui faciunt oreoselinum, palmum al⟨t⟩o frutice recto, semine cumino simili, urinae et menstruis efficax. heleoselino vis privata contra araneos; e⟨o⟩ et oreoselino feminae purgantur e vino.", "st": "20.46"}, {"sp": "N", "t": "Alio genere petroselinum quidam appellant in saxis natum, praecipuum ad vomicas, coclearibus binis suci additis in cyathum marrubii suc⟨i⟩ atque ita calidae aquae tribus cyathis. adiecere quidam buselinum, differens brevitate caulis a sativo et radicis colore rufo, eiusdem effectus, praevalere contra serpentes potu et inlitu.", "st": "20.47"}, {"sp": "N", "t": "Ocimum quoque Chrysippus graviter increpuit inutile stomacho, urinae, oculorum quoque claritati, praeterea insaniam facere et lethargos et iocineris vitia, ideoque capras id aspernari, hominibus quoque fugiendum censens. addunt quidam tritum, si operiatur lapide, scorpionem gignere, commanducatum et in sole positum vermes; Afri vero, si eo die feriatur quispiam a scorpione, quo ederit ocimum, non posse servari. quin immo tradunt aliqui, manipulo ocimi cum cancris x marinis vel fluviatilibus trito convenire ad id scorpiones ex proximo omnes. Diodorus in empiricis etiam pediculos facere ocimi cibum. secuta aetas acriter defendit, nam id esse capras, nec cuiquam mentem motam, et scorpionum terrestrium ictibus marinorumque veneis mederi ex vino addito aceti exiguo. usu quoque conpertum deficientibus ex aceto odoratu salutare esse, item lethargicis et inflammatis refrigeration⟨e⟩, inlitum capitis doloribus cum rosaceo aut myrteo ⟨e⟩t aceto, item oculorum epiphoris inpositum ex vino. stomacho quoque utile, inflationes ructu dissolvere ex aceto sumptum, alvum sistere inpositum, urinam ciere; sic et morbo regio et hydropicis prodesse, etiam in choleris destillationes stomachi inhiberi. ergo etiam coeliacis Philistio dedit et coctum dysintericis, et contra… Plistonicu⟨s⟩, aliqui et in tenesmo et sanguinem excreantibus in vino, duritia quoque praecordiorum. inlinitur mammis exin⟨an⟩itque lactis proventum. auribus utilissimum infantium, praecipue cum adipe anserino. semen tritum et ⟨h⟩au⟨s⟩tum naribus sternumenta⟨c⟩om⟨p⟩e⟨sci⟩t et destillationes quoque capitis inlitum, vulvas purgat in cibo ex aceto. verrucas mixto atramento sutorio tollit. venerem stimulat, ideo etiam equis asinisque admissurae tempore ingeritur.", "st": "20.48"}, {"sp": "N", "t": "Silvestri ocimo vis efficacior ad eadem omnia, peculiaris ad vitia, quae vomitionibus crebris contrahuntur, vomicasque volvae, contra bestiarum morsus e vino radice efficacissima.", "st": "20.48"}, {"sp": "N", "t": "Erucae semen scorpionum venenis et muris aranei medetur, bestiolas omnes innascentes corpori arcet, vitia cutis in facie cum melle inlitum, lentigines ex aceto, cicatrices nigras reducit ad candorem cum felle bubulo. aiunt verbera subituris potum ex vino duritiam quandam contra ea sensus induere. in condiendis opsoniis tanta est suavitas, ut Graeci euzomon appellaverint. putant, subtrita eruca si foveantur oculi, claritatem restitui,… tussim infantium sedari. radix eius in aqua decocta fracta ossa extrahit…—nam de venere stimulanda diximus— tria folia silvestris erucae sinistra manu decerpta et trita in aqua mulsa si bibantur.", "st": "20.49"}, {"sp": "N", "t": "E contrario nasturtium venerem inhibet, animum exacuit, ut diximus. duo eius genera. alvum purgat, detrahit bilem potum X̅ pondere in aquae VII, strumis cum lomento inlitum opertumque brassica praeclare medetur. alterum est nigrius, quod capitis vitia purgat [visum compurgat], commotas mentes sedat ex aceto sumptum, lienem ex vino potum vel cum fico sumptum, tussim, ex melle si cotidie ieiuni sumant. semen ex vino omnia intestinorum animalia pellit, efficacius addito mentastro. prodest et contra suspiria et tussim cum origano et vino dulci, pectoris doloribus decoctum in lacte caprino. panos discutit cum pice extrahitque corpori aculeos et maculas inlitum ex aceto; contra carcinomata adicitur ovorum album. et lienibus inlinitur ex aceto, infantibus vero e melle utilissime. Sextius adicit ustum serpentes fugare, scorpionibus resistere, capitis dolores contrit⟨o⟩, alopecias emendari addito sinapi, gravitatem aurium trito inposito auribus cum fico, dentium dolores infuso in aures suco, porriginem et ulcera capitis cum adipe anserino. furunculos concoquit cum fermento. carbunculos ad suppurationem perducit et rumpit, phagedaenas ulcerum expurgat cum melle. coxendicibus et lumbis cum polenta ex aceto inlinitur, item licheni, unguibus scabris, quippe natura eius caustica est. optimum autem Babylonium; silvestr⟨i⟩ ad omnia ea effectus maior.", "st": "20.50"}, {"sp": "N", "t": "In praecipuis autem medicaminibus ruta est. latiora sativae folia, rami fruticosiores; silvestris horrida ad effectum est et ad omnia acrior. sucus exprimitur tunsae aspersa modice aqua et in pyxide Cypria adservatur. hic copiosior datus veneni noxiam obtinet, in Macedonia maxime iuxta flumen A⟨li⟩acm⟨one⟩m; mirumque, cicutae suco extinguitur: adeo etiam venenorum venena sunt. cicutae sucus prodest et manibus colligentium rutam. cetero inter prima miscetur antidotis, praecipueque Galatica; quaecumque autem ruta ⟨e⟩t per se pro antidoto valet foliis tritis ex vino sumptis, contra aconitum maxime et viscum, item fungos sive in potu detur sive in cibo; simili modo contra serpentium ictus, utpote cum mustelae dimicaturae cum his rutam prius edendo muniant se. valent et contra scorpionum et contra araneorum, apium, crabronum, vesparum aculeos et cantharidas ac salamandras canisve rabiosi morsus. acetabuli mensura sucus e vino bibitur, et folia trita vel commanducata inponuntur cum melle ac sale vel cum aceto et pice decocta. suco perunctos, etiam habentes negant feriri ab his maleficis, serpentesque, si uratur ruta, nidorem fugere. efficacissima tamen est silvestris radix cum vino sumpta; eandem adiciunt efficaciorem esse sub diu potam.", "st": "20.51"}, {"sp": "N", "t": "Pythagoras et in hac marem minoribus herbaceique coloris foliis a femina discrevit, et eam laetioribus foliis et colore. idem oculis noxiam putavit; falsum, quoniam scalptores et pictores hoc cibo utuntur oculorum causa cum pane vel nasturtio, caprae quoque silvestres propter visum, ut aiunt. multi suco eius cum melle Attico inuncti discusserunt caligines vel cum lacte mulieris puerum enixae vel puro suco angulis oculorum tactis. epiphoras cum polenta inposita lenit; item capitis dolores pota cum vino aut cum aceto et rosaceo inlita, si vero sit cephalaea, cum farina hordeacia et aceto. eadem cruditates discutit, mox et inflationes, dolores stomachi veteres. vulvas aperit corrigitque conversas inlita in melle toto ventre et pectore; hydropicis cum fico et decocta ad dimidias partes potaque ex vino. sic bibitur et ad pectoris dolores laterumque et lumborum, tusses, suspiria, pulmonum, iocinerum, renium vitia, horrores frigidos, crapulae gravedines. decocuntur folia poturis; et in cibo vel cruda vel decoctaaut condita prodest; item torminibus in hysopo decocta et cum vino ⟨p⟩ota. sic et sanguinem sistit interiorem et narium indita ⟨i⟩is; sic et conlutis dentibus prodest. auribus quoque in dolore sucus infunditur, custodito ut diximus, modo in silvestri, contra tarditatem vero sonitusque cum rosaceo vel cum laureo oleo aut cum vino et melle. sucus et phreneticis ex aceto tritae instillatur in tempora et cerebrum. adiecerunt aliqui et serpyllum et laurum, inlinentes capita et colla. dederunt et lethargicis ex aceto olfaciendum e⟨t⟩ comitialibus bibendum decoctae sucum in cyathis IIII; ante accessiones, quarum frigus intolerabile est, alsiosisque et crudam in cibo. urinam quoque vel cruentam pellit, feminarum etiam purgationes secundasque et iam emortuos partus, ut Hippocrati videtur, ex vino dulci nigro pota. itaque inlitam et vulvarum causa et suffire iubet. Diodes et cardiacis inponit ex aceto et melle cum farina hordeacia et contra ileum decocta farina in oleo velleribus collecta. multi vero et contra purulentas excreationes siccae drachmas duas, sulpuris unam et dimidiam sumi censent, et contra cruentas ramos III decoctos in vino. datur et dysintericis cum caseo in vino contrita. dederunt et cum bitumine infriatam potioni propter anhelitum, ex alto lapsis seminis III uncias olei libra vinique sextario. inlinitur cum oleo coctis foliis partibus, quas frigus adusserit. si urinam movet, ut Hippocrati videtur, mirum est, quosdam dare vel⟨ut⟩ inhibentem potui contra incontinentiam urinae. psoras et lepras cum melle et alumine inlita emendat, item vitiligines, verrucas, strumas et similia cum try⟨ch⟩no et adipe suillo ac taurino sebo, ignem sacrum ex aceto et oleo vel psimithio, carbunculum ex aceto; nonnulli laserpicium una inlini iubent, sine quo epinyctidas pusulas curant. inponunt et mammis turgentibus decoctam et pituitae eruptionibus cum cera, testium vero epiphoris cum ramis lauri teneris, adeo peculiari in visceribus his effectu, ut silvestri ruta cum axungia vetere inlitos ramices sanari prodant, fracta quoque membra semine trito cum cera inposito. radix rutae sanguinem oculis suffusum et toto corpore cicatrices aut maculas inlita emendat. ex reliquis, quae traduntur, mirum est, cum ferventem rutae naturam esse conveniat, fasciculum eius in rosaceo decoctum addita aloes uncia perunctis sudorem reprimere, itemque generationem inpediri hoc cibo. ideo in profluvio genitali datur et venerem crebro per somnia imaginantibus. praecavendum est gravidis abstineant hoc cibo, necari enim partus invenio. eadem ex omnibus satis quadripedum quoque morbis in maximo usu est, sive difficile spirantibus sive contra maleficorum animalium ictus, infusa per nares ex vino aut, si sanguisugam hauserint, ex aceto et quocumque in simili morborum genere, ut in homine, temperat⟨a⟩.", "st": "20.51"}, {"sp": "N", "t": "Mentastrum silvestris menta est, differens specie foliorum, quae stunt figura ocimi, pulei o⟨d⟩ore, propter quod quidam silvestre puleium vocant. his commanducatis et inpositis sanari elephantiasin Magni Pompei aetate fortuito cuiusdam experimento, propter pudorem facie inlita, conpertum est. eadem inlinuntur bibunturque adversus serpentium ictus drachmis duabus in vini cyathis duobus, adversus scorpionum cum sale, oleo, aceto, item adversus scolopendras ius decocti. adversus omnia venena servantur folia arida ad farinae modum. substratum vel accensum fugat etiam scorpiones. potum feminas purgat, sed partus necat. ruptis, convulsis, orthopnoicis, torminibus, choleris efficacissimum, item lumbis, podagris inpositum. sucus auribus verminosis instillatur. in regio morbo bibitur, strumis inlinitur, somnia veneris inhibet, t⟨ae⟩n⟨i⟩as pellit ex aceto potum, contra porriginem ex aceto infunditur capiti in sole.", "st": "20.52"}, {"sp": "N", "t": "Mentae ipsius odor animum excitat et sapor aviditatem in cibis, ideo embammatum mixturae familiaris. ipsa acescere aut coire dens⟨a⟩rique lac non patitur; quare lactis potionibus additur, et his, qui coagulati potu strangulentur, data in aqua aut mulso. eadem vi resistere et generationi creditur cohibendo genitalia densari. aeque maribus ac feminis sistit sanguinem et purgationes feminarum inhibet, cum amylo ex aqua pota coeliacorum impetus. ⟨exulc⟩erationem et vomicas vulvae cura⟨n⟩t ill⟨it⟩a, iocinerum vitia ternis obolis ex mulso datis, item sanguinem excreantibus in sorbitione. ulcera in capite infantium mire sanat, arterias umidas siccat, siccas adstringit, pituitas corruptas purgat in mulso et aqua. voci suco utilis, sub certamine dumtaxat, qui et gargarizatur uva tumente adiecta ruta et coriandro ex lacte; utilis et contra tonsillas cum alumine, linguae asperae cum melle et convulsis intus per se vitiisque pulmonis. singultus et vomitiones sistit cum suco granati, ut Democritus monstrat. recentis sucus narium vitia spiritu subductus emendat; ipsa trita choleras, in aceto quidem pota, sanguinis fluctiones intus, ileum etiam inposita cum polenta et si mammae tendantur. inlinitur et temporibus in capitis dolore, sumitur et contra scolopendras et scorpiones marinos et ad serpentes. epiphoris inlinitur et omnibus in capite eruptionibus, item sedis vitiis. intertrigines quoque, vel si teneatur tantum, prohibet. auribus instillatur cum mulso. aiunt et lieni mederi eam in horto gustatam ita, ne vellatur, si is, qui mordeat, dicat se lieni mederi, per dies VIII; aridae quoque farinam tribus digitis adprehensam et stomachi dolorem sedare in aqua et similiter aspersa potione ventris animalia expellere.", "st": "20.53"}, {"sp": "N", "t": "Magna societas cum hac ad recreandos defectos animo puleio, cum surculis suis in ampullas vitreas aceti utrisque deiectis. qua de causa dignior e puleio corona Varroni quam e rosa cubiculis nostris pronuntiata est; nam et capitis dolores inposita dicitur levare, quin et olfactu capita tueri contra frigorum aestusque iniuriam et ab siti traditur, neque aestuare eos, qui duos e puleio surculos inpositos auribus in sole habeant. inlinitur etiam in doloribus cum polenta et aceto, femina efficacius. est autem haec flore purpureo, mas candidum habet. i⟨tem⟩ nausias cum sale et polenta in frigida aqua pota inhibet; sic et pectoris dolorem, stomachi autem ex aqua. item rosiones sistit et vomitiones cum aceto et polenta, alvum solvit ex sale et aceto et polenta. intestinorum vitia melle decocta et nitro sanat, urinam pellit ex vino et, si Ammineum sit, et calculos et interiores omnes dolores. ex melle et aceto sedat menstrua et secundas, vulvas conversas corrigit, defunctos partus eicit. semen obmutescentibus olfactu admovetur. comitialibus in aceto cyathi mensura datur. si aquae insalubres bibendae sint, tritum aspergitur. lassitudines corporis, si omnino tractetur, minuit, nervorum causa et in contractione cum sale et aceto, e melle infricatur in opisthotono. bibitur ad serpentium ictus decoctum, ad scorpionum in vino tritum, maxime quod in siccis nascitur. ad oris exulcerationes, ad tussim efficax habetur. flos recentis incensus pulices necat odore. Xenocrates pulei ramum lana involutum in tertianis ante accessionem olfactandum dari aut stragulis subici et ita collocari aegrum inter remedia tradit.", "st": "20.54"}, {"sp": "N", "t": "Silvestri ad eadem vis efficacior. simile est origano, minoribus foliis quam sativum, et a quibusdam dictamnos vocatur. gustatum a pecore caprisque balatum concitat, unde quidam Graeci ittera mutata blechonem vocaverunt. natura tam fervens est, ut inlitas partes exulceret. tuso in perfrictione fricari ante balinea convenit et ante accessionum horrorem. convolsis et torminibus, podagris mire prodest, spasticis cum melle et sale bibendum datur, pulmonum vitia excreabilia facit. ad lienem cum sale utile est et vesicae et suspiriis et inflationibus; decoctum suco aequaliter et vulvas corrigit et contra scolopendram terrestrem vel marinam, item scorpiones valet privatim⟨q⟩ue contra hominis morsum. radix contra increscentia ulcera recens potentissima, arida vero cicatricibus decorem adfert.", "st": "20.55"}, {"sp": "N", "t": "Item puleio est nepetaeque societas. decocta in aqua ad tertias discutiunt frigora [mulierumque menstruis prodest] et aestate sedant calores. nepeta quoque vires contra serpentes habet; fumum ex ea nidoremque fugiunt, quin et substernere in metu eo dormituris utile est. tusa aegilopis inponitur et capitis doloribus recens cum tertia parte panis temperata aceto inlinitur. sucus eius instillatus naribus supinis profluvium sanguinis sistit; item radix, quae cum myrti semine in passo tepido gargarizata anginis medetur.", "st": "20.56"}, {"sp": "N", "t": "Cuminum est et silvestre, praetenue, quaternis aut quinis foliis veluti serratis, sed ut sativo magnus usus, in stomachi praecipue remediis. discutit pituitas, inflationes tritum et cum pane sumptum vel potum ex aqua vinoque, tormina quoque et intestinorum dolores. verumtamen omne pallorem gignit bibentibus. ita certe ferunt Porci Latronis, clari inter magistros dicendi, adsectatores similitudinem coloris studiis contracti imitatos, et paulo ante Iulium Vindicem, adsertorem illum a Nerone libertatis, captation⟨i⟩ testamenti sic lenocinatum. narium sanguinem pastillis inditum vel ex aceto recens sistit, et oculorum epiphoris per se inpositum, tumentibus cum melle prodest. infantibus inponi in ventre satis est. morbo regio in vino albo a balineis datur;", "st": "20.57"}, {"sp": "N", "t": "… is Aethiopicum maxime in posca et in ⟨ec⟩ligmate cum melle. Africano privatim urinae incontinentiam cohiberi putant. sativum datur ad iocineris vitia tostum tritum in aceto, item ad vertiginem, iis vero, quos acrior urina mordeat, in dulci tritum, ad vulvarum vitia in vino praeterque inpositis vellere foliis, testium tumoribus tostum tritumque cum melle aut cum rosaceo et cera. silvestre ad omnia eadem efficacius, praeterea ad serpentes cum oleo, ad scorpiones, scolopendras. sistit et vomitionem nausiasque ex vino quantum adprehenderint tres digiti. propter colum qu⟨o⟩que bibitur inliniturque in penicillo fervens, adprimitur fasciis. strangulationes vulvae potum in vino aperit tribus drachmis in tribus cyathis vini. auribus instillatur ad sonitus atque tinnitus cum sebo vitulino vel melle. suggillatis inlinitur cum melle et uva passa et aceto, lentigini nigrae ex aceto.", "st": "20.57"}, {"sp": "N", "t": "Est cumino simillimum quod Graeci vocant ami. quidam vero Aethiopicum cuminum id esse existimant. Hippocrates regium appellavit, videlicet quia efficacius Aegyptio iudicavit. plerique alterius naturae in totum putant, quoniam sit exilius et candidius. similis autem et huic usus. namque et panibus Alexandrinis subditur et condimentis interponitur. inflationes et tormina discutit, urinas et menstrua ciet, suggillata oculorum, epiphoras mitigat, cum lini semine scorpionum ictus in vino potum drachmis duabus privatimque cerastarum cum pari portione myrrae. colorem quoque bibentium similiter mutat in pallorem. suffitum cum uva passa aut resina vulvam purgat. tradunt facilius concipere eas, quae odorentur id per coitum.", "st": "20.58"}, {"sp": "N", "t": "De cappari satis diximus inter peregrinos frutices. non utendum transmarino, innocentius est Italicum. ferunt eos, qui cotidie id ed⟨i⟩nt, paralysi non periclitari nec lienis doloribus. radix eius vitiligines albas tollit, si trita in sole fricentur. splenicis prodes⟨t⟩ in vino potus radicis cortex duabus drachmis, dempto balinearum usu, feruntque xxxv diebus per urinam et alvum totum lienem emitti. bibitur in lumborum doloribus ac paralysi. dentium dolores sedat tritum ex a⟨c⟩eto vel semen decoctum vel manducata radix. infunditur et aurium dolori decoctum oleo. ulcera, quae phagedaenas vocant, folia et radix recens cum melle sanant. sic et strumas discutit radix, parotidas vermiculosque cocta in aqua. iocineris doloribus tusa cum farina hordeacia inponitur. vesicae quoque malis medetur. dant et ad taenias in aceto et melle. oris exulcerationes in aceto decocta tollit. stomacho inutile esse inter auctores convenit.", "st": "20.59"}, {"sp": "N", "t": "Ligusticum—aliqui panaces vocant—stomacho utile est, item convolsionibus, inflationibus. sunt qui et cunilam bubulam appellaverint, uti diximus, falso.", "st": "20.60"}, {"sp": "N", "t": "Cunilae praeter sativam plura sunt in medicina genera. quae bubula appellatur, semen pulei habet, utile ad vulnera commanducatum inpositum, ut quinto post die solvatur. et contra serpentes in vino bibitur ac tritum plagae inponitur. vulnera ab his facta perfricant, item testudines cum serpentibus pugnaturae; quidamque in hoc usu panaceam vocant. sedat et tumores et virilium mala sicca vel foliis tritis, in omni usu mire congruens vino.", "st": "20.61"}, {"sp": "N", "t": "Est alia cunila, gallinacea appellata nostris, Graecis origanum Heracleoticum. prodest oculis trita addito sale; tussim quoque emendat et iocinerum vitia, laterum dolores cum farina, oleo et aceto sorbitione temperata, praecipue vero serpentium morsus.", "st": "20.62"}, {"sp": "N", "t": "Tertium genus est eius, quae a Graecis mascula, a nostris cunilago vocatur, odoris foedi, radicis lignosae, folio aspero. vires eius vehementissimas in omnibus generibus earum tradunt; manipulo quoque eius abiecto omnes e tota domo blattas convenire ad earn, privatim adversus scorpiones ex posca pollere, foliis tribus ex oleo peruncto homine fugari serpentes.", "st": "20.63"}, {"sp": "N", "t": "E contrario quae mollis vocatur, pilosioribus ramis et aculeatis, trita mellis odorem habet, digitis tactu eius cohaerescentibus, altera turis, quam libanotida appellavimus. medetur utraque contra serpentes ex vino vel aceto, pulices etiam contritae cum aqua sparsae necant.", "st": "20.64"}, {"sp": "N", "t": "Sativa quoque suos usus habet. sucus eius cum rosaceo auriculas iuvat, ipsa ad ictus bibitur. fit ex ea montana, serpyllo similis, efficax contra serpentes. urinam movet, purgat a partu mulieres. concoctionem mire adiuvat et aviditatem ad cibos utraque vel in cruditate ieiunis in potione aspersa; luxatis quoque utilis, contra vesparum et similes ictus ex farina hordeacia et posca utilissima. libanotidis alia genera suis locis dicentur.", "st": "20.65"}, {"sp": "N", "t": "Piperitis, quam et siliquastrum appellavimus, contra morbos comitiales bibitur. Castor et aliter demonstrabat: caule rubro et longo, densis geniculis, foliis lauri, semine albo, tenui, gustu piperis, utilem gingivis, dentibus, oris suavitati et ructibus.", "st": "20.66"}, {"sp": "N", "t": "Origanum, quod ⟨v⟩i sapore⟨m⟩ cunilae aemulatur, ut diximus, plura genera in medicina habet. onitin ali⟨i⟩ prasion appellant, non dissimile hysopo. privatim eius usus contra rosiones stomachi in tepida aqua et contra cruditates, aran⟨eo⟩s scorpionesque in vino albo, luxata et incussa in aceto et oleo et lana.", "st": "20.67"}, {"sp": "N", "t": "Tragoriganum similius est serpyllo silvestri. urinam ciet, tumores discutit, contra viscum potum viperaeque ictum efficacissimum, stomacho acida ru⟨c⟩tanti et praecordiis. tussientibus quoque cum melle datur et pleuriticis et perip⟨n⟩eumonicis.", "st": "20.68"}, {"sp": "N", "t": "Heraclium quoque tria genera habet: nigrius latioribus foliis, glutinosum, alterum exilioribus, mollius, sampsucho non dissimile, quod aliqui prasion vocare malunt. tertium est inter haec medium, set minus quam cetera efficax. optimum autem Creticum, nam et iucunde olet, proximum Zmyrnaeum d⟨u⟩rius, Heracleoticum ad potum utilius, quod onitin vocant. communis autem usus serpentes fugare, percussis esui dar⟨i⟩ et decoctum potui, urinam ciere, ruptis, convolsis mederi cum panacis radice, hydropicis cum fico aut cum hysopo acetabuli mensuris decoctum ad sextam; item ad scabiem, pruriginem, psoras in descensione balinearum. sucus auribus infunditur cum lacte mulieris. tonsillis quoque et uvis medetur, capitis ulceribus. venena opii et gypsi extinguit decoctum, si cum cinere e vino bibatur. alvum mollit acetabuli mensura, suggillatis inlinitur, item dentium dolori, quibus et candorem facit, cum melle et nitro. sanguinem narium sistit. ad parotidas decoquitur cum hordeacia farina, ad arterias asperas cum galla et melle teritur, ad lienem folia cum melle et sale. crassiores pituitas et nigras extenuat coctum cum aceto et sale sumptum paulatim. regio morbo tritum cum oleo in nares infunditur. lassi perunguuntur ex eo ita, ⟨n⟩e venter attingatur. epinyctidas cum pice sanat, furunculos aperit cum fico tosta, strumas cum oleo et aceto et farina hordeacia, lateris dolores cum fico inlitum, fluctiones sanguinis in genitalibus tusum ex aceto inlitum, reliquias purgationum a partu.", "st": "20.69"}, {"sp": "N", "t": "Lepidium inter urentia intellegitur. sic et in facie cutem emendat exulcerando, ut tamen cera et rosaceo facile sanetur. sic et lepras et psoras tollit semper facile et cicatricum ulcera. tradunt in dolore dentium adalligatum bracchio, qua doleat, convertere dolorem.", "st": "20.70"}, {"sp": "N", "t": "Git ex Graecis alii melanthium, alii melaspermon vocant. optimum quam excitatissimi odoris et quam nigerrimum. medetur serpentium plagis et scorpionum; inlini ex aceto ac melle reperio incensoque serpentes fugari. bibitur drachma una et contra araneos. destillationem narium discutit tusum in linteolo olefactum, capitis dolores inlitum ex aceto, et infusum naribus cum irino oculorum epiphoras et tumores, dentium dolores coctum cum aceto, ulcera oris tritum aut commanducatum; item lepras et lentigines ex aceto, difficultates spirandi addito nitro potum, duritias tumoresque veteres et suppurationes inlitum. lacte mulierum auget aliquot continuis diebus sumptur. colligitur sucus eius ut hyoscyami similiterque largior venenum est, quod miremur, cum semen gratissime panes etiam condiat. oculos quoque purgat, urinam et menses ciet. quin immo linteolo deligatis tantum granis xxx secundas trahi reperio. aiunt et clavis in pedibus mederi tritum in urina, culices suffitu necare, item muscas.", "st": "20.71"}, {"sp": "N", "t": "Et anesum adversus scorpiones ex vino habetur, Pythagorae inter pauca laudatum sive crudum sive decoctum; item viride aridumve omnibus, quae condiuntur quaeque intinguntur, desideratum, panis etiam crustis inferioribus subditum. saccis quoque additum cum amaris nucibus vina commendat. quin ipsum oris halitum iucundiorem facit faetoremque tollit manducatum matutinis cum zmyrnio et melle exiguo, mox vino collutum. vultum iuniorem praestat. insomnia levat suspensum in pulvino, ut dormientes olefaciant. adpetentiam ciborum praestat, quando id quoque inter artificia deliciae fecere, ex quo labor desiit cibos poscere. ob has causas quidam anicetum id vocavere.", "st": "20.72"}, {"sp": "N", "t": "Laudatissimum est Creticum, proximum Aegyptium. hoc ligustici vicem praestat in condimentis. dolores capitis levat suffitum naribus. epiphoris oculorum Euenor radicem eius tusam inponit, Iollas ipsum cum croco pari modo et vino, et per se cum polenta ad magnas fluctiones extrahendisque si qua in oculos inciderint. narium quoque carcinodes consumit inlitum ex aqua. sedat anginas cum hysopo ac melle ex aceto gargarizatum, auribus infunditur cum rosaceo, thoracis pituitas purgat tostum cum melle sumptum. melius cum acetabulo anesi nuces amaras L purgatas terere in melle ad tussim; facillime vero anesi drachmae tres, papaveris duae miscentur melle ad fabae magnitudinem et ternae diebus sumuntur. praecipuum autem est ad ructus; ideo stomachi inflationibus et intestinorum torminibus et coeliacis medetur. singultus et olfactum potumque decoctum inhibet. foliis decoctis digerit cruditates. sucus decocti cum apio olfactus sternumenta inhibet. potum somnos conci⟨li⟩at, calculos pellit, vomitiones cohibet et praecordiorum tumores, et pectorum vitiis, nervis quoque, quibus succinctum est corpus, utilissimum. prodest et capitis doloribus instillari sucum cum oleo decocti. non aliud utilius ventri et intestinis putant; ideo dysintericis et in tenesmo datur tostum. aliqui addunt et opium, pilulis in die ternis lupini magnitudine in vini cyatho dilutis. Dieuches et ad lumborum dolores suco usus est, semen hydropicis et coeliacis dedit tritum cum menta, Euenor radicem et ad renes. Dalion herbarius parturientibus ex eo cataplasma inposuit cum apio, item vulvarum dolori deditque bibendum cum aneto parturientibus. phreneticis quoque inlinunt vel recens cum polenta; sic et infantibus comitiale vitium aut contractiones sentientibus. Pythagoras quidem negat corripi vitio comitiali in manu habentes, ideo quam plurimum domi serendum; parere quoque facilius olfactantes, et statim a partu dandum potui polenta aspersa. Sosimenescontra omnes duritias ex aceto usus est eo et contra lassitudines in oleo decoquens addito nitro. semine eius poto lassitudinis auxilium viatoribus spopondit. Heraclides ad inflationes stomachi semen tribus digitis cum castorei obolis duobus ex mulso dedit, similiter ad ventris aut intestinorum inflationes et orthopnoicis quod ternis digitis prender⟨e⟩t seminis, tantundem hyoscyami cum lacte asinino. multi vomituris acetabula eius et folia lauri decem trita in aqua bibenda inter cenam suadent. strangulatus vulvae, si manducetur et linatur calidum vel si bibatur cum castoreo in aceto et melle, sedat; vertigines a partu cum semine cucumeris et lini pari mensura ternum digitorum, vini albi tribus cyathis discutit. Tlepolemus ad quartanas ternis digitis seminis anesi et feniculi usus est in aceto et mellis cyatho uno. lenit articulari⟨o⟩s morbos cum amaris nucibus inlitum. sunt qui et aspidum venenis adversari naturam eius putent. urinam ciet, sitim cohibet, venerem stimulat, cum vino sudorem leniter praestat, vestes quoque a tineis defendit. efficacius semper recens et quo nigrius, stomacho tamen inutile est praeterquam inflato.", "st": "20.73"}, {"sp": "N", "t": "Anetum quoque ructus movet et tormina sedat, alvum sistit. epiphoris radices inlinuntur ex aqua vel vino. singultus cohibet semen fervens olfactu; sumptum ex aqua sedat cruditates. cinis eius uvam in faucibus levat, oculos et genituram hebetat.", "st": "20.74"}, {"sp": "N", "t": "Sacopenium, quod apud nos gignitur, in totum transmarino alienatur. illud enim hammoniaci lacrimae simile sagapenon vocatur. prodest laterum et pectoris doloribus, convolsis, tussibus vetustis excreationibusque, praecordiorum tumoribus. sanat et vertigines, tremulos, opisthotonicos, lienes, lumbos, perfrictiones. datur olfactandum ex aceto in strangulatu vulvae; ceteris et potui datur et cum oleo infricatur. prodest et contra mala medicamenta.", "st": "20.75"}, {"sp": "N", "t": "Papaveris sativi tria diximus genera, et sponte nascentis alia promisimus. e sativis albi calix ipse teritur et e vino bibitur somni causa. semen elephantiasi medetur. e nigro papavere sopor gignitur scapo inciso, ut Diagoras suadet, cum turgescit, ut lollas, cum deflorescit, hora sereni diei tertia, hoc est cum ros in eo exaruerit. incidi iubent sub capite et calice, nec in alio genere ipsum inciditur caput. sucus et hic et herbae cuiuscumque lana excipitur aut, si exiguus s⟨i⟩t, ungue pollicis, ut lactucis, et postero die magis, quod inaruit, [papaveris vero largus] densatus et in pastillos tritus in umbra siccatur, non vi soporifera modo, verum, si copiosior hauriatur, etiam mortifera per somnos. opium vocant. sic scimus interemptum P. Licini Caecinae praetorii viri patrem in Hispania Bavili, cum valetudo inpetibilis odium vitae fecisset; item plerosque alios. qua de causa magna concertatio extitit. Diagoras, Erasistratus in totum damnavere ut mortiferum, infundi vetantes praeterea, quoniam visui noceret. addidit Andreas, ideo non protinus excaecari eo, quoniam adulteraretur Alexandriae. sed postea usus eius non inprobatus est medicamento nobili, quod διὰ κωδυῶν vocant. semine quoque eius trito in pastillos e lacte utuntur ad somnum, item ad capitis dolores cum rosaceo; cum h⟨o⟩c et aurium dolori instillatur. podagris inlinitur cum lacte mulierum—sic et foliis ipsis utuntur—, item ad ignes sacros et vulnera ex aceto. ego tamen damnaverim collyriis addi, multoque magis quas vocantληξιπυρέτους quasque pe⟨p⟩ticas et coeliacas. nigrum tamen coeliacis in vino datur. sativum omne maius. rotunda e⟨i⟩ capita, at silvestri longa ac pusilla, sed ad omnes effectus valentiora. decoquitur et bibitur contra vigilias, eademque aqua fovent ora. optimum in siccis et ubi raro pluat. cum capita ipsa et folia decocuntur, sucus meconium vocatur, multum opio ignavior. experimentum opii est primum in odore—sincerum enim perpeti non est—, mox in lucernis, ut pura luceat flamma et ut extinct⟨um⟩ demum oleat, quae in fucato non eveniunt. accenditur quoque difficilius et crebro extinguitur. est sinceri experimentum et in aqua, quoniam ut nubecula innatat, fictum in pusulas coit. sed maxime mirum est aestivo sole deprehendi; sincerum enim sudat et se diluit, done suco recenti simile fiat. Mnesides optime servari putat hyoscyami semine adiecto, alii in faba.", "st": "20.76"}, {"sp": "N", "t": "Inter sativa et silvestria medium genus, quoniam in arvis, sed sponte nasceretur, rh⟨oe⟩am vocavimus et e⟨r⟩raticum. quidam id decerptum protinus cum toto calice mandunt. alvum exinanit. capita quinque decocta in vini tribus heminis pota et somnum faciunt.", "st": "20.77"}, {"sp": "N", "t": "Silvestrium unum genus ceratitim vocant, nigrum, cubitali altitudine, radice crassa et corticosa, calyculo inflexo ut cornicul⟨o⟩. folia minora et tenuiora quam ceteris silvestribus. semen exile tempestivum est messibus; alvum purgat dimidio acetabulo in mulso. folia trita cum oleo argema iumentorum sanant. radix acetabuli mensura cocta in duobus sextariis ad dimidias datur ad lumborum vitia et iocineris. carbunculis medentur ex melle folia. quidam hoc genus glaucion vocant, alii paralium. nascitur enim in adflatu maris aut nitroso loco.", "st": "20.78"}, {"sp": "N", "t": "Alterum e silvestribus genus heraclium vocatur, ab aliis aphro⟨des⟩, foliis, si procul intuearis, speciem passerum praebentibus, radice in summa terrae cute, semine spumeo. ex hoc lina splendorem trahunt. aestate tunditur in pila. comitialibus morbis acetabul⟨o⟩ semin⟨is⟩ in vino albo —vomitionem enim facit—, item medicamento, quod διὰ κωδυῶν et arteriace vocatur, utilissimum. fit autem huius papaveris aut cuiuscumque silvestris capitibus cxx in aquae caelestis sextariis tribus biduo maceratis in eademque discoctis, deinde suco siccato iterumque cum melle decocto ad dimidias partes vapore tenui. addidere postea drac⟨h⟩m⟨a⟩s senas croci, hypocisthidis, turis, acaciae et passi Cretici sextarium. haec ostentatione, simplex quidem et antiqua illa salubritas papavere et melle constat.", "st": "20.79"}, {"sp": "N", "t": "Tertium genus est tithymalon—mecona vocant, lii paralion—folio lini, flo⟨re⟩ albo, capite magnitudinis fabae. colligitur uva florente, siccatur in umbra. semen potum purgat alvum dimidio acetabulo in mulso. cuiuscumque autem papaveris caput viride vel siccum inlitum epiphoras oculorum lenit. opium ex vino meraculo si protinus detur, scorpionum ictibus resistit. aliqui hoc tantum nigro tribuunt, si capita eius vel folia terantur.", "st": "20.79"}, {"sp": "N", "t": "Est et porcillaca, quam peplin vocant, non multum sativa efficacior, cuius memorabiles usus traduntur: sagittarum venena et serpentium haemorrhoidum et prest⟨e⟩rum restingui pro cibo sumpta et plagis inposita extrahi, item hyoscyami pota e passo expresso suco. cum ipsa non est, semen eius simili effectu prodest. resistit et aquarum vitiis, capitis dolori ulceribusque in vino tusa et inposita, reliqua ulcera commanducata cum melle sanat. sic et infantium cerebro inponitur umbilicoque prociduo, in epiphoris vero omnium fronti temporibusque cum polenta, sed ipsis oculis e lacte et melle; eadem, si pro⟨ci⟩dant oculi, foliis tritis cum corticibus fabae, pusulis cum polenta et sale et aceto. ulcera oris tumoremque gingivarum commanducata cruda sedat, item dentium dolores, tonsillarum ulcera sucus decoctae; quidam adiecere paulum murrae. nam mobiles dentes stabilit conmanducata [cruda sedat] vocemque firmat et sitim arcet. cervicis dolores cum galla et lini semine et melle pari mensura sedat, mammarum vitia cum melle aut Cimolia crela, salutaris et suspiriosis semine cum melle hausto. stomachum in acetariis sumpta corroborat. ardenti febribus inponitur cum polenta, et alias manducata refrigerat etiam intestina. vomitiones sistit. dysinteriae et vomicis estur ex aceto vel bibitur cum cumino, tenesmis autem cocta. comitialibus cibo vel potu prodest, purgationibus mulierum acetabuli mensura in sapa, podagris calidis cum sale inlita et sacro igni. sucus eius potus renes iuvat ac vesicas, ventris animalia pellit. ad vulnerum dolores ex oleo cum polenta inponitur. nervorum duritias emollit. Metrodorus, qui ἐπιτομὴν ῥιζοτομουμένων scripsit, purgationibus a partu dandam censuit. venerem inhibet venerisque somnia. praetorii viri pater est, Hispaniae princeps, quem scio propter inpetibiles uvae morbos radicem eius filo suspensam e collo gerere praeterquam in balineis, ita liberatum incommodo omni. quin etiam inveni apud auctores caput inlitum ea destillationem anno toto non sentire. oculos tamen hebetare putatur.", "st": "20.81"}, {"sp": "N", "t": "Coriandrum inter silvestria non invenitur. praecipuum esse constat Aegyptium. valet contra serpentium genus unum, quod am⟨ph⟩is⟨ba⟩enas vocant, potum inpositumque. sanat et alia vulnera, epinyctidas pusulas tritum; sic et omnes tumores collectionesque cum melle aut uva passa, panos vero ex aceto tritum. seminis grana tria in tertianis devorari iubent aliqui ante accessionem vel plura inlini fronti. sunt qui et ante solis ortum cervicalibus subici efficaciter putent. vis magna ad refrigerandos ardores viridi. ulcera quoque, quae serpunt, sanat cum melle vel uva passa, item testes, ambusta, carbunculos, aures, cum lacte mulieris epiphoras oculorum, ventris et intestinorum fluctiones semen ex aqua potum. bibitur et in choleris cum ruta. pellit animalia interaneorum cum mali punici suco et oleo semen potum. Xenocrates tradit rem miram, si vera est, menstrua contineri uno die, si unum granum biberint feminae, biduo, si duo, et totidem diebus quot grana sumpserint, M. Varro coriandro subtrito et cumino acetoque carnem omnem incorruptam aestate servari putat.", "st": "20.82"}, {"sp": "N", "t": "Atriplex et silvestre est, accusatum Pythagorae, tamquam faceret hydropicos morbosque regios et pallorem, con⟨co⟩queretur difficillime; ac ne in hortis quidem iu⟨x⟩t⟨a⟩ id nasci quicquam nisi languidum culpavit. addidere Dionysius et Diodes plurimos gigni ex eo morbos, nec nisi mutata saepe aqua coquendum, stomacho contrarium esse, lentigines et papulas gignere. miror quare difficulter in Italia nasci tradiderit id Solo Smyrn⟨a⟩eus. Hippocrates vulvarum vitiis infundit id cum beta. Lycus Neapolitanus contra cantharidas bibendum dedit, panos, furunculos incipientes,duritias omnes vel cocto vel crudo utiliter inlini putavit,item ignem sacrum cum melle, aceto, nitro, similiter podagras. ungues scabros detrahere dicitur sine ulcere. sunt qui et morbo regio dent semen eius cum melle, arterias et tonsillas nitro addito perfricent, alvum moveant cocto vel per se vel cum malva aut lenticula. concitant e⟨t⟩ vomitiones. silvestri capillos tingunt et ad supra scripta utuntur.", "st": "20.83"}, {"sp": "N", "t": "E contrario in magnis laudibus malva est utraque et sativa et silvestris. duo genera earum amplitudine folii discernuntur. maiorem Graeci ⟨ma⟩lopen vocant in sativis, alteram ab emolliendo ventre dictam putant malac⟨h⟩en. at e silvestribus, cui grande folium et radices albae, althaea vocatur, ab excellentia effectus a quibusdam plistoloc⟨h⟩ia. omne solum, in quo seruntur, pinguius faciunt. contra omnes aculeatos ictus efficaces, praecipue scorpionum, vesparum similiumque et muris aranei. quin et trita cum oleo qualibet earum peruncti ante vel habentes eas non feriuntur. folium inpositum scorpionibus torporem adfert. valent et contra psimithi venena. aculeos omnes extrahunt inlitae crudae cum a⟨ph⟩ronitro, potae vero decoctae cum radice sua leporis marini venenum restingunt, ut quidam dicunt, si vomatur. de iisdem mira et alia traduntur, sed maxime, si quis cotidie suci ex qualibet earum sorbeat cyathum dimidium, omnibus morbis cariturum. ulcera manantia in capite sanant in urina putrefactae, lichenas et ulcera oris cum melle; radix decocta furfures capitis et dentium mobilitates. eius, quae unum caulem habet, radice circa dentem, qui doleat, pungunt, donec desinat dolor; eadem strumas et parotidas, panos addita hominis saliva purgat citra vulnus. semen in vino nigro potum pituita et nauseis liberat. radix mammarum vitiis occurrit adalligata in lana nigra, tussim in lacte cocta et sorbitionis modo sumpta quinis diebus emendat. stomacho inutiles Sextius Niger dicit, Olympias Thebana abortivas esse cum adipe anseris, aliqui purgari feminas foliis earum manus plenae mensura in oleo et vino sumptis. utique constat parturientes foliis substratis celerius solvi; protinus a partu revocanda, ne vulva sequatur. dant et sucum bibendum parturientibus ieiunis in vino decoctae hemina. quin et semen adalligant racchio genitale non continentium, adeoque veneri nascuntur, ut semen unicaulis adspersum curationi feminarum aviditates augere ad infinitum Xenocrates tradat itemque tres radices iuxta adalligatas. tenesmo, dysintericis utilissime infundi, item sedis vitiis, vel si foveantur. melancholicis quoque sucus datur cyathis ternis tepidus et insanientibus quaternis, decoctae comitialibus heminae suci. hic et calculosis et inflatione et torminibus aut opisthotonico laborantibus tepidus inlinitur. et sacris ignibus et ambustis decocta in ole⟨o⟩ folia inponuntur, et ad vulnerum impetus cruda cum pane. sucus decoctae nervis prodest et vesicae et intestinorum rosionibus, vulvas et cibo et infusione emollit. ⟨al⟩vo sucus decoctae permeatus suaves facit.", "st": "20.84"}, {"sp": "N", "t": "Althaeae in omnibus supra dictis efficacior radix, praecipue convulsis ruptisque. cocta in aqua alvum sistit, ex vino albo strumas et parotidas et mammarum inflammationes; et panos in vino folia decocta et inlita tollunt; eadem arida in lacte decocta quamlibet perniciosae tus⟨si⟩ citissime medentur. Hippocrates vulneratis sitientibusque defectu sanguinis radicis decoctae sucum bibendum dedit et ipsam vulneribus cum melle et resina, item contusis, luxatis, tumentibus; et musculis, nervis, articulis inposuit ut supra; spasticis, dysintericis in vino bibendam dedit. mirum aquam radice ea addita addensari sub diu atque glaciescere. efficacior autem quo recentior.", "st": "20.84"}, {"sp": "N", "t": "Nec lapathum dissimiles effectus habet. est autem et silvestre. quod alii oxalida appellant, *nostri vero rumicem, alii lapathum canterinum*, sapore sativo proximum, foliis acutis, colore betae candidae, radice minima, * ad strumas cum axungia efficacissimum est; et alterum genus fere oxylapathum vocant, sativo [item] similius et acutior⟨e⟩ foli⟨o⟩ ac rubriore, non nisi in palustribus nascens. sunt qui et hydrolapathum tradant, in aqua natum, et aliud hippolapathum, maius sativo candidiusque ac spissius. silvestria scorpionum ictibus medentur et feriri prohibent habentes. radix aceto decocta, si colluatur sucus, dentibus auxiliatur, si vero bibatur, morbo regio. semen stomachi inextricabilia vitia sanat. hippolapathi radi⟨x⟩ e⟨t⟩ privatim ungues scabros detrahit; dysintericos semen duabus drachmis in vino potum liberat. oxylapathi semen lotum in aqua caelesti sanguinem reicientibus adiecta acacia lentis magnitudine prodest. praestantissimos pastillos faciunt ex foliis et radice addito nitro et ⟨t⟩ure exiguo. in usu aceto diluunt.", "st": "20.85"}, {"sp": "N", "t": "Sed sativum in epiphoris oculorum inlinunt frontibus. radice lichenas et lepras curant, in vino vero decocta strumas et parotidas, set calculos pota e vino et lienes inlita, coeliacos aeque et dysintericos et tenesmos; ex eademque ad omnia efficacious ius lapathi et ructus facit et urinam ciet et caliginem oculorum discutit, item pruritum corporis in solia balinearum additum aut prius ipsum inlitum sine oleo. firmat et commanducata radix dentes; eadem decocta cum vino sistit alvum, folia solvunt. adiecit Solo, ne quid omittamus, bulapathum, radicis tantum altitudine differens et egr⟨egio⟩ a⟨d⟩ dysintericos effectu pota⟨e⟩ ex vino.", "st": "20.86"}, {"sp": "N", "t": "Sinapi, cuius in sativis tria genera diximus, Pythagoras principatum habere ex his, quorum in sublime vis feratur, iudicavit, quoniam non aliud magis in nares et cerebrum penetret. ad serpentium ictus et scorpionum tritum cum aceto inlinitur; fungorum venena discutit. contra pituitam tenetur in ore, donec liquescat, aut gargarizatur cum aqua mulsa. ad dentium dolores manditur, ad uvam gargarizatur cum aceto et melle, stomacho utilissimum contra omnia vitia, pulmonibus excreationes faciles facit in cibo sumptum; et suspiriosis datur, item comitialibus te⟨r⟩ di⟨e⟩ cum suco cucumerum. sensus atque sternutamentis caput purgat, alvum mollit, menstrua et urinam ciet. et hydropicis inponitur cum fico et cumino tusum ternis partibus. comitiali morbo aut vulvarum conversione suffocatas excitat odore aceto mixto; item lethargicos: adicitur tordylon—est autem hoc semen ex seseli —et, si vehementior lethargus premat, cruribus aut etiam capiti inlinitur cum fico ex aceto. veteres dolores thoracis, lumborum, coxendicum, umerorum et in quacumque parte ex alto corporis vitia extrahenda s⟨i⟩nt inlitum caustica vi emendat pusulas faciendo, at in magna duritia sine fico inpositum aut, si vehementior ustio timeatur, per duplices pannos. utuntur eo ad alopecias cum rubrica, psoras, lepras, phthiriases, ⟨te⟩tanicos, opisthotonicos. inungunt quoque scabras genas aut caliga⟨n⟩tes oculos suco cum melle, sucusque tribus modis exprimitur in fictili calescitque in eo sole modice. exit et e cauliculo sucus lacteus; eius ⟨g⟩u⟨t⟩ta, cum induruit, dentium dolori medetur. semen ac radix, cum inmaduere musto, conteruntur manusque plenae mensura sorbentur ad confirmandas fauces, stomachum, oculos, caput sensusque omnes, mulierum etiam lassitudines, saluberrimo genere medicinae. calculos quoque discutit potum in aceto. inlinitu⟨r⟩ et livoribus suggillatisque cum melle et adipe anserino aut cera Cypria. fit et oleum ex eo semine madefacto in oleo expressoque, quo utuntur ad nervorum rigores lumborumque et coxendicum et perfrictiones.", "st": "20.87"}, {"sp": "N", "t": "Sinapis naturaeesse effectusque eosdem habere traditur adarca inter silvestria dicta, in cortice calamorum sub ipsa coma nascens.", "st": "20.88"}, {"sp": "N", "t": "Marrubium plerique inter primas herbas commendavere, quod Graeci prasion vocant, alii linostrophon, nonnulli philopaeda aut philochares, notius quam ut indicandum sit. huius folia semenque contrita prosunt contra serpentes, pectorum et lateris dolores, tussim veterem. et iis, qui sanguinem reiecerint, eximie utile, scopis eius cum panico aqua decoctis, ut asperitas suci mitigetur. inponitur strumis cum adipe. sunt qui viride semen, quantum duobus digitis capiant, cum farris pugillo decoctum addito exiguo olei et salis sorberi ieiunis ad tussim iubeant. alii nihil conparant in eadem causa marrubii et feniculi sucis ad sextarios ternos expressis decoctisque ad sextarios duos, tum addito mellis sextario, rursus decocto ad sextarios duos, si coclearii mensura in die sorbeatur in aquae cyatho. virilium vitiis tusum cum melle mire prodest. lichenas purgat ex aceto, ruptis, convulsis, spasticis, nervis salutare. potum alvum solvit cum sale et aceto, item menstrua et secundas mulierum. arida farina cum melle ad tussim siccam efficacissima est, item ad ⟨g⟩an⟨g⟩ra⟨e⟩nas et pterygia. sucus vero auriculis, e⟨x⟩ naribus et morbo regio minuendaeque bili cum melle prodest, item contra venena inter pauca potens. ipsa herba stomachum et excreationes pectoris purgat cum iride et melle, urinam ciet, cavenda tamen exulceratae vesicae et renium vitiis. dicitur sucus et claritatem oculorum adiuvare. Castor marrubii duo genera tradit, nigrum et, quod magis probat, candidum. in ovum inane sucum addit is ipsumque ovum infundit cum melle aequis portionibus, tepefactum vomicas rumpere, purgare, persanare promittens. inli⟨n⟩it etiam vulneribus a cane factis tusum cum axungia vetere.", "st": "20.89"}, {"sp": "N", "t": "Serpyllum a serpendo putant dictum, quod in silvestri evenit, in petris maxime; nam sativum non serpit, sed ad palmum altitudine increscit. pinguius voluntarium et candidioribus foliis ramisque. adversus serpentes efficax, maxime cenchrim et scolopendras terrestres ac marinas et scorpiones, decotis ex vino ramis foliisque. fugat et odore omnes, si uratur, et contra marinorum venena praecipue valet. capitis doloribus decoctum in aceto inlinitur temporibus ac fronti cum rosaceo, item phreneticis, lethargicis. contra tormina et urinae difficultates, anginas, vomitiones drachmis quattuor ex aqua bibitur; ad iocinerum desideria folia obolis quattuor dantur, ad lienem ex aceto. ad cruentas excreationes teritur in cyathis duobus aceti et mellis.", "st": "20.90"}, {"sp": "N", "t": "Sisymbrium silvestre, quibusdam thymbraeum appellatum, pedali non amplius altitudine. quod in riguis nascitur, simile nasturtio est, tr⟨it⟩umque efficax adversus aculeata animalia, ut crabrones et similia; quod in sicco, odoratum est et inseritur coronis, angustiore folio. sedant utraque capitis dolorem, item epiphoras, ut P⟨h⟩ilinus tradit. alii panem addunt, alii per se decocunt in vino. sanat et epinyctidas cutisque vitia in facie mulierum intra quartum diem noctibus inpositum diebusque detractum. vomitiones, singultus, tormina, stomachi dissolutiones cohibet, sive in cibo sumptum sive suco pot⟨o⟩. non edendum gravidis nisi mortuo conceptu, quippe etiam inpositum eicit. movet urinas cum vino potum, silvestre vero et calculos. quos vigilare opus sit, excitat infusum capiti cum aceto.", "st": "20.91"}, {"sp": "N", "t": "Lini semen cum aliis quidem in usu est, sed et per se mulierum cutis vitia emendat in facie, oculorum aciem suco adiuvat. epiphoras cum ture et aqua aut cum murra ac vino sedat, parotidas cum melle aut adipe aut cera, stomachi solutiones inspersum polentae modo, angina⟨s⟩ in aqua et oleo decoctum et cum aneso inlitum. torretur, ut alvum sistat. coeliacis et dysintericis inponitur ex aceto. ad iocineris dolores estur cum uva passa; ad phthisim utilissime e semine fiunt ecligmata. musculorum, nervorum, articulorum, cervicium duritias, cerebri membranas mitigat farina seminis nitro aut sale aut cinere additis. eadem cum fico… etidem concoquit ac maturat; cum radice vero cucumeris silvestris extrahit quaecumque corpori inhaereant; sic et fracta ossa. serpere ulcus in vino decocta prohibet, eruptiones pituitae cum melle. emendat ungues scabros cum pari modo nasturtii, testium vitia et ramices cum resina et murra et gangraenas ex aqua, stomachi dolores cum feno Graeco sextariis utriusque decoctis in aqua mulsa, intestinorum, thoracis perniciosa vitia clystere in oleo aut melle.", "st": "20.92"}, {"sp": "N", "t": "Blitum iners videtur ac sine sapore aut acrimonia ulla, unde convicium feminis apud Menandrum faciunt mariti. stomacho inutile est. ventrem adeo turbat, ut choleram faciat aliquis. dicitur tamen adversus scorpiones potum e vino prodesse, clavis pedum inlini, item lienibus et temporum dolori ex oleo. Hippocrates menstrua sisti eo cibo putat.", "st": "20.93"}, {"sp": "N", "t": "Meum in Italia non nisi a medicis seritur et his admodum paucis. duo genera eius: nobilius A⟨th⟩amanticum vel At⟨h⟩amanicum vocant, illi tamquam ab Athamante inventum, hi quoniam laudatissimum in Athaman⟨i⟩a reperiatur, foliis aneto simile et caule, aliquando bipedale, radicibus multis obliquis nigris, quibusdam et altis, minus rufum quam illud alterum. urinam⟨ci⟩et in aqua pota radice trita vel decocta, inflationes stomachi mire discutit, item tormina et vesicae vitia vulvarumque. articulis cum melle… infantibus cum apio inlitum imo ventri urinas movet.", "st": "20.94"}, {"sp": "N", "t": "Feniculum nobilitavere serpentes gustatu, ut diximus, senectam exuendo oculorumque aciem suco eius reficiendo, unde intellectum, hominum quoque caliginem praecipue eo levari. colligitur hic caule turgescente et in sole siccatur inunguiturque ex melle. [ubique hoc est] laudatissimus in Hiberia lacrimis fit. et e semine recenti fit et e radicibus prima germinatione incisis.", "st": "20.95"}, {"sp": "N", "t": "Est in hoc genere et silvestre, quod hippomarathum, alii myrsineum vocant, foliis maioribus, gustu acriore, procerius, baculi crassitudine, radice candida. nascitur in calidis et saxosis. Diocles et aliud hippomarathi genus tradidit, longo et angusto folio, semine coriandri.", "st": "20.96"}, {"sp": "N", "t": "Medicinae in sativo ad scorpionum ictus et serpentium semine in vino poto. sucus et auribus instillatur vermiculosque in his necat. ipsum condimentis prope omnibus inseritur, oxyporis etiam aptissime. quin et panis crustis subditur. semen stomachum dissolutum adstringit vel in febribus sumptum, nausiam ex aqua tritum sedat, pulmonibus et iocineribus laudatissimum. ventrem sistit, cum modice sumitur, urinam ciet et ad tormina ⟨p⟩otu. decoctum in lactis defectu potum mammas replet. radix cum tisana sumpta renes purgat sive decoct⟨ae⟩ suco ex vino sumpto. prodest et hydropicis radix ex vino pota, item convulsis. inlinuntur folia tumoribus ardent⟨ibus⟩ ex aceto, calculos vesicae pellunt, venerem stimulant. geniturae abundantiam quoquo modo haustum facit, verendis amicissimum sive ad fovendum radice cum vino decocta sive contrit⟨a⟩ in oleo inlit⟨a⟩. multi et suggillatis cum cera inlinunt [et] radicem. ⟨sem⟩in⟨is⟩ suco vel radice cum melle contra canis morsum utuntur et contra multipedam ex vino.", "st": "20.96"}, {"sp": "N", "t": "Hippomarathum ad omnia vehementius calculos praecipue pellit, prodest vesicae cum vino leni et feminarum menstruis haerentibus. efficacius in eo semen quam radix. modus in utroque quod duobus digitis trit⟨um⟩ addatur in potionem. Petrichus, qui ophiaca scripsit, et Mic⟨i⟩on, qui rhizotomumena, adversus serpentes nihil efficacius hippomaratho putavere; sane et Nicander non in novissimis posuit.", "st": "20.96"}, {"sp": "N", "t": "Cannabis in silvis primum nata est, nigrior foliis et asperior. semen eius extinguere genituram virorum dicitur. sucus ex eo vermiculos aurium et quodcumque animal intraverit eicit, sed cum dolore capitis, tantaque vis ei est, ut aquae infusus coagulare eam dicatur; et ideo iumentorum alvo succurrit potus in aqua. radix articulos contractos emollit in aqua cocta, item podagras et similes impetus. ambustis cruda inlinitur, sed saepius mutatur, priusquam arescat.", "st": "20.97"}, {"sp": "N", "t": "Ferula semen aneto simile habet. quae ab uno caule dividitur in cacumine, femina putatur. caules eduntur decocti commendanturque muria ac melle, stomacho util⟨e⟩s. sin plures sumpti, capitis dolorem faciunt. radix denarii pondere in vini cyathis duobus bibitur adversus serpentes, et ipsa radix inponitur. sic et torminibus medetur, ex oleo autem et aceto contra sudores inmodicos vel in febribus proficit. sucus ferulae alvum solvit fabae magnitudine devoratus. e viridi medulla vulvis utilis et ad. omnia ea vitia. ad sanguinem sistendum decem grana seminis bibuntur in vino trita vel medulla. sunt qui comitialibus dandum putent luna IIII usque VII lingulae mensura. natura ferularum murenis infestissima est, tactae siquidem ea moriuntur. Castor radicis sucum et oculorum claritati conferre multum putavit.", "st": "20.98"}, {"sp": "N", "t": "Et de carduorum satu inter hortensia diximus, quapropter et medicinam ex his non differamus. silvestrium genera sunt duo, unum fruticosius a terra statim, alterum unicaule crassius. utrique folia pauca, spinosa, muricatis cacuminibus, sed alter florem purpureum emittit inter medios aculeos celeriter canescentem et abeuntem cum aura; σκόλυμον Graeci vocant. hic, antequam floreat, contusus atque expressus inlito suco alopecias replet. radix cuiuscumque ex aqua decocta potoribus sitim facere narratur. stomachum corroborat et vulvis… si credimus, etiam conferre aliquid traditur, ut mares gignantur. ita cer⟨t⟩e Glaucias scripsit, qui circa carduos diligentissimus videtur. mastichee carduis odorem commendat oris.", "st": "20.99"}, {"sp": "N", "t": "Et discessu⟨ri⟩ ab hortensiis unam conpositionem ex his clarissimam subteximus adversus venenata animalia incisam in lapide versibus Coi in aede Aesculapi: serpylli duum denariorum pondus, opopanacis et m⟨e⟩i tantundem singulorum, trifolii seminis pondus denarii, anesi et feniculi seminis et ammi et apii denarium senum e singulis generibus, ervi farinae denarium XII. haec tusa cribrataque vino quam possit excellenti digeruntur in pastillos victoriati ponderum. ex his singuli dantur ex vini. mixti cyathis ternis. hac theriace Magnus Antiochus rex adversus omnia venenata usus traditur aspide excepta.", "st": "20.100"}, {"sp": "HDR", "t": "Liber XXI", "st": "21"}, {"sp": "N", "t": "In hortis seri et coronamenta iussit Cato, inenarrabili florum maxime subtilitate, quando nulli potest facilius esse loqui quam rerum naturae pingere, lascivienti praesertim et in magno gaudio fertilitatis tam varie ludenti. quippe reliqua usus alimentique gratia genuit, ideoque saecula annosque tribuit iis, flores vero odoresque in diem gignit, magna, ut palam est, admonitione hominum, quae spectatissime floreant, celerrime marcescere. sed ne pictura quidem sufficiet imagini colorum reddendae mixturarumque varietati, sive alteruni atque multiplices inter se nectantur, sive privatis generum ftniculis in orbem, in oblicum, in ambitum quaedam coronae per coronas curr⟨a⟩nt.", "st": "21.1"}, {"sp": "N", "t": "Tenuioribus utebantur antiqui, stroppos appellantes, unde nata strophiola. quin et vocabulum ipsum tarde communicatum est, inter sacra tantum et bellicos honores coronis suum nomen vindicantibus. cum vero e floribus fierent, serta a serendo serieve appellabantur, quod apud Graecos quoque non adeo antiquitus placuit.", "st": "21.2"}, {"sp": "N", "t": "Arborum enim ramis coronari in sacris certaminibus erat primum. postea variari coeptum mixtura versicolori florum, quae invicem odores coloresque accenderet, Sicyone ingenio Pausiae pictoris atque Glycerae coronariae dilectae admodum illi, cum opera eius pictura imitaretur, illa provocans variaret, essetque certamen artis ac naturae, quales etiam nunc extant artificis illius tabellae atque in primis appellata stephaneplocos, qua pinxit ipsam. idque factum est post Olympiada c. sic coronis e floribus receptis paulo mox subiere, quae vocantur Aegyptiae, ac deinde hibernae, cum terra flores negat, ramento e cornibus tincto. paulatimque et Romae subrepsit appellatio corollis inter initia propter gracilitatem nominatis, mox et corollariis, postquam e lamina tenui aerea inaurata aut inargentata dabantur.", "st": "21.3"}, {"sp": "N", "t": "Crassus Dives primus argento auroque folia imitatus ludis suis coronas dedit, accesseruntque et lemnisci, quos adici ipsarum coronarum honor erat, propter Etruscas, quibus iungi nisi aurei non debebant. purl diu fuere hi; caelare eos primus instituit P. Claudius Pulcher bratteasque etiam philyrae dedit.", "st": "21.4"}, {"sp": "N", "t": "Semper tamen auctoritas vel ludicro quaesitarum fuit. namque ad certamina in circum per ludos et ipsi descendebant et servos suos ⟨e⟩quosque mittebant. inde illa XII tabularum lex: qui coronam parit ipse pecuniave eius, virtutis suae ergo duit⟨o⟩r ei. quam servi equive meruissent, pecunia partam lege dici nemo dubitavit. quis ergo honos? ut ipsi mortuo parentibusque eius, dum intus positus esset forisve ferretur, sine fraude esset inposita. alias in usu promiscuo ne ludicrae quidem erant,", "st": "21.5"}, {"sp": "N", "t": "ingensque et hinc severitas. L. Fulvius argentarius bello Punico secundo cum corona rosacea interdiu e pergula sua in forum prospexisse dictus ex auctoritate senatus in carcerem abductus non ante finem belli emissus est. P. Munatius cum demptam Marsuae coronam e floribus capiti suo inposuisset, atque ob id duci eum in vincula triumviri iussissent, appellavit tribunos pleb⟨e⟩i, nec intercessere illi, aliter quam Athenis, ubi comissabundi iuvenes ante meridiem conventus sapientium quoque doctrinae frequentabant. apud nos exemplum licentiae huius non est aliud quam filia divi Augusti, cuius luxuria noctibus coronatum Marsuam litterae illius dei gemunt.", "st": "21.6"}, {"sp": "N", "t": "Florum quidem populus Romanus honorem Scipioni tantum habuit. Serapio cognominabatur propter similitudinem suarii cuiusdam negotiatoris. obierat in tribunatu plebei admodum gratus dignusque Africanorum familia, nec erat in bonis funeris inpensa. asses ergo contulit populus ac funus elocavit, quaque praeferebatur, flores e prospectu omni sparsit.", "st": "21.7"}, {"sp": "N", "t": "Et iam tunc coronae deorum honos erant et larum publicorum privatorumque ac sepulchrorum et manium, summaque auctoritas pactili coronae, ut i⟨n⟩ Saliorum sacris invenimus sollemnes cena⟨e⟩. transiere deinde ad rosa⟨r⟩ia, eoque luxuria processit, ut non esset gratia nisi mero folio sutili⟨bu⟩s, mox petitis ab India aut ultra Indos. lautissimum quippe habetur e nardi folio eas dari aut veste Serica versicolori, unguentis madida. hunc habet novissime exitum luxuria feminarum.", "st": "21.8"}, {"sp": "N", "t": "Et apud Graecos quidem de coronis privatim scripser⟨un⟩t Mnesitheus atque Callimachus medici, quae nocerent capiti, quoniam et in hoc est aliqua valitudinis portio, in potu atque hilaritate praecipue odorum vi subrepente fallaciter. scelerata Cleopatrae sollertia. namque in apparatu belli Actiaci gratificationem ipsius reginae Antonio timente nec nisi praegustatos cibos sumente fertur pavore eius lusisse extremis coronae floribus veneno inlitis ipsaque capiti inposita; mox procedente hilaritate invitavit Antonium, ut coronas biberent. quis ita timeret insidias? ergo concerpta⟨m⟩ in scyphum incipienti haurire opposita manu: en ego sum, inquit illa, Marce Antoni, quam tu nova praegustantium diligentia caves; adeo mihi, si possim sine te vivere, occasio aut ratio deest! inductam custodiam bibere iussit ilico expirantem.", "st": "21.9"}, {"sp": "N", "t": "De floribus… supra dictis scripsit Theophrastus apud Graecos; ex nostris autem inscripsere aliqui libros anthologicon, flores vero persecutus est nemo, quod equidem inveniam. nec nos nunc scilicet coronas nectemus —id enim frivolum est—, sed de floribus quae videbuntur digna memorabimus.", "st": "21.9"}, {"sp": "N", "t": "Paucissima nostri genera coronamentorum inter hortensia novere, ac paene violas rosasque tantum. rosa nascitur spina verius quam frutice, in rubo quoque proveniens, illic etiam iucundi odoris, quamvis angusti. germinat omnis primo inclusa granoso cortice, quo mox intumescente et in virides alabastros fastigato paulatim rubescens dehiscit ac sese pandit, in calice medio sta⟨m⟩i⟨n⟩is conplexa luteos apices. usus eius in coronis prope minimus est. oleo maceratur, idque⟨i⟩am a Troianis temporibus Homero teste. praeterea in unguenta transit, ut diximus. medicas per se artes praebet. emplastris atque collyriis inseritur mordaci subtilitate, mensarum etiam deliciis perunguendis, minime noxia car⟨ie⟩.", "st": "21.10"}, {"sp": "N", "t": "Genera eius nostri fecere celeberrima Praenestinam et Campanam; addidere alii Milesiam, cui⟨u⟩s ardentissimus colos, non excedentis duodena folia, proximam ei Trachiniam minus rubentem, mox Al⟨a⟩bandicam viliorem, albicantibus foliis, vilissimam vero plurimis, sed minutissimis, spiniolam. differunt enim multitudine foliorum, asperitate, levore, colore, odore. paucissima quina folia, ac deinde numerosiora, cum sit genus eius, quam centifoliam vocant, quae est in Campania Italiae, Graeciae vero circa Philippos, sed ibi non suae terrae proventu: Pangaeus mons in vicino fert numerosis foliis ac parvis; accolae transferentes conserunt, ipsaque plantatione proficiunt. non autem talis odoratissima nec cui latissimum maximumve folium, breviterque indicium est odoris scabritia corticis. Caepio Tiberii Caesaris principatu negavit centifoliam in coronas addi, praeterquam extremas velut ad cardines, nec odore nec specie probabilem. est et quae Graeca appellatur a nostris, a Graecis lychnis, non nisi in umidis locis proveniens nec umquam excedens quin⟨a⟩ folia violaeque magnitudine, odore nullo. est et alia Graecula appellata, convolutis foliorum paniculis nec dehiscens nisi manu coacta semperque nascenti similis, latissimis foliis; alia funditur e caule malvaceo folia oleae habente—mucetum vocant—, atque inter has media magnitudine autumnalis, quam coroniolam appellant, omnes sine odore praeter coroniolam et in rubo natam. tot modis adulteratur.", "st": "21.10"}, {"sp": "N", "t": "Et alias vera quoque plurimum solo praevalet. Cyrenis odoratissima est, ideoque ibi unguentum pulcherrimum, Carthagine Hispaniae hieme tota praecox. refert et caeli temperies, quibusdam enim annis minus odorata provenit, praeterea omnis siccis quam umidis odoratior. seri neque pinguibus vult neque argillosis locis nec riguis, contenta r⟨o⟩ribus, proprieque ruderatum agrum amat. praecox Campana est, sera Milesia, novissima tamen desinit Praenestina. fodiuntur altius quam fruges, levius quam vites. tardissime proveniunt semine, quod in ipso cortice est, sub ipso flore, opertum lanugine. ob id potius caule conciso inseruntur. et ocellis radicis, ut harundo, unum genus inseritur pallidae, spinosae, longissimis virgis, quinquefoliae, quae Graecis altera est. omnis autem recisione atque ustione proficit; tralatione quoque, ut vites, optime ocissimeque provenit surculis quaternum digitorum longitudine aut ampliore post vergiliarum occasum sata, dein per favonium translata pedalibus intervallis crebroque cir⟨cum⟩fossa. qui praecocem faciunt, pedali circa radicem scrobe aquam calidam infundunt germinare incipiente calice.", "st": "21.10"}, {"sp": "N", "t": "Lilium rosae nobilitate proximum est et quadam cognatione unguenti oleique, quod lili⟨n⟩um appellatur. interpositum etiam maxime rosas decet, medio proventu earum incipiens. nec ulli forum excelsitas maior, interdum cubitorum trium, languido semper collo et non sufficiente capitis oneri. candor eius eximius foris striati et ab angustiis in latitudinem paulatim sese laxantis effigie calathi, resupinis per ambitum labris tenuique pilo et s⟨ta⟩min⟨is⟩ stantibus in medio crocis. ita odor colorque duplex, et alius calicis, alius staminis, differentia angusta. in unguenti vero oleique usu et folia non spernuntur. est flos non dissimilis illi in herba, quam convolvolum vocant, nascens per frutecta, nullo odore nec crocis intus, candorem tantum referens ac veluti naturae rudimentum lilia facere condiscentis. alba lilia iisdem omnibus modis seruntur, quibus rosa, et hoc amplius lacrima sua, ut hipposelinum, nihilque est fecundius una radice quinquagenos saepe emittente bulbos. est et rubens lilium, quod Graeci crinon vocant, alii florem eius cynorrhodon. laudatissimum in Antiochia ac Laudicea Syriae, mox in Phaselide. quartum locum optinet in Italia nascens.", "st": "21.11"}, {"sp": "N", "t": "Sunt et purpurea lilia, aliquando gemino caule, carnosiore tantum radice maiorisque bulbi, sed unius; narcissum vocant. huius alterum genus flore candido, calice purpureo. differentia a liliis et haec, quod narcissis in radice folia sunt, probatissimis in Lyciae montibus. tertio generi cetera eadem, calix herbaceus. omnes serotini, post arcturum enim florent ac per aequinoctium autumnum.", "st": "21.12"}, {"sp": "N", "t": "Inventa est in his et ratio inserendi monstrificis hominum ingeniis. collig⟨a⟩ntur namque mense Iulio scapi arescentis lilii a⟨t⟩que suspenduntur in fumo; dein nudantibus se nodulis in faece nigri vini vel Graeci mense Martio macerantur, ut colorem percipiant, atque ita in scrobiculis seruntur heminis faecis circumfusis. sic fiunt purpurea lilia, mirumque tingui aliquid, ut nascatur infectum.", "st": "21.13"}, {"sp": "N", "t": "Violis honos proximus, earumque plura genera, purpureae, luteae, albae, plantis omnes, ut olus, satae. ex his vero, quae sponte apricis et macris locis proveniunt, purpureae latiore folio, statim ab radice exeunti, carnoso solaeque Graeco nomine a ceteris discernuntur, appellatae ia et ab his ianthina vestis. e sativis maxima auctoritas luteis; genera autem Tusculana et quae marina appellatur, folio aliquanto latiore, sed minus odorat⟨a⟩; in totum vero sine odore minutoque folio Calatina, munus autumni, ceterae veris.", "st": "21.14"}, {"sp": "N", "t": "Proxima ei caltha est et concolori… amplitudine. vincit numero foliorum marinam quin⟨a⟩ non excedentem; eadem odore superatur. est enim gravi caltha, non leviore quam scopam regiam appellant, quamquam folia eius olent, non flores.", "st": "21.15"}, {"sp": "N", "t": "Baccar quoque radicis tantum odoratae est, a quibusdam nardum rusticum appellatum. unguenta ex ea radice fieri solita apud antiquos Aristophanes, priscae comoediae poeta, testis est; unde quidam errore falso barbaricam eam appellabant. odor est cinnamomo proximus. gracili solo nec umido provenit. simillimum e⟨i⟩ combretum appellatur, foliorum exilitate usque in fila adtenuata et procerius quam baccar. haec sut⟨ilia⟩ tantum. eorum quoque error corrigendus est, qui baccar rusticum nardum appellavere. est enim alia herba sic cognominata, quam Graeci asaron vocant, cuius speciem figuramque diximus in nardi generibus. quin immo asaron invenio vocitari, quoniam in coronas non addatur.", "st": "21.16"}, {"sp": "N", "t": "Crocum silvestre optimum. serere in Italia minime expedit, ad scripula usque singula areis decoquentibus. seritur radicis bulbo. sativum latius maiusque et nitidius, sed multo lenius, degenerans ubique nec fecundum etiam Cyrenis, ubi semper flores laudatissimi. prima nobilitas Cilicio et ibi in Coryco monte, dein Lyci⟨o⟩ e monte Olympo, mox Centuripino Siciliae. aliqui ⟨T⟩her⟨a⟩eo secundum locum dedere. adulteratur nihil aeque. probatio sinceri, si inposita manu crepit⟨e⟩t veluti fragile; umidum enim, quod event adulteratione, se⟨nt⟩it. altera probatio, si manu relata ad ora leniter faciem oculosque mordeat. est per se genus sativi blandissimum volgo, cum sit mediocre, dialeucon vocant. contra Cyrenaico vitium, quod omni croco nigrius est et celerrime marcescit. optimum ubicumque quod pinguissimum et brevis capilli, pessimum vero quod situm redolet. Mucianus auctor est, in Lycia anno septimo aut octavo transferri in locum subactum atque ita degenerans renovari. usus eius in coronis nusquam; herba enim est folio angusto paene in capillamenti modum. sed vino mire congruit, praecipue dulci, tritum ad theatra replenda. floret vergiliarum occasu paucis diebus folioque florem expellit. viret bruma et colligitur; siccatur umbra, melius etiam hiberna. carnosa et illi radix vivaciorque quam ceteris. gaudet calcari et atteri pereundoque melius provenit; ideo iuxta semitas ac fontes laetissimum.", "st": "21.17"}, {"sp": "N", "t": "Troianis temporibus iam erat honos e⟨i⟩; hos certe flores Homerus tris laudat loton, crocum, hyacinthum.", "st": "21.17"}, {"sp": "N", "t": "Omnium autem odoramentorum atque adeo herbarum differentia est in colore et odore et suco. odorato sapor raro ulli non amarus, e contrario dulcia raro odorata; itaque et vina mustis odoratiora et silvestria magis omnia sativis. quorundam odor suavior e longinquo, propius admotus hebetatur, ut violae. rosa recens a longinquo olet, sicca propius. omnis autem verno tempore acrior et matutinis; quidquid ad meridianas horas dies vergit, hebetatur. novella quoque vetustis minus odorata; acerrimus tamen odor omnium aetate media. rosa et crocum odoratiora, cum serenis diebus leguntur, et omnia in calidis quam in frigidis; in Aegypto tamen minime odorati flores, quia nebulosus et roscidus aer est a multo flumine. quorundam suavitati gravitas inest. quaedam, dum virent, non olent propter umorem nimium, ut bucer⟨a⟩s, quod est fenum Graecum. aquatis odor non omni⟨no⟩ sine suco est, ut violae, rosae, croco; quae vero ex aquatis carent suco, eorum omnium odor gravis, ut in lilio utriusque generis. habrotonum et amaracum acres habent odores. quorundam flos tantum iucundus, reliquae partes ignavae, ut violae ac rosae. hortensium odoratissima quae sicca, ut ruta, menta, apium, et quae in siccis nascantur. quaedam vetustate odoratiora, ut cotonea, eademque decerpta quam in suis radicibus. quaedam non nisi defracta aut ex adtritu olent, alia non nisi detracto cortice, quaedam vero non nisi usta, sicut tura murraeque. flores triti omnes amariores quam intacti. aliqua arida diutius odorem continent, ut melilotos. quaedam locum ipsum odoratiorem faciunt, ut iris, quin et arborem totam, cuiuscumque radices adtingat. hesperis noctu magis olet, inde nomine invento. animalium nullum odoratum, nisi si de pantheris quod dictum est credimus.", "st": "21.18"}, {"sp": "N", "t": "Illa quoque non omittenda differentia est, et odoratorum multa nihil adtinere ad coronamenta, ut irim atque saliuncam, quamquam nobilissimi odoris utramque. sed iris radice tantum commendatur, unguentis nascens et medicinae. laudatissima in Illyrico, et ibi quoque non in maritimis, sed in silvestribus Drinonis et Naronae, proxima in Macedonia, longissima haec et candicans et exilis. tertium locum habet Africana, amplissima inter omnes gustuque amarissima. Illyrica quoque duorum generum est: raphanitis a similitudine, quae et melior, rhizotomos. subrufa optima, quae sternumenta tractatu movet. caulem habet cubitalem, erectum; floret versicolori specie, sicut arcus caelestis, unde et nomen. non inprobatur et Pisidica. effossuri tribus ante mensibus mulsa aqua circumfusa hoc veluti placamento terrae blandiuntur, circumscriptam mucrone gladii orbe triplici cum legerunt, protinus in caelum adtollunt. natura est fervens, tractataque pusulas ambusti modo facit. praecipitur ante omnia, ut casti legant. teredines non sicca modo, verum et in terra celerrime sentit. —Optimum antea irinum Leucade et Elide ferebatur— iam pridem enim et seritur—, nunc e Pamphylia, sed Cilic⟨i⟩um maxime laudatur atque e septentrionalibus.—", "st": "21.19"}, {"sp": "N", "t": "Saliunca folio quidem subbrevi et quod necti non possit, radici numerosae cohaeret, herba verius quam flos, densa veluti manu pressa breviterque caespes sui generis. Pannonia hanc gignit et Norici Alpiumque aprica, urbium Eporedia, tantae suavitatis, ut metallum esse coeperit. vestibus interponi eam gratissimum,", "st": "21.20"}, {"sp": "N", "t": "sicut apud Graecos polium herbam, inclutam Musaei et Hesiodi laudibus ad omnia utilem praedicantium superque cetera ad famam etiam ac dignitates, prorsusque miram, si modo, ut tradunt, folia eius mane candida, meridie purpurea, sole occidente caerulea aspiciuntur. duo genera eius: campestre maius; silvestre, quod minus est, quidam teuthrion vocant. folia canis hominis similia, a radice protinus, numquam palmo altiora.", "st": "21.21"}, {"sp": "N", "t": "Et de odoratis floribus satis dictum. in quibus unguento vicisse naturam gaudens luxuria vestibus quoque provocavit eos flores, qui colore commendantur. hos animadverto tris esse principales: rubentem in cocco, qui a ros⟨a⟩e nigrantis gratia ni⟨t⟩i⟨do⟩ trahitur suspectu et in purpuras Tyrias dibaphasque ac Laconicas; amethyst⟨i⟩⟨n⟩um, qui a viola et ipse in purpureum, quemque ianthinum appellavimus. genera enim tractamus in species multas sese spargentia. tertius est, qui proprie conchylii intellegitur, multis modis: unus in heliotropio et in aliquo ex⟨il⟩is, plerumque saturatior; alius in malva ad purpuram inclinans; alius in viola serotina conchyliorum vegetissimus. paria nunc componuntur, et natura atque luxuria depugnant. lutei video honorem antiquissimum, in nuptialibus flammeis totum feminis concessum, et fortassis ideo non numerari inter principales, hoc est communes maribus ac feminis, quoniam societas principatum dedit.", "st": "21.22"}, {"sp": "N", "t": "Amaranto non dubie vincimur. est autem spica purpurea verius quam flos aliquis, et ipse sine odore. mirum in eo gaudere decerpi et laetius renasci. provenit Augusto mense, durat in autumnum. Alexandrino palma, qui decerptus adservatur; mireque, postquam defecere cuncti flores, madefactus aqua revivescit et hibernas coronas facit. summa natura eius in nomine est, appellati, quoniam non marcescat.", "st": "21.23"}, {"sp": "N", "t": "in nomine et cyani colos, item holochrysi.", "st": "21.24"}, {"sp": "N", "t": "Omnes autem hi flores non fuere in usu Alexandri Magni aetate, quoniam proximi a morte eius auctores siluere de illis; quo manifestum est postea placuisse. a Graecis tamen repertos quis dubitet, non aliter Italia usurpante nomina illorum?", "st": "21.24"}, {"sp": "N", "t": "at, Hercules, petellio ipsa nomen inposuit, autumnali circaque vepres nascenti. ei tantum color es⟨t⟩ commendatus, qui est rosae silvestris, folia parva, quina; mirumque in eo flore inflecti cacumen et e nodis intort⟨a⟩ folia nasci parvolo calice ac versicolori luteum semen includentia. luteo et bellio, pastillicantibus quinquagenis quinis barbulis. coronant pratenses hi flore; at sine usu plerique et ideo sine nominibus, quin et his ipsis alia alii vocabula inponunt.", "st": "21.25"}, {"sp": "N", "t": "chrysocome sive chrysitis non habet Latinam appellationem. palmi altitudine est, comantibus fulgore auri corymbis, radice nigra, ex austero dulci, in petrosis opacisque nascens.", "st": "21.26"}, {"sp": "N", "t": "Et fere peractis colorum quoque celeberrimis, transit ratio ad eas coronas, quae varietate sola placent. duo earum genera, quando aliae flore constant, aliae folio. florem esse dixerim genistas, namque et his decerpitur lateus; item rhododendron, item zizipha, qua⟨e⟩ Cappadocia vocantur; his odoratus similisque olearum fioribus. in vepribus nascitur cyclaminum, de quo plura alias. flos eius Colossinus in coronas admittitur.", "st": "21.27"}, {"sp": "N", "t": "Folio coronantium milac⟨e⟩s et hederae corymbique earum optinent principatum, de quibus in fruticum loco abunde diximus. sunt et alia genera nominibus Graecis indicanda, quia nostris maiore ex parte huius nomenclaturae defuit cura; et pleraque eorum in exteris terris nascuntur, nobis tamen consectanda, quoniam de natura sermo, non de Italia est.", "st": "21.28"}, {"sp": "N", "t": "Ergo in coronamenta folio venere melotrum, spiraea, ⟨o⟩riganum, cneorum, quod casiam Hyginus vocat, et, quod cunilaginem, conyza, melissophyllum, quod apiastrum, melilotum, quod sertulam Campanam vocamus. est enim in Campania Italiae laudatissima, Graecis in Sunio, mox Chalcidica et Cretica, ubicumque vero asperis et silvestribus nata. coronas ex ea antiquitus factitatas indicio est nomen sertulae, quod occupavit. odor est croco vicinus et flos, ipsa cana; placet maxime foliis brevissimis atque pinguissimis.", "st": "21.29"}, {"sp": "N", "t": "Folio coronat et trifolium. tria eius genera: min⟨y⟩ant⟨h⟩es vocant Graeci, alii ⟨a⟩sphaltion, maiore folio, quo utuntur coronarii; alterum acuto oxytriphyllon; tertium ex omnibus minutissimum. inter haec nervosi cauliculi quibusdam, ut maratho, hippomaratho, myophono; utuntur et ferulis, corymbis hederae et flore purpureo et in alio genere earum silvestribus rosis simili. sed in his quoque colos tantum delectat, odor autem abest. et cneori duo genera, nigri atque candidi; hoc et odoratum, ramosa ambo. florent post aequinoctium autumnum.", "st": "21.30"}, {"sp": "N", "t": "totidem et origani in coronamentis species, alterius enim nullum semen; id, cui odor est, Creticum vocatur.", "st": "21.30"}, {"sp": "N", "t": "Totidem et thymi, candidum ac nigricans. floret autem circa solstitia; ⟨t⟩um et apes decerpunt, ut augurium mellis s⟨i⟩t; proventum enim sperant apiarii large florescente eo. laeditur imbribus amittitque florem. semen thymi non potest deprehendi, cum origani, perquam minutum, non tamen fallat. sed quid interest occultasse id naturam? in flore ipso intellegitur satoque eo nascitur. quid non temptavere homines? mellis Attici in toto orbe summa laus existimatur; ergo translatum est ex Attica thymum et vix flore, uti docemur, satum. sed alia ratio naturae obstitit, non durante Attico thymo nisi in adflatu maris. erat quidem haec opinio antiqua in omni thymo, ideoque non nasci in Arcadia, cu⟨m⟩ oleam non putarent gigni nisi intra CCC stadia a mari. thymo quidem nunc etiam lapideos campos in provincia Narbonensi refertos scimus, hoc paene solo reditu, e longinquis regionibus pecudum milibus convenientibus, ut thymo vescantur.", "st": "21.31"}, {"sp": "N", "t": "Et conyzae duo genera in coronamentis, mas ac femina. differentia in folio: tenuius feminae et constrictius angustiusque, imbricatum. mas et ramosior. flos quoque magis splendet eius, serotinus utrique post arcturum. mas odore gravior, femina acutior et ideo contra bestiarum morsus aptior. folia feminae mellis odorem habent, masculae radix a quibusdam libanotis appellatur, de qua diximus.", "st": "21.32"}, {"sp": "N", "t": "Et⟨i⟩a⟨m⟩num folio coronant lovis flos, amaracum, hemerocalles, habrotonum, Helenium, sisymbrium, serpullum, omnia surculosa rosae modo. colore tantum placet Iovis flos, odor abest, sicut et illi, qui Graece phlox vocatur. et ramis autem et folio odorata sunt excepto serpull. Helenium e lacrimis Helenae dicitur natum, et ideo in Helene insula laudatissimum; est autem frutex humi se spargens dodrantalibus ramulis, serpullo simili folio.", "st": "21.33"}, {"sp": "N", "t": "Habrotonum odore iucunde gravi floret aestate; flos est aurei coloris. vacuum sponte provenit, cacumine suo se propagat. seritur autem semine melius quam radice aut surculo, semine quoque non sine negotio; plantaria transferuntur—sic et Adonium—, utrumque aestate. alsiosa enim admodum sunt, ⟨u⟩t sole tamen nimio laedantur. sed ubi convaluere, rutae vice fruticant. habrotono simile odore leucanthemum est, flore albo, foliosum.", "st": "21.34"}, {"sp": "N", "t": "Amaracum Diocles medicus et Sicula gens appellavere, quod Aegyptus et Syria sampsucum. seritur utroque genere, et seine et ramo, vivacius supra dictis et odore mollius. copiosum amaraco aeque quam habrotono semen, sed habrotono radix una et alte descendens, ceteris in summa terra leviter haerens. reliquorum satio autumno fere incipiente, nec non et vere quibusdam locis, umbraque gaudent et aqua ac fimo.", "st": "21.35"}, {"sp": "N", "t": "Nyctegreton inter pauca miratus est Democritus, coloris hysgini, folio spinae, nec a terra se adtollentem, praecipuam in Gedrosia. narrat erui post aequinoctium vernum radicitus siccarique ad lunam XXX diebus, ita lucere noctibus; Magos Parthorumque reges hac herba uti ad vota suscipienda. eandem vocari chenamychen, quoniam anseres a primo conspectu eius expavescant, ab aliis nyctalopa, quoniam e longinquo noctibus fulgeat.", "st": "21.36"}, {"sp": "N", "t": "Melilotos ubique nascitur, laudatissima tamen in Attica; ubicumque vero recens, nec candicans et croco quam simillima, quamquam in Italia odoratior candida.", "st": "21.37"}, {"sp": "N", "t": "Florum prima ver nuntiat viola alba, tepidioribus vero locis etiam hieme emicat; post ea, quae ion appellatur et purpurea, proxime flamme⟨u⟩m, quod phlox vocatur, silvestre dumtaxat. cyclaminum bis anno, vere et autumno; aestates hiemesque fugit. seriores supra dictis aliquanto narcissus et lilium trans maria, in Italia quidem, ut diximus, post rosam. Ver⟨um⟩ in Graecia tardius etiamnum anemone; est autem haec silvestrium bulborum flos, alia quam quae dicetur in medicis. sequitur oenanthe ac melanium et ex silvestribus heli⟨o⟩chrysos, deinde alterum genus anemones, quae limonia vocatur, post hanc gladiolus comitatus hyacintho. novissima rosa, eademque prima deficit excepta sativa; e ceteris hyacinthus maxime durat et viola alba et oenanthe, sed haec ita, si devolsa crebro prohibeatur in semen ire. nascitur locis tepidis; odor idem ei, qui germinantibus uvis, atque inde nomen. hyacinthum comitatur fabula duplex, luctum praeferen⟨ti⟩s eius, quem Apollo dilexerat, aut ex Aiacis cruore editi, ita discurrentibus venis, ut Graecarum litterarum figura Al legatur inscriptum. heliochrysus florem habet auro similem, folium tenue, cauliculum quoque gracilem, sed durum. hoc coronare se Magi, si et unguenta sumantur ex auro, quod apyron vocant, ad gratiam quoque vitae gloriamque pertinere arbitrantur.", "st": "21.38"}, {"sp": "N", "t": "Et verni quidem flores hi sunt;", "st": "21.38"}, {"sp": "N", "t": "succedunt illis aestivi, lychnis et Iovis flos et alterum genus lilii, item tiphyon et amaracus, quem Phrygium cognominant. sed maxime spectabilis pothos. duo genera huius: unum, cui flos hyacinthi est, alter candidus, qui fere nascitur tumulis, quoniam fortius durat. et iris aestate floret. abeunt et hi marcescuntque. alii rursus subeunt autumno: tertium genus lilii et crocum et orsini utraque genera, unum hebes, alterum odoratum, primis omnia imbribus emicantia. coronarii quidem et spinae flore utuntur, quippe cum spinae albae cauliculi inter oblectamenta quoque gulae condiantur. hic est trans maria ordo florum. in Italia violis succedit rosa, huic intervenit lilium, rosam cyanus excipit, cyanum amarantus. nam vicapervica semper viret, in modum liniae foliis geniculatim circumdata, topiaria herba, inopiam tamen florum aliquando supplet. haec a Graecis chamaedaphne vocatur.", "st": "21.39"}, {"sp": "N", "t": "Vita longissima violae albae trimatu. ab eo tenpore degenerat. rosa et quinquennium perfert non recisa nec adusta. illo enim modo iuvenescit. diximus et terram referre plurimum. nam in Aegypto sine odore haec omnia, tantumque myrtis odor praecipuus; ali⟨o⟩qui etiam binis mensibus antecedit germinatio omnium. rosaria a favonio fossa oportet esse iterumque solstitio, et id agendum, ut intra id tempus purgata ac pura sint.", "st": "21.40"}, {"sp": "N", "t": "Verum hortis coronamentisque maxime alvaria et apes conveniunt, res praecipui quaestus conpendiique, cum favet. harum ergo causa oportet serere thymum, apiastrum, rosam, violas, lilium, cytisum, fabam, erviliam, cunilam, papaver, conyzam, casiam, melilotum, melissophyllum, cerinthen. ea est autem folio candido, incurvo, cubitalis, capite concavo mellis sucum habente. horum floris avidissimae sunt atque etiam sinapis, quod miremur, cum olivae florem ab his non attingi constet; ideo hanc arborem procul esse melius sit, cum aliquas quam proxime seri conveniat, quae et evolantium examina invitent nec longius abire patiantur.", "st": "21.41"}, {"sp": "N", "t": "Cornum quoque arborem caveri oporteat. flore eius degustato alvo cita moriuntur. remedium sorba contusa e melle praebere his vel urinam hominis vel boum aut grana punici mali Ammineo vino conspersa. at genistas circumseri alvariis gratissimum.", "st": "21.42"}, {"sp": "N", "t": "Mirum est dignumque memoratu de alimentis quod conperi. Hostilia vicus adluitur Pado. huius inquilini pabulo circa deficiente inponunt navibus alvos noctibusque a⟨d⟩ quina milia passuum contrario amne subvehunt. egressae luce apes pastaeque ad naves cotidie remeant mutantes locum, donec pondere ipso pressis navibus plenae alvi intellegantur revectisque eximantur mella.", "st": "21.43"}, {"sp": "N", "t": "et in Hispania mulis provehunt simili de causa.", "st": "21.43"}, {"sp": "N", "t": "tantumque pabulum refert, ut mella quoque venenata fiant. Heracliae in Ponto quibusdam annis perniciosissima existunt ab iisdem apibus facta, nec dixere auctores, e quibus floribus ea fierent! nos trademus quae conperimus. herba est ab exitio et iumentorum quidem, sed praecipue caprarum appellata aegolethron. huius flore concipiunt noxium virus aquoso vere marcescentis. ita fit, ut non omnibus annis sentiatur malum. venenati signa sunt, quod omnino non densatur, quod color magis rutilus est, odor alienus, sternumenta protinus movens, quod ponderosius innoxio. qui edere, abiciunt se humi refrigerationem quaerentes, nam et sudore diffluunt. remedia sunt multa, quae suis locis dicemus; sed quoniam statim repraesentari aliqua in tantis insidiis oportet, mulsum vetus e melle optimo et ruta, salsamenta etiam, si reiciantur, sumpta crebro. certumque est id malum per excrementa ad canes etiam pervenire similiterque torqueri eos. mulsum tamen ex eo inveteratum innocuum esse constat, et feminarum cutem nullo melius emendari cum costo, suggillata cum aloe.", "st": "21.44"}, {"sp": "N", "t": "Aliud genus in eodem Ponti situ, gente Sannorum, mellis, quod ab insania, quam gignit, maenomenon vocant. id existimatur contrahi flore rhododendri, quo scatent silvae. gensque ea, cum ceram in tributa Romanis praestet, mel, quoniam exitiale est, non vendit. et in Perside et in Mauretaniae Caesariensis Gaetulia, contermina Massaesylis, venenati favi gignuntur, quidamque a parte, quo nihil esse fallacius potest, nisi quod livore deprehenduntur. quid sibi voluisse naturam his arbitremur insidiis, ut ab iisdem apibus nec omnibus annis fierent aut non totis favis? parum enim erat genuisse rem, in qua venenum facillime daretur? etiamne hoc ipsa in melle tot animalibus dedit? quid sibi voluit, nisi ut cautiorem minusque avidum faceret hominem? non enim et ipsis apibus iam cuspides dederat et quidem venenatas, remedio adversus has utique non differendo? ergo malvae suco aut foliorum hederae perungui salutare est vel percussos eas bibere. mirum tamen est venena portantes ore fingentesque ipsas non mori, nisi quod illa domina rerum omnium hanc dedit repugnantiam apibus, sicut contra serpentes Psyllis Marsisque inter homines.", "st": "21.45"}, {"sp": "N", "t": "Aliud in Creta miraculum mellis: mons est CarinaV̅I̅I̅I̅I̅ passuum ambitu, intra quod spatium muscae non reperiuntur, natumque ibi mel nusquam attingunt. hoc experimento singulare medicamentis eligitur.", "st": "21.46"}, {"sp": "N", "t": "Alvaria orientem aequinoctialem spectare convenit. aquilonem evitent, nec favonium minus. alvus optim⟨a⟩ e cortice, secunda ferula, tertia vimine; multi et e speculari lapide fecere, ut ⟨o⟩perantes intus spectarent. circumlini alvos fimo bubulo utilissimum, operculum a tergo esse ambulatorium, ut pro⟨f⟩eratur intus, si magna sit alvus aut sterilis operatio, ne desperatione curam abiciant; id paulatim reduci fallente operis incremento. alvos hieme stramento operiri, crebro suffiri, maxime fimo bubulo. cognatum hoc iis innascentes bestiolas necat, araneos, papiliones, teredines, apesque ipsas excitat. et araneorum quidem exitium facilius est; papilio, pestis maior, lucernis tollitur vere, cum maturescat malva, noctu interlunio caelo sereno accensis ante alvos. in eam flammam sese ingerunt.", "st": "21.47"}, {"sp": "N", "t": "Si cibus sentiatur deesse apibus, uvas passas siccasve ficos tusas ad fores earum posuisse conveniat, item lanas tractas madentes passo aut defruto aut aqua mulsa, gallinarum etiam crudas carnes. quibusdam et aestatibus iidem cibi praestandi, cum siccitas continua florum alimentum abstulit. alvorum, cum mel eximatur, inlini oportet exitus melissophyllo aut genista tritis, aut medias alba vite praecingi, ne apes diffugiant. vasa mellaria et favos lavari aqua praecipiunt, hac decocta fieri saluberrimum acetum.", "st": "21.48"}, {"sp": "N", "t": "Cera fit expressis favis, sed ante purificatis aqua ac triduo in te⟨n⟩ebris siccatis, quarto die liquatis igni in novo fictili, aqua favos tegente, tunc sporta colatis. rursus in eadem olla coquitur cera cum eadem aqua excipiturque alia frigida, vasis melle circumlitis. optima quae Punica vocatur, proxima quam maxime fulva odorisque mellei, pura, natione autem Pontica, quod constare equidem miror inter venenata mella, dein Cretica, plurimum enim ex propoli habet, de qua diximus in natura apium. post has Corsica, quoniam ex buxo fit, habere quan⟨d⟩am vim medicaminis putatur. Punica fit hoc modo: ventilatur sub diu saepius cera fulva, dein fervet in aqua marina ex alto petita addito nitro. inde lingulis hauriunt florem, id est candidissima quaeque, transfunduntque in vas, quod exiguum frigidae habeat, et rursus marina decocunt separatim, dein vas ipsum aut aquam refrigerant. et cum hoc ter fecere, iuncea crate sub diu siccant sole lunaque. haec enim candorem facit, sol siccat, et, ne liquefaciat, protegunt tenui linteo. candidissima vero fit post insolationem etiamnum recocta. Punica medicinis utilissima. nigrescit cera addito chartarum cinere, sicut anchusa admixta rubet, variosque in colores pigmentis trahitur ad reddendas similitudines et innumeros mortalium usus parietumque etiam et armorum tutelam. cetera de melle apibusque in natura earum dicta sunt.", "st": "21.49"}, {"sp": "N", "t": "Et hortorum quidem omnis fere peracta ratio est;", "st": "21.49"}, {"sp": "N", "t": "secuntur herbae sponte nascentes, quibus pleraeque gentium utuntur in cibis maximeque Aegyptus, frugum quidem fertilissima, sed ut prope sola iis carere possit. tanta est ciborum ex herbis abundantia. in Italia paucissimas novimus, fraga, tamnum, ruscum, batim marinam, batim hortensiam, quas aliqui asparagum Gallicum vocant, praeter has pastinacam pratensem, lupum salictarium, eaque verius oblectamenta quam cibos.", "st": "21.50"}, {"sp": "N", "t": "In Aegypto nobilissima est colocasia, quam cyamon aliqui vocant. hanc e Nilo metunt, caule, cum coctus est, araneoso in mandendo, thyrso autem, qui inter folia emicat, spectabili, foliis latissimis, etiam si arboreis conparentur, ad similitudinem eorum, quae personata in nostris amnibus vocamus, adeoque Nili sui dotibus gaudent, ut inplexis colocasiae foliis in variam speciem vasorum potare gratissimum habeant. seritur iam haec in Italia.", "st": "21.51"}, {"sp": "N", "t": "In Aegypto proxima auctoritas cichorio est, quod diximus intubum erraticum. nascitur post vergilias, floret particulatim. radix ei lenta, quare etiam ad vincula utuntur illa. anthalium longius a flumine nascitur, mespili magnitudine et rotunditate, sine nucleo, sine cortice, folio cyperi. mandunt igni comparatum. mandunt et oetum, cui pauca folia minimaque, verum radix magna. arachidne quidem et aracos, cum habeant radices ramosas ac multiplices, nec folium nec herbam ullam aut quicquam aliud supra terram habent. reliqua volgarium in cibis apud eos herbarum nomina: c⟨ho⟩ndryl⟨l⟩a, hypoc⟨hoe⟩ris, cauca⟨l⟩is, enthryscum, scandix, come, quae ab aliis tragopogon vocatur, foliis croco simillimis, parthenium, trychnum, corchorus et ab aequinoctio nascentes aphace, achynops. epipetron vocant quae numquam floret. at e contrario ap⟨h⟩ace subinde marcescente flore emittit alium tota hieme totoque vere usque in aestatem.", "st": "21.52"}, {"sp": "N", "t": "Multas praeterea ignobiles habent, sed maxime celebrant cnecon Italiae ignotam, ipsis autem oleo, non cibo gratam. hoc faciunt e semine eius. differentia prima: silvestris et mitior. silvestrium duae species. una mitiori similis, caule tamen rigido; itaque et colu antiquae utebantur exili, quare quidam atractylida vocant. semen eius candidum et grande, amarum. altera hirsutior, torosiore caule et qui paene humi serpat, minuto semine. aculeatarum generis haec est, quoniam distinguenda sunt et genera.", "st": "21.53"}, {"sp": "N", "t": "Ergo quaedam herbarum spinosae sunt, quaedam sine spinis. spinosarum multae species. in totum spina est asparagus, scorpio, nullum enim folium habent. quaedam spinosa foliata sunt, ut carduus, er⟨y⟩nge, glycyrrhiza, urtica; his enim omnibus foliis inest aculeata mordacitas. aliqua et secundum spinam habent folium, ut tribulus et anonis. quaedam in folio non habent et in caule habent, ut pheos, quod aliqui stoeben appellavere. hippophaes spinis geniculatum. tribu⟨l⟩o proprietas, quod et fructum spinosum habet.", "st": "21.54"}, {"sp": "N", "t": "Ex omnibus his generibus urtica maxime noscitur acetabulis in flore purpuream lanuginem fundentibus, saepe altior binis (ubitis. plures eius differentiae: silvestris, quam et feminam vocant, mitiorque; et silvestri quae dicitur canina acrior, caule quoque mordaci, fimbriatis foliis; quae vero etiam odorem fundit Herculanea vocatur. semen omnibus copiosum, nigrum. mirum sine ullis spinarum aculeis lanuginem ipsam esse noxiam et tactu tantum levi pruritum pusulasque confestim adusto similes existere. notum est [et] remedium olei. sed mordacitas non protinus cum ipsa herba gignitur, nec nisi solibus roborata. incipiens quidem ipsa nasci vere non ingrato, multis etiam religioso in cibo est ad pellendos totius anni morbos. silvestrium quoque radix omnem carnem teneriorem facit simul cocta. quae innoxia est, morsu carens, lamium vocatur. de scorpione dicemus inter medicas.", "st": "21.55"}, {"sp": "N", "t": "Carduus et folia et caules spinosae lanuginis habet, item acorna, leucacanthos, chal⟨ceos,⟩⟨c⟩necos, polyacanthos, onopyxos, helxine, scolymos. chamaeleon in foliis non habet aculeos. est et illa differentia, quod quaedam in his multicaulia ramosaque sunt, ut carduus, uno autem caule ne⟨c⟩ ramosum cnecos. quaedam cacumine tantum spinosa sunt, ut erynge. quaedam aestate florent, ut tetralix et helxine. scolymos quoque sero floret et diu. acornaa cneco colore tantum rufo distinguitur et pinguiore suco. idem erat atractylis quoque, nisi candidior esset et nisi sanguineum sucum funderet, qua de causa phonos vocatur a quibusdam, odore etiam gravis, sero maturescente semine nec ante autumnum, quamquam id de omnibus spinosis dici potest. verum omnia haec et semine et radice nasci possunt. scolymus carduorum generis ab his distat, quod radix eius vescendo est decocta. mirum, quod sine intervallo tota aestate aliud floret in eo genere, aliud concipit, aliud parturit. aculei arescente folio desinunt pungere. Hel⟨x⟩ine rara visu est neque in omnibus terris, a radice foliosa, ex qua media veluti malum extuberat contectum sua fronde. huius vertex summus lacrimam continet iucundi saporis, acanthicen mastic⟨h⟩en appellatam.", "st": "21.56"}, {"sp": "N", "t": "Et cactos quoque in Sicilia tantum nascitur, suae proprietatis et ipse. in terra serpunt caules a radice emissi, lato folio et spinoso. caules vocant cact⟨o⟩s, nec fastidiunt in cibis inveteratos ⟨quo⟩que. unum autem caulem rectum habet, quem vocant ⟨p⟩t⟨er⟩nica, eiusdem suavitatis, sed vetustatis inpatientem. semen ei lanuginis, quam pappum vocant, quo detracto et cortice teneritas similis cerebro palmae est. vocant ascalia⟨n⟩.", "st": "21.57"}, {"sp": "N", "t": "Tribulus non nisi in palustribus nascitur. dura res alibi, iuxta Nilum et Strymonem amnes ⟨r⟩ecipitur in cib⟨o⟩s, inclinatus in vadum, folio lato atque effigie ulmi, pediculo longo. at in reliquo orbe genera II, uni cicerculae folia, alteri aculeata. hic et serius floret magisque saepta obsidet villarum. semen ei rotundius, nigrum, in siliqua, alteri harenaceum. spinosorum etiamnum aliud genus anonis. in ramis enim spinas habet adposito folio rutae simili, toto caule foliato in modum coronae. sequitur arata, frugibus inimica vivaxque praecipue.", "st": "21.58"}, {"sp": "N", "t": "Aculeatarum caules aliquarum per terram serpunt, ut eius, quam coronopum vocant. e diverso stat anchusa inficiendo ligno cerisque radicis aptae, stant e mitioribus anthemis et phyllanthes et anemone et ap⟨h⟩ace. caule foliato est crepis et lotos.", "st": "21.59"}, {"sp": "N", "t": "Differentia foliorum et hic quae in arboribus, brevitate pediculi ac longitudine, angustiis ipsius folii, amplitudine, iam vero angulis, incisuris, odore, flore. diuturnior hic quibusdam per partes florentibus, ut ocimo, heliotropio, aphacae, onochi⟨li.⟩", "st": "21.60"}, {"sp": "N", "t": "multis inter haec aeterna folia, sicut quibusdam arborum, inprimisque heliotropio, adianto, poli⟨o⟩.", "st": "21.60"}, {"sp": "N", "t": "Aliud rursus spicatarum genus, ex quo est a⟨ch⟩ynops, alopecuros, steleph⟨u⟩ros,—quam quidam ortygem vocant, alii plantaginem, de qua plura dicemus inter medicas —, ⟨t⟩hryallis. ex his alopecuros spicam habet mollem et lanuginem densam, non dissimilem vulpium caudis, unde et nomen. proxima e⟨i⟩ est et stelephuros, nisi quod illa particulatim floret. cichorion et similia circa terram folia habent; germinant ab radice post vergilias.", "st": "21.61"}, {"sp": "N", "t": "Perdicium et aliae gentes quam Aegyptii edunt. nomen dedit avis id maxime eruens. crassas plurimasque habet radices. item ornithogale caule tenero, candido, semipeda⟨li⟩, molli, tribus aut quattuor agnatis, radice bulbosa; coquitur in pulte.", "st": "21.62"}, {"sp": "N", "t": "Mirum loton herbam et aegilopa non nisi post annum e semine suo nasci. mira et anthemidis natura, quod a summo florere incipit, cum ceterae omnes, quae particulatim florent, ab ima sui parte incipiant.", "st": "21.63"}, {"sp": "N", "t": "Notabile et in lappa, quae adhaerescit, quod in ipsa flos nascitur non evidens, sed intus occultus, et intra se ⟨ger⟩minat velut animalia, quae in se pariunt. circa Opuntem⟨e⟩&gt;s⟨t⟩ herba etiam homini dulcis, mirumque e folio eius radicem fieri ac sic eam nasci.", "st": "21.64"}, {"sp": "N", "t": "⟨I⟩asine unum folium habet, sed ita implicatum, ut plura videantur. ch⟨o⟩ndrylla amara est et acris in radice suci. amara et aphace et quae picris nominatur, et ipsa toto anno florens; nomen ei amaritudo inposuit.", "st": "21.65"}, {"sp": "N", "t": "Notabilis et scillae crocique natura, quod, cum omnes herbae folium primum emittant, mox in caulem rotundentur, in his caulis prior intellegitur quam folium. et in croco quidam flos inpellitur caule, in scilla vero caulis exit, deinde ex eo flos emergit, eademque ter floret, ut diximus, tria tempora arationum ostendens.", "st": "21.66"}, {"sp": "N", "t": "Bulborum generi quidam adnumerant et cypiri, hoc est gladioli, radicem. dulcis ea est et quae decocta panem etiam gratiorem faciat ponderosioremque simul subacta. non dissimilis est et quae thesium vocatur, gustu aspera.", "st": "21.67"}, {"sp": "N", "t": "Ceterae eiusdem generis folio differunt: asphodelus oblongum et angustum habet, scilla latum et tractabile, gladiolus simile nomini. asphodelus manditur et semine tosto et bulbo, set hoc in cinere tosto, dein sale et oleo addito, praeterea tuso cum ficis, praecipua voluptate, ut videtur Hesiodo. tradunt et ante portas villarum satum remedio esse contra veneficiorum noxiam. asphodeli mentionem et Homerus fecit. radix eius napis modicis similis est, neque alia numerosior LXXX simul acervatis saepe bulbis. Theophrastus et fere Graeci princepsque Pythagoras caulem eius cubitalem et saepe duum cubitorum, foliis porri silvestris, anthericum vocavere, radicem vero, id est bulbos, asphodelum. nostri illud albucum vocant et asphodelum ⟨hast⟩ulam regiam, caulis acinosi, ac duo genera faciunt. albuco scapus cubitalis, amplus, purus levisque, de quo Mago praecipit exitu mensis Marti et initio Aprilis, cum floruerit, nondum semine eius intumescente, demetendum findendosque scapos et quarto die in solem proferendos, ita siccati manipulos faciendos. idem ⟨o⟩ist⟨o⟩n adicit a Graecis vocari, quam inter ulvas sagittam appellamus. hanc ab idibus Maiis usque in finem Octobris mensis decorticari atque leni sole siccari iubet; idem et gladiolum alterum, quem cypiron vocant, et ipsum palustrem, Iulio mense toto secari iubet ad radicem tertioque die in sole siccari, done candidus fiat, cotidie autem ante solem occidentem in tectum referri, quoniam palustribus desectis nocturni rores noceant.", "st": "21.68"}, {"sp": "N", "t": "Similia praecipit et de iunco, quem mariscum appellant, ad texendas tegetes et ipsum lunio mense eximi ad Iulium medium praecipiens, cetera desiccando eadem, quae de ulva suo loco diximus. alterum genus iuncorum facit, quod marinum et a Graecis oxyschoenon vocari invenio. tria genera eius: acuti, sterilis, quem marem et oxyn Graeci vocant; reliqua feminini, ferentis semen nigrum: quem mela⟨n⟩cran⟨i⟩m appellant, crassior hic et fruticosior, magisque etiamnum tertius, qui vocatur holoschoenus. ex his melancranis sine aliis generibus nascitur, oxys autem et holoschoenus eodem caespite. utilissimus ad vitilia holoschoenus, quia mollis et carnosus est; fert fructum ovorum cohaerentium modo. nascitur autem et is, quem marem appellavimus, ex semetipso, cacumine in terram defixo, melancranis autem suo semine. alioqui omnium radices omnibus annis intermoriuntur. usus ad nassas marinas, vitilium elegantiam, lucernarum lumina, praecipua medulla, amplitudine iuxta maritimas Alpes tanta, ut inciso ventre inpleant paene unciarum latitudinem, in Aegypto vero cub⟨it⟩orum longitudinem non aliis utiliorem. quidam etiamnum unum genus faciunt iunci trianguli —cyperon vocant—, multi vero non discernunt a cypiro vicinitate nominis. nos distinguemus utrumque.", "st": "21.69"}, {"sp": "N", "t": "Cypirus est gladiolus, ut diximus, radice bulbosa, laudatissimus in insulis Creta, dein Naxo et postea in Phoenice. Cretico candor odorque vicinus nardo, Naxio acrior, Phoenicio exiguum spirans, nullus Aegyptio, nam et ibi nascitur. discutit duritias corporum; iam remedia enim dicemus, quoniam et florum odorumque generi est magnus usus in medicina, quod ad cypiron attinet, Apollodorum quidem sequar, qui negat bibendum, quamquam professus efficacissimum esse adversus calculos. os eo fovet. feminis quidem abortus facere non dubitat; mirumque, tradit barbaros suffitum huius herbae excipientes ore lienes consumere et non egredi domibus nisi ab hoc suffitu, vegetiores enim firmioresque sic etiam in die fieri; intertriginum et alarum vitiis perfrictionibusque cum oleo inlitum non dubie mederi.", "st": "21.69"}, {"sp": "N", "t": "Cyperos iuncus est, qualiter diximus, angulosus, iuxta terram candidus, cacumine niger pinguisque. folia ima porraceis exiliora, in cacumine minuta, inter quae semen est. radix olivae nigrae similis, quam, cum oblonga est, cyperida vocant, magni in medicina usus. laus cypero prima Hammoniaco, secunda Rhodio, tertia Theraeo, novissima Aegyptio. qu⟨i⟩ et confudit intellectum, quoniam et cypiros ibi nascitur. sed cypirosradice durissima vixque spirans, c⟨yp⟩eris odor et ipsis nardum imitans. est et per se Indica herba, quae cypira vocatur, zingiberis effigie; commanducata croci vim reddit. cypero vis in medicine psilotri. inlinitur pterygiis ulceribusque genitalium et quae in umore sunt omnibus, sicut oris ulceribus. radix adversus serpentium ictus et scorpionum praesentis remedii est. vulvas aperit pota; largiori tanta vis, ut et expellat eas. urinam ciet et calculos, ob id utilissima hydropicis. inlinitur et ulceribus, quae serpunt, sed his praecipua, quae in stomacho sunt, e vino vel aceto inlita.", "st": "21.70"}, {"sp": "N", "t": "Iunci radix in tribus heminis aquae decocta ad tertias tussi medetur. semen tostum et in aqua potum sistit alvum et feminarum menses. capitis dolores facit. qui vocatur holoschoenus… quae proxima sunt radici, commanducantur adversus araneorum morsus. invenio etiamnum unum iunci genus quod ⟨Eu⟩ripicen vocant; huius semine somnum allici, set modum servandum, ne sopor fiat.", "st": "21.71"}, {"sp": "N", "t": "Obit⟨er⟩ et odorati iunci medicinae dicentur, quoniam et in… Syria Coele, ut suo loco rettulimus, nascitur. laudatissimus ex Nabataea cognomine teuchitis, proximus Babylonius, pessimus ex Africa ac sine odore. est autem rotundus, vinosae mordacitatis ad linguam; sincerus in confricando odorem rosae emittit rubentibus fragmentis. discutit inflationes, ob id stomacho utilis bilemque reicientibus. singultus sedat, ructus movet, urinam ciet, vesicae medetur. ad muliebres usus decoquitur. opisthotonicis cum resina arida inponitur excalfactoria v⟨i⟩.", "st": "21.72"}, {"sp": "N", "t": "Rosa adstringit, refrigerat. usus eius dividitur in folia et flores, capita. foliorum partes, quae sunt candidae, ungues vocantur. in flore aliud est semen, aliud capillus, in capite aliud cortex, aliud calix. folium siccatur aut tribus modis exprimitur: per se, cum ungues non detrahuntur—ibi enim umoris plurimum—, aut cum detractis unguibus reliqua pars aut oleo aut vino maceratur in sole vasis vitreis. quidam et salem admiscent, nonnulli et anchusam aut aspalathum aut iuncum odoratum, quia talis maxime prodest vulvae ac dysintericis. exprimuntur eadem folia detractis unguibus trita per linteum spissum in aereum vas, lenique igni sucus coquitur, donec fiat crassitudo mellis. ad haec eligi oportet odoratissima quaeque folia.", "st": "21.73"}, {"sp": "N", "t": "vinum quomodo fieret e rosa, diximus inter genera vini. usus suci ad aures, oris ulcera, gingivas, tonsillas gargarizati, stomachum, vulvas, sedis vitia, capitis dolores—in febri per se vel cum aceto—, somnos, nausias. folia uruntur in calliblepharum, et siccis femina adsperguntur. epiphoras quoque arida leniunt. flos somnum facit, inhibet fluctiones mulierum, maxime albas, in posca potus et sanguinis excreationes, stomachi quoque dolores, quantum… in vini cyathis tribus. seminis optimum crocinum nec anniculo vetustius et in umbra siccatum; nigrum inutile. dentium dolori inlinitur, urinam ciet, stomacho inponitur, item igni sacro non veteri. naribus subductum caput purgat. capita pota ventrem et sanguinem sistunt. ungues rosae epiphoris salubres sunt; ulcera enim oculorum rosa sordescunt, praeterquam initiis epiphorae ita, ut arida cum pane inponatur. folia quidem intus stomachi rosionibus et [intus] ventris aut intestinorum utilissima et praecordiis, vel inlita. cibo quoque lapathi modo condiuntur. cavendus in his situs celeriter insidens. et aridis aut expressis aliquis usus. diapasmata inde fiunt ad sudores coercendos ita, ut a balineis inarescant corpori, dein frigida abluantur. silvestris pilulae cum adipe ursino alopecias emendant.", "st": "21.73"}, {"sp": "N", "t": "Lilii radices multis modis florem suum nobilitant, contra serpentium ictus ex vino potae et contra fungorum venena. propter clavos pedum in vino decoquuntur triduoque non solvuntur. cum adipe aut oleo decoctae pilos quoque adustis reddunt. e mulso potae inutilem sanguinem cum alvo trahunt, lienique et ruptis, vulsis prosunt et mensibus feminarum, in vino vero decoctae inpositaeque cum melle nervis praecisis. medenttr contra lichenas et lepras, et furfures in facie emendant, erugant corpora, cu⟨te⟩m. folia in aceto cocta vulneribus inponuntur, si testium, melius cum hyoscyamo et farina tritici.semen inlinitur igni sacro, flos et folia ulcerum vetustati, sucus qui flore expressus est—ab aliis mel vocatur, ab aliis syrium—ad emolliendas vulvas sudoresque faciendos et suppurationes concoquendas.", "st": "21.74"}, {"sp": "N", "t": "Narcissi duo genera in usum medici recipiunt, purpureo flore et alterum herbaceum, hunc stomacho inutilem et ideo vomitorium alvosque solventem, nervis inimicum, caput gravantem et a narce narcissum dictum, non a fabuloso puero. utriusque radix mulsei saporis est. ambustis prodest exiguo e melle, sic et vulneribus et luxatis; panis vero cum melle et ae⟨ri⟩na farina, sic et infixa corpori extrahit. in polenta tritus oleoque contusis medetur et lapide percussis. purgat vulnera permixtus farinae, nigras vitiligines emaculat. ex hoc flore fit narcissinum oleum ad emolliendas duritias, calfacienda quae alserint, auribus utilissimum, sed et capitis dolores facit.", "st": "21.75"}, {"sp": "N", "t": "Violae silvestres et sativae. purpureae refrigerant. contra inflammationes inlinuntur stomacho, ardenti inponuntur et capiti in fronte, oculorum privatim epiphoris et sede procidente volvave et contra suppurationes. crapulam et gravedines capitis inpositis coronis olfactuque discutiunt, anginas ex aqua potae. id, quod purpureum est ex his, comitialibus medetur, maxime pueris, in aqua potum. semen violae scorpionibus adversatur. contra flos albae suppurata aperit, ipsa discutit. et alba autem et lutea extenuat menses, urinam ciet. minor vis est recentibus, ideoque aridis post annum utendum. lutea dimidio cyatho in aquae tribus menses trahit. radices eius cum aceto inlitae sedant lienem, item podagram, oculorum autem inflammationes cum murra et croco. folia cum melle purgant capitis ulcera, cum cerato rimas sedis et quae in umidis sunt, ex aceto vero collectiones sanant.", "st": "21.76"}, {"sp": "N", "t": "Baccar in medicinae usu aliqui ex nostris perpressam vocant. auxiliatur contra serpentes, capitis dolores fervoresque, item epiphoras. inponitur mammis tumentibus a partu et aegilopiis incipientibus ignibusque sacris. odor somnum gignit. radicem decoctam bibere spasticis, eversis, convulsis, suspiriosis salutare est et in tussi vetere. rami eius tres quattuorve decocuntur ad tertias partes; haec potio mulieres ex abortu purgat. laterum punctiones tollit et vesicae calculos. tundituret u⟨t⟩ili⟨ter⟩ in diapasmata. vestibus odoris gratia inseritur. combretum, quod simile ei diximus, tritum cum axungia vulnera mire sanat.", "st": "21.77"}, {"sp": "N", "t": "Asarum iocinerum vitiis salutare esse traditur uncia sumpta in hemina mulsi mixti. alvum purgat ellebori modo, hydropicis prodest et praecordiis vulvisque ac morbo regio. in mustum si addatur, facit vinum urinis ciendis. effoditur cum folia mittit, siccatur et conditur. in umbra situm celerrime sentit.", "st": "21.78"}, {"sp": "N", "t": "Et quoniam quidam, ut diximus, nardum rusticum nominavere radicem baccaris, contexemus et Gallici nardi remedia, in hunc locum dilata in peregrinis arboribus. ergo adversus serpentes duabus drachmis in vino succurrit, inflationibus coli vel ex aqua vel ex vino, item iocineris et renium suffusisque felle et hydropicis, per se vel cum absinthio. sistit purgationum mulierum impetus.", "st": "21.79"}, {"sp": "N", "t": "Eius vero, quod phun eodem loco appellavimus, radix datur potui trita vel decocta ad strangulatus vel pectoris dolores vel laterum quoque. menses ciet. bibitur cum vino.", "st": "21.80"}, {"sp": "N", "t": "Crocum melle non solvitur nulloque dulci, facillime autem vino aut aqua. utilissimum in medicina, adservatur cornea pyxide. discutit inflammationes omnes quidem, sed oculorum maxime ex ovo; i⟨tem⟩ vulvarum quoque strangulatus, stomachi exulcerationes, pectoris et renium, iocinerum, pulmonum vesicarumque, peculiariter inflammationi earum vehementer utile, item tussi et pleuriticis. tollit et pruritus, urinas ciet. qui crocum prius biberint, crapulam non sentient, ebrietati resistent. coronae quoque ex eo mulcent ebrietatem. somnum facit, caput leniter movet, venerem stimulat. flos eius igni sacro inlinitur cum creta Cimolia. ipsum plurumis medicaminibus miscetur, collyrio uni etiam nomen dedit.", "st": "21.81"}, {"sp": "N", "t": "faex quoque expressi unguento crocino, quod crocomagma appellant, habet suas utilitates contra suffusiones oculorum, urinas. magis excalfacit quam crocum ipsum. optimum quod gustatu salivam dentesque maxime inficit.", "st": "21.82"}, {"sp": "N", "t": "Iris rufa melior quam candida. infantibus eam circumligari salutare est, dentientibus praecipue et tussientibus taeniarumve vitio laborantibus instillari. ceteri effectus eius non multum a melle differunt. ulcera purgat capitis, praecipue suppurationes veteres. alvum solvit duabus drachmis cum melle, tussim, tormina, inflationes pota, lienes ex aceto. contra serpentium et araneorum morsus ex posca valet; contra scorpiones duarum drachmarum pondere in pane vel aqua sumitur; contra canum morsus ex oleo inponitur et contra perfrictiones. sic et nervorum doloribus, lumbis vero et coxendicibus cum resina inlinitur. vis ei concalfactoria. naribus subducta sternumenta movet caputque purgat. dolori capitis cum cotoneis malis aut strutheis inlinitur. crapulas quoque et orthopnoeas discutit. vomitiones ciet duobus obolis sumpta. ossa fracta extrahit inposita cum melle. ad paronychia farina eius utuntur, in vino ad clavos et verrucas, triduoque non solvit⟨ur.⟩ halitus oris commanducata abolet alarumque vitia. suco duritias omnes emollit, somnum conciliat, sed genituram consumit. sedis rimas et condylomata omniaque in corpore excrescentia sanat. sunt qui silvestrem xyrim vocent. strumas haec vel panos vel inguina discutit. praecipitur, ut sinistra manu ad hos usus eruatur colligentesque dicant, cuius hominis vitiique causa eximant. scelus herbariorum aperietur et in hac mentione: partem eius servant et quarundam aliarum herbarum, sicuti plantaginis, et si parum mercedis tulisse se arbitrantur rursusque opus quaerunt, partem eam, quam servavere, eodem loco infodiunt, credo, ut vitia, quae sanaverint, faciant rebellare. saliuncae radix in vino decocta sistit vomitiones, conroborat stomachum.", "st": "21.83"}, {"sp": "N", "t": "Polio Musaeus et Hesiodus perungui iubent dignationis gloriaeque avidos, polium tractari… coli, polium contra venena haberi, contra serpentes substerni, uri, in vino decoqui recens vel aridum inlinique vel potari. medici splenicis propinant ex aceto, morbo regio in vino, et hydropicis incipientibus in vino decoctum; vulneribus quoque sic inlinunt. secundas mulierum partusque emortuos pellit, item dolores corporis. vesicas inanit, epiphoris inlinitur. nec magis alia herba convenit medicamento, quod alexipharmacon vocant. stomacho tamen inutile esse caputque eo inpleri et abortum fieri puto. aliqui negant et religionem addunt, ubi inventum sit, protinus adalligandum contra oculorum suffusiones cavendumque, ne terram attingat. hi et folia eius thymo similia tradunt, nisi quod molliora sunt et lanatiore canitie. cum ruta silvestri et si teratur ex aqua caelesti, aspids mitigare dicitur, ⟨e⟩t non secus atque cy⟨ti⟩nus adstringit t cohibet vulnera prohibetque serpere.", "st": "21.84"}, {"sp": "N", "t": "Holochrysos medetur stranguriae in vino, et oculorum epiphoris inlitu, cum faece vero vini cremata et polenta lichenas emendat. chrysocomes radix calfacit et adstringit. datur potui ad iocinerum vitia, item pulmonum, vulvae dolores in aqua mulsa decocta. ciet menstrua et, si cruda detur, hydropicorum aquam.", "st": "21.85"}, {"sp": "N", "t": "Melissophyllo sive melittaena si perunguantur alvi, non fugient apes; nullo enim magis flore gaudent. scopis eius examina facillime continentur. idem praesentissimum est contra ictus earum vesparumque et similium, sicut araneorum, item scorpionum, item contra volvarum strangulationes addito nitro, contra tormina e vino. folia eius strumis inlinuntur et sedis vitiis cum sale. decoctae sucus feminas purgat et inflammationes discutit et ulcera sanat. articularios morbos sedat canisque morsus. prodest dysintericis veteribus et coeliacis, orthopnoicis, lienibus, ulceribus thoracis. caligines oculorum suco cum melle inungui eximium habetur.", "st": "21.86"}, {"sp": "N", "t": "Melilotos quoque oculis medetur cum luteo ovi aut lini semine. maxillarum quoque dolores lenit et capitis cum rosaceo, item aurium e passo quaeque in manibus intumescant vel erumpant, stomachi dolores in vino decocta vel cruda tritaque. idem effectus et ad vulvas, ad testes vero et sedem prociduam quaeque et alia ibi sint vitia… recentem ex aqua decoctam vel ex passo. adiecto rosaceo inlinitur ad carcinomata. defervescit in vino dulci. peculiariter et contra meliceridas efficax.", "st": "21.87"}, {"sp": "N", "t": "Trifolium scio credi praevalere contra serpentium et scorpionum ictus ex vino aut posca, seminis granis xx potis vel foliis et tota herba decocta, serpentesque numquam in trifolio aspici; praeterea a celebratis auctoribus contra omnia venena pro antidoto sufficere xxv grana eius, quod minyanthes ex eo appellavimus, tradi, multa alia praeterea in remediis eius adscribi. sed me contra sententias eorum gravissimi viri auctoritas movet, Sophocles enim poeta venenatum id dicit, Simos quoque ex medicis, decocti aut contriti sucum infusum corpori easdem uredines facere, quas si percussis a serpente inponatur. ergo non aliter utendum eo quam contra venena censuerim. fortassis enim et his venenis inter se contraria sit natura, sicut multis aliis. item animadverto semen eius, cuius minima sint folia, utile esse ad custodiendam mulierum cutis gratiam in facie inlitum.", "st": "21.88"}, {"sp": "N", "t": "Thymum colligi oportet in flore et in umbra siccari. duo autem sunt genera eius: candidum, radice lignosa, in collibus nascens, quod et praefertur; alterum nigrius florisque nigri. utraque oculorum claritati multum conferre existimantur et in cibo et in medicamentis; item diutinae tussi ecligmate faciles excreationes facere cum aceto et sale, sanguinem concrescere non pati e melle, longas faucium destillationes extra inlita cum sinapi extenuare, item stomachi et ventris vitia. modicis tamen utendum est, quoniam excalfaciunt; qua vi sistunt alvum, quae si exulcerata sit, denarii pondus in sextarium aceti et mellis addi oporteat, item si lateris dolor sit, aut inter scapulas aut in thorace. praecordiis medentur ex aceto cum melle, quae potio datur et in alienatione mentis ac melancholicis. datur et comitialibus, quos correptos olfactu excitat thymum. aiunt et dormire eos oportere in molli thymo. prodest et orthopnoicis et anhelatori⟨bu⟩s mulierumque mensibus retardatis vel si emortui sint in utero partus, decoctum in aqua ad tertias, et viris vero contra inflationes cum melle et aceto et si venter turgueat testesve aut si vesicae dolor exigat. e vino tumores et impetus inpositum tollit, item cum aceto callum et verrucas. coxendicibus inponitur cum vino, articulariis morbis et luxatis tritum ac lanae inspersum ex oleo, ambustis cum adipe suillo. dant et potion⟨i⟩in articulariis ⟨m⟩o⟨r⟩bis trium obolorum pondere in tribus cyathis aceti et mellis, in fastidio tritum cum sale.", "st": "21.89"}, {"sp": "N", "t": "Hemerocalles pallidum e viridi et molle folium habet, grandi radice odorataque, bulbosa. cum melle inposita ventri aquas pellit et sanguinem etiam inutilem. folia epiphoris oculorum mammarumque post partum inlinuntur.", "st": "21.90"}, {"sp": "N", "t": "Helenium ab Helena, ut diximus, natum favere creditur formae, cutem mulierum in facie reliquoque corpore nutrire incorruptam. praeterea putant usu eius quandam ⟨v⟩ita⟨e⟩ gratiam his veneremque conciliari. adtribuunt et hilaritatis effectum eidem potae in vino eumque, quem habuerit nepenthes illud praedicatum ab Homero, quod tristitia omnis aboleretur. est autem suci praedulcis. prodest et orthopnoicis radix eius in aqua ieiunis pota. est autem candida intus et dulcis. bibitur et contra serpentium ictus ex vino. mures quoque contrita dicitur necare.", "st": "21.91"}, {"sp": "N", "t": "Habrotonum duorum traditur generum, campestre ac montanum. hoc feminam, illud marem intellegi volunt. amaritudo absinthii in utroque. Siculum laudatissimum, dein Galaticum. usus et foliis, sed maior semini ad excalfaciendum, ideo nervis utile, tussi, orthopnoeae, ruptis, convulsis, lumbis, urinae angustiis. datur bibendum manualibus fasciculis decoctis ad tertias partes; ex his quaternis cyathis bibitur. datur et semen tusum in aqua drachmae pondere. prodest et vulvae. concoquit panos cum farina hordeacia et oculorum inflammationi inlinitur cotoneo malo cocto. serpentes fugat; contra ictus earum bibitur cum vino inliniturque, efficacissimum contra ea, quorum veneno tremores et frigus accidunt, ut scorpionum et phalangiorum; et contra venena alia pota prodest et quoquo modo algentibus. vis ⟨e⟩i et extrahendi ea, quae inhaereant corporibus. pellit et interaneorum mala. ramo eius, si subiciatur pulvino, venerem stimulari aiunt, efficacissimamque esse herbam contra omnia veneficia, quibus coitus inhibeatur.", "st": "21.92"}, {"sp": "N", "t": "Leucanthemum suspiriosis medetur duabus partibus aceti permixtum. sampsuchum sive amaracum in Cypro laudatissimum et odoratissimum scorpionibus adversatur ex aceto ac sale inlitum. menstruis quoque multum confert inpositum. minor eidem poto vis. cohibet et oculorum epiphoras cum polenta. sucus decocti tormina discutit. et urinis et hydropicis utile. movet aridum sternumenta. fit ex eo et oleum, quod sam⟨p⟩suc⟨h⟩inum vocatur aut amaracinum, ad excalfaciendos molliendosque nervos; et vulvas calfacit. folia suggillatis cum melle et luxatis cum cera prosunt.", "st": "21.93"}, {"sp": "N", "t": "Anemonas coronarias tantum diximus, nunc reddemus et medicas. sunt qui ⟨ph⟩re⟨n⟩ion vocent. duo eius genera: prima silvestris, altera cultis nascens, utraque sabulosis. huius plures species: aut enim phoenicium florem habet, quae et copiosissima est, aut purpureum aut lacteum. harum trium folia apio similia sunt nec temere semipedem altitudine excedunt, cacumine asparagi. flos numquam se aperit nisi vento spirante, unde et nomen accepere. silvestri amplitudo maior, latioribus durioribus⟨que⟩ foliis, flore phoenicio. hanc errore ducti argemonen putant multi, alii rursus papaver, quod rh⟨oe⟩an vocavimus. sed distinctio magna, quod utraque haec postea florent, nec aut sucum illarum anemonae reddunt aut calyces habent nec nisi asparagi cacumen. prosunt anemonae capitis doloribus et inflammationibus, vulvis mulierum. lact⟨e⟩ quoque et menstrua ' cient cum tisana sumptae aut vellere adpositae. radix commanducata pituitam trahit, dentes sanat, decocta oculorum epiphoras et cicatrices. Magi⟨occ⟩ultum quiddam iis tribuere, qua⟨e⟩ primum aspiciatur eo anno tolli iubentes dicique colligi eam tertianis et quartanis remedio, postea adligari florem panno russeo et in umbra adservari, ita, cum opus sit, adalligari. quae ex his phoenicium florem habet, radice contrita cuicumque animalium inposita ulcus facit styptica vi; et ideo expurgandis ulceribus adhibetur.", "st": "21.94"}, {"sp": "N", "t": "Oenanthe herba nascitur in petris, folio pastinacae, radice magna, numerosa. caulis eius et folia cum melle ac vino nigro pota facilitatem pariendi praestant secundasque purgant, tussim e melle tollunt, urinam cient. radix et vesicae vitiis medetur.", "st": "21.95"}, {"sp": "N", "t": "Heliochrysum alii chrysanth⟨em⟩on vocant, ramulos habet candidos, folia subalbida, habrotono similia, ad solis repercussum aureae lucis in orbem veluti corymbis dependentibus, qui numquam marcescunt; qua de causa deos coronant illo, quod diligentissime servavit Ptolemaeus Aegypti rex. nascitur in frutectis. ciet urinas e vino pota et menses. duritias et inflammationes discutit, ambustis cum melle inponitur. contra serpentium ictus et lumborum vitia bibitur. sanguinem concretum ventris aut vesicae absumit cum mulso. folia eius trita trium obolorum pondere sistunt profluvia mulierum in vino albo. vestes tuetur odore non ineleganti.", "st": "21.96"}, {"sp": "N", "t": "Hyacinthus in Gallia maxime provenit. hoc ibi ⟨fu⟩co hysginum tingunt. radix est bulbacea, mangonicis venaliciis pulchre nota, quae e vino dulci inlita pubertatem coercet et non patitur erumpere. torminibus et araneorum morsibus resistit. urinam impellit. contra serpentes et scorpiones morbumque regium semen eius cum habrotono datur.", "st": "21.97"}, {"sp": "N", "t": "Lychnis quoque flammea illa adversus serpentes et scorpiones et crabrones similiaque bibitur e vin⟨o⟩ semine trito. silvestris eadem stomacho inutilis. alvum solvit, ad detrahendam bilem efficacissima duabus drachmnis, scorpionibus tam contraria, ut omnino visa ea torpescant. radicem eius Asiani boliten vocant, qua adalligata oculo albugines tolli dicuntur.", "st": "21.98"}, {"sp": "N", "t": "Et vicapervica sive chamaedaphne arida tusa hydropicis datur in aqua cocleari⟨i⟩ mensura, celerrimeque reddunt aquam. eadem decocta in cinere sparsa vino tumores siccat. auribus suco medetur. alvi ⟨viti⟩is inposita plurimum prodesse dicitur.", "st": "21.99"}, {"sp": "N", "t": "Rusci radix decocta bibitur alternis diebus in calculorum valitudine et tortuosiore urina vel cruenta. radicem pridie erui oportet, postero mane decoqui, ex eo sextario vini cyathis duobus misceri. sunt qui et crudam radicem tritam ex aqua bibant, et in totum ad virilia cauliculis eius ex aceto tritis nihil utilius putant.", "st": "21.100"}, {"sp": "N", "t": "Batis quoque alvum mollit. inlinitur podagricis cruda et contunsa. acinon et coronarum causa et ciborum Aegyptii serunt, eademque erat quae ocimum, nisi hirsutior ramis ac foliis esset et admodum odorata. ciet et menses et urinas.", "st": "21.101"}, {"sp": "N", "t": "Colocasia Glaucias acria corporis leniri putavit et stomachum iuvari.", "st": "21.102"}, {"sp": "N", "t": "Anthalii, quod Aegyptii edunt, nullum alium reperi usum. sed est herba anthyllium, quam alii anthyllum vocant, duorum generum: foliis et ramis lenticulae similis, palmi altitudine, sabulosis, apricis nascens, subsalsa gustanti; altera chamaepityi similis, brevior et hirsutior, purpurei floris, odore gravis, in saxosis nascens. prior vulvis aptissima, ex rosaceo ac lacte inposita, et vulneribus. bibitur in stranguria reniumque ⟨h⟩arenis tribus drachmis. altera bibitur in duritia vulvarum et in torminibus et in comitiali morbo cum melle et aceto quattuor drachmis.", "st": "21.103"}, {"sp": "N", "t": "Parthenium alii leucanthes, alii amaracum vocant, Celsus apud nos perdicium et muralem. nascitur in hortorum saepibus, flore albo, odore mali, sapore amaro. ad insidendum decoctae in duritia vulvarum et inflammationibus …, sicca cum melle et aceto inposita detrahit bilem atram; ob hoc contra vertigines utilis et calculosis. inlinitur et sacro igni, item strumis cum axungia inveterata. Magi contra tertianas sinistra manu evelli eam iubent dicique, cuius causa vellatur, nec respicere, dein eius folium aegri linguae subicere, ut mox in cyatho aquae devoretur.", "st": "21.104"}, {"sp": "N", "t": "Trychno, quam quidam strychnon scripsere, utinam nec coronarii in Aegypto uterentur, quos invitat hederae foliorum similitudo in duobus eius generibus, quorum alterum, cui acini coccini, granosi in folliculis, halicacabon vocant, alii callion, nostri autem vesicariam, quoniam vesicae et calculis prosit. frutex est surculosus verius quam herba, folliculis magnis latisque et turbinatis grandi intus acino, qui maturescit Novembri mense. tertio folia sunt ocimi, minime diligenter demonstrando remedia, non venena, tractantibus, quippe insaniam facit parvo quoque suco. quamquam et Graeci auctores in iocum vertere. drachmae enim pondere lusum ⟨f⟩u⟨r⟩oris gigni dixerunt, species vanas imaginesque conspicuas obversari demonstrantes; duplicatum hunc modum legitimam insaniam facere; quidquid vero adiciatur ponderi, repraesentari mortem. hoc est venenum, quod innocentissimi auctores simpliciter dorycnion appellavere ab eo, quod cuspides in proeliis tinguerentur illo passim nascente. qu⟨i⟩ parcius insectabantur, manicon nominavere; qui nequiter occultabant, erythron aut neuradaaut, ut nonnulli, perisson, ne cavendi quidem causa curiosius dicendum. quin et alterum genus, quod ⟨h⟩alicacabon vocant, soporiferum est atque etiam opio velocius ad mortem, ab aliis morion, ab aliis mo⟨ly⟩ appellatum, laudatum vero a Diocle et Euenore, a Timaristo quidem etiam carmine. mira oblivione innocentia ⟨e⟩—quippe praesentaneum remedium ad dentium mobiles firmandos, si colluerentur halicacabo⟨i⟩n vino— exceptionem addidere, ne diutius id fieret; delirationem enim gigni. n⟨o⟩n demonstranda remedia, quorum medicina maioris mali periculum adferat: commendetur ergo in cibis tertium genus licet a⟨c⟩ praeferatur hortensi⟨i⟩s saporibus et nil sit corporis malorum, cui non salutares trychnos Xenocrates praedicet; non tamen auxilia e⟨a⟩rum tanti sunt, ut id⟨eo⟩ plura nos de iis commemorare fas putem, praesertim tanta copia innoxiorum medicaminum. halicacabi radicem bibunt qui vaticinari gallantesque vere ad confirmandas superstitiones aspici se volunt. remedio est— id enim libentius rettulerim—aqua copiosa mulsa calida potu. nec illud praeteribo, aspidum naturae halicacabum in tantum adversam, ut radice eius propius admota soporetur illa sopore enecans vis earum. ergo trita ex oleo percussis auxiliatur.", "st": "21.105"}, {"sp": "N", "t": "Corchorum Alexandrini cibi herba est convolutis foliis ad similitudinem m⟨o⟩ri, praecordiis, ut ferunt, utilis alopeciisque et lentigini. boum quoque scabiem celerrime sanari ea inven⟨i⟩o, apud Nicandrum quidem et serpentium morsus, antequam flore⟨a⟩t.", "st": "21.106"}, {"sp": "N", "t": "Nec de cneco sive atractylide verbosius dici par esset, Aegyptia herba, ni magnum contra venenata animalia praeberet auxilium, item adversus fungos. constat a scorpione percussos, quamdiu teneant eam herbam, non sentire cruciatum.", "st": "21.107"}, {"sp": "N", "t": "Et pesolutam Aegyptus in hortis serit, coronarum gratia. duo genera eius: femina ac mas; utraque subdita venerem inhiberi, virorum maxime, tradunt.", "st": "21.108"}, {"sp": "N", "t": "Et quoniam in mensuris quoque ac ponderibus crebro Graecis nominibus utendum est, interpretationem eorum semel hoc in loco ponemus: drachma Attica—fere enim Attica observatione medici utuntur— denarii argentei habet pondus, eademque vi obolos pondere efficit, obolus x chalcos. cyathus pendet per se drachmas x; cum acetabuli mensura dicitur, significat heminae quartam, id est drachmas xv. mna, quam nostri minam vocant, pendet drachmas Atticas C.", "st": "21.109"}, {"sp": "HDR", "t": "Liber XXII", "st": "22"}, {"sp": "N", "t": "Implesse poterant miraculum sui natura atque tellus reputantium vel prioris tantum voluminis dotes totque genera herbarum utilitatibus hominum aut voluptatibus genita. sed quanto plura restant quantoque mirabiliora inventu! illa enim maiore in parte cibi aut odoris decorisve commendatio ad numerosa experimenta duxit; reliquarum potentia adprobat, nihil ab rerum natura sine aliqua occultiore causa gigni.", "st": "22.1"}, {"sp": "N", "t": "Equidem et formae gratia ritusque perpetui in corporibus suis aliquas exterarum gentium uti herbis quibusdam adverto animo. inlinunt certe aliis aliae faciem in populis barbarorum feminae; maresque etiam apud Dacos et Sarmatas corpora sua inscribunt. simili plantagini —glastum in Gallia vocatur—Britannorum coniuges nurusque toto corpore oblitae quibusdam in sacris nudae incedunt, Aethiopum colorem imitantes.", "st": "22.2"}, {"sp": "N", "t": "iam vero infici vestes scimus admirabili fuco, atque, ut sileamus Galatiae, Africae, Lusitaniae grani coccum imperatoriis dicatum paludamentis, transalpina Gallia herbis Tyria atque conchylia tinguit et omnes alios colores. nec quaerit in profundis murices seque obiciendo escam, dum praeripit, beluis marinis intacta etiam ancoris scrutatur vada, ut inveniat per quod facilius matrona adultero placeat, corruptor insidietur nuptae: stans et in sicco carpit, quo frugem modo. sed culpant ablui usu; alioqui fulgentius instrui poterat luxuria, certe innocentius.", "st": "22.3"}, {"sp": "N", "t": "Non est nunc propositum ista consectari, nec ⟨c⟩om⟨m⟩ittemus, ut subiciendo viliora luxuriam u⟨t⟩ilitate circumscribamus, dicturi et alias herbis tingui parietes nec pingi lapide. nec tinguendi tamen rationem omisissemus, si umquam ea liberalium artium fuisset. interim fortius agetur, auctoritasque, quanta debet, etiam surdis, hoc est ignobilibus, herbis perhibebitur, siquidem auctores imperii Romani conditoresque immensum quiddam et hi⟨n⟩c sumpsere, quoniam non aliunde sagmina in remediis publicis fuere et in sacris legationibusque verbenae. certe utroque nomine idem significatur, hoc est gramen ex arce cum sua terra evolsum, ac semper e legatis, cum ad hostes clarigatumque mitterentur, id est res raptas dare repetitum, unus utique verbenarius vocabatur.", "st": "22.3"}, {"sp": "N", "t": "Corona quidem nulla fuit graminea nobilior in maiestate populi terrarum principis praemiisque gloriae. gemmatae et aureae, vallares, murales, rostratae, civicae, triumphales post hanc fuere suntque cunctae magno intervallo magnaque differentia. ceteras omnes singuli, et duces ipsi imperatoresque, militibus aut aliquando collegis dedere, decrevit in triumphis senatus cura belli solutus et populus otiosus,", "st": "22.4"}, {"sp": "N", "t": "graminea numquam nisi in desperatione suprema contigit, nulli nisi ab universo exercitu servato decreta. ceteras imperatores dedere, hanc solam miles imperatori. eadem vocatur obsidionalis liberatis obsidione abominandoque exitu totis castris. quod si civicae honos uno aliquo ac vel humillimo cive servato praeclarus sacerque habetur, quid tandem existimari debet unius virtute servatus universus exercitus? dabatur haec viridi e gramine decerpto inde, ubi obsessos servasset aliquis. namque summum apud antiquos signum victoriae erat herbam porrigere victos, hoc est terra et altrice ipsa humo et humatione etiam cedere, quem morem etiam nunc durare apud Germanos scio.", "st": "22.4"}, {"sp": "N", "t": "Donatus est ea L. Siccius Dentatus semel, cum civicas quattuordecim meruisset depugnassetque centiens viciens semper victor. tanto rarius est servatorem unum a servatis donari. quidam imperatores et saepius donati sunt, veluti P. Decius Mus tribunus militum ab exercitu, altera ab his, qui in praesidio obsessi fuerant, quanta esset eius honoris auctoritas, confessus religione, siquidem donatus bovem album Marti inmolavit et centum fulvos, qui ei virtutis causa dati fuerant simul ab obsessis. hic Decius postea se consul Imperioso conlega pro victoria devovit. data est et a senatu populoque Romano, qua claritate nihil equidem in rebus humanis sublimius duco, Fabio illi, qui rem omnem Romanam restituit non pugnando; nec data, cum magistrum equitum exercitumque eius servasset,—tune satius fuit nomine novo coronari appellatum patrem ab his, quos servaverat,—sed quo dictum est consensu honoratus est Hannibale Italia pulso, quae corona adhuc sola ipsius imperii manibus inposita est et, quod peculiare ei est, sola a tota Italia data.", "st": "22.5"}, {"sp": "N", "t": "Praeter hos contigit eius coronae honos M. Calpurnio Flammae tribuno militum in Sicilia, centurioni vero uni ad hoc tempus Cn. Petreio Atinati Cimbrico bello. primum pilum is capessens sub Catulo exclusam ab hoste legionem suam hortatus tribunum suum dubitantem per castra hostium erumpere interfecit legionemque eduxit. invenio apud auctores eundem praeter hunc honorem adstantibus Mario et Catulo cos. praetextatum immolasse ad tibicinem foculo posito. scripsit et Sulla dictator ab exercitu se quoque donatum apud Nolam legatum bello Marsico, idque etiam in villa sua Tusculana, quae fuit postea Ciceronis, pinxit. quod si verum est, hoc exsecrabiliorem eum dixerim, quandoquidem eam capiti suo proscriptione sua ipse detraxit, tanto paucioribus civium servatis quam postea occisis. addat etiamnum huic gloriae superbum cognomen Felicem, ipse tamen obsessis in toto orbe proscriptis hac corona Sertorio cessit. Aemilianum quoque Scipionem Varro auctor est donatum obsidionali in Africa Manilio consule, III cohortibus servatis totidemque ad servandas eas eductis, quod et statuae eius in foro suo divus Augustus ⟨in⟩scripsit. ipsum Augustum M. Cicerone filio consule idibus Septembribus senatus obsidionali donavit; adeo civica non satis videbatur. nec praeterea quemquam invenimus donatum.", "st": "22.6"}, {"sp": "N", "t": "Nullae ergo herbae fuere certae in hoc honore, sed quaecumque fuerant in periculi sede, quamvis ignobiles ignotaeque, honored nobilem faciebant, quod latere apud nos minus quidem miror cernens neglegi ea quoque, quae ad valitudinem conservandam cruciatusque corporis propulsandos et mortem arcendam pertinent. sed quis non mores iure castiget? addidere vivendi pretia deliciae luxusque; numquam fuit vitae cupido maior nec minor cura. aliorum hanc operae esse credimus ac ne mandato quidem nostro alios id agere, medicisque provisum esse pro ⟨m⟩o⟨r⟩bis. ipsi fruimur voluptatibus et, quo nihil equidem probrosius duco, vivimus aliena fiducia. immo vero plerisque ultro etiam inrisui sumus ista commentantes atque frivoli operis arguimur, magno quamquam inmensi laboris solatio, sperni cum rerum natura, quam certe non defuisse nobis docebimus et invisis quoque herbis inseruisse remedia, quippe cum medicinas dederit etiam aculeatis. haec enim proxime restant ex iis, quas priore libro nominavimus, in quibus ipsis providentiam naturae satis mirari amplectique non est. dederat quas diximus molles cibisque gratas, pinxerat remedia in floribus visuque ipso animos invitaverat etiam deliciis auxilia permiscens:⟨e⟩n, excogitavit aliquas aspectu hispidas, tactu truces, ut tantum non vocem ipsius fingentis illas rationemque reddentis exaudire videamur, ne scilicet depascat avida quadripes, ne procaces manus rapiant, ne neglecta vestigia obterant, ne insidens ales infringat, iis muniendo aculeis telisque armando, remediis ut tuta ac salva sint. ita hoc quoque, quod in iis odimus, hominum causa excogitatum est.", "st": "22.7"}, {"sp": "N", "t": "Clara in primis aculeatarum erynge est sive eryngion contra serpentes et venena omnia nascens. adversus ictus morsusque radix eius bibitur drachmae pondere in vino aut, si plerumque tales iniurias comitetur et febris, ex aqua. inlinitur plagis, peculiariter efficax contra ch⟨e⟩rsyd⟨r⟩os ac ranas. omnibus vero contra toxica et aconita efficaciorem Heraclides medicus in iure anseris decoctam arbitratur. Apollodorus adversus toxica cum rana decoquit, ceteri in aqua. ipsa dura, fruticosa, spinosis foliis, caule geniculato, cubitali et maiore aliquando, alia albicans, alia nigra, radice odorata. et sativa quidem est et sponte nascitur in asperis, saxosis, set in litoribus maris durior nigriorque, folio apii.", "st": "22.8"}, {"sp": "N", "t": "Ex his candidam nostri centum capita vocant. omnes eiusdem effectus, caule et radice in cibos Graecorum receptis utroque modo, sive coquere libeat sive cruda vesci. portentosum est, quod de ea traditur, radicem eius alterutrius sexus similitudinem referre, raro invento, set si viris contigerit mas, amabiles fieri; ob hoc et Phaonem Lesbium dilectum a Sappho, multa circa hoc non Magorum solum vanitate, sed etiam Pythagoricorum. sed in medico usu praeter supra dicta auxiliatur inflationibus, torminibus, cordis vitiis, stomacho, iocineri, praecordiis in aqua mulsa, lieni in posca, item ex mulsa renibus, stranguriae, opisthotonis, spasmis, lumbis, hydropicis, comitialibus, mulierum mensibus, sive subsidant sive abundent, vulvarumque omnibus vitiis. extrahit infixa corpori cum melle. strumas, parotidas, panos, recedentes ab ossibus carnes sanat cum axungia salsa et cerato, item fracturas. crapulam praesumpta arcet, alvum sistit. aliqui e nostris sub solstitio colligi eam iussere, ex aqua caelesti inponi omnibus cervicis vitiis. oculorum quoque albugines sanare adalligatam ⟨ali⟩qu⟨i⟩ tradiderunt.", "st": "22.9"}, {"sp": "N", "t": "Sunt qui et acanum ery⟨n⟩gio adscribant, spinosam brevemque et latam herbam spinisque latioribus. hanc inpositam sanguinem mire sistere.", "st": "22.10"}, {"sp": "N", "t": "Alii eryngen falso eandem putavere esse et glycyrr⟨h⟩izam, quare subiungi eam protinus refert. et ipsa sine dubio inter aculeatas est, foliis echinatis, pinguibus tactuque cum⟨m⟩inosis, fruticosa, binum cubitorum altitudine, flore hyacinthi, fructu pilularum platani magnitudinis. praestantissima in Cilicia, secunda Ponto, radice dulci et hac tantum in usu. capitur ea vergiliarum occasu, longa, sucosa ceu ⟨ly⟩cium, coloris buxei, melior qu⟨a⟩e nigra, quaeque lenta quam quae fragilis. usus in subditis decoctae ad tertias, cetero ad mellis crassitudinem, aliquando et tusae, quo genere et vulneribus inponitur et faucium vitiis omnibus, item voci utilissim⟨a⟩ suco sic, ut spissatus est, linguae subdito, item thoraci, iocineri. hac diximus sitim famemque sedari; ob id quidam adipson appellavere eam et hydropicis dedere, ne sitirent. ideo et conmanducata stomatice est ulceribus oris; inspersa saepe et pterygiis. sanat et vesicae scabiem, renium dolores, condylomata, ulcera genitalium. dedere eam quidam potui in quartanis drachmarum duarum pondere et piper ex hemina aquae. conmanducata sanguinem ex vulnere sistit. sunt qui et calculos ea pelli tradiderunt.", "st": "22.11"}, {"sp": "N", "t": "Tribuli unum genus in hortis nascitur, alterum in fluminibus tantum. sucus ex iis colligitur ad oculorum medicinas; est enim refrigerantis naturae et ideo utilis contra inflammationes collectionesque. ulcera per se erumpentia et praecipue in ore cum melle sanat, item tonsillas. potus calculos frangit. Thraces, qui ad Strymona habitant, foliis tribuli equos saginant, ipsi nucleo vivunt panem facientes praedulcem et qui contrahat ventrem. radix caste pureque collecta discutit strumas, semen adalligatum varicum dolores sedat, tritum vero in aqua sparsum pulices necat.", "st": "22.12"}, {"sp": "N", "t": "Stoebe, quam aliqui pheon vocant, decocta in vino praecipue auribus purulentis medetur, item oculis ictu cruentatis, haemorrhagiae quoque et dysinteriae infusa.", "st": "22.13"}, {"sp": "N", "t": "Hippophaes in sabulosis maritimis, spinis albis, hederae modo racemosa est, candidis, ex parte rubentibus acinis. radix suco madet, qui aut per se conditur aut pastillis farinae ervi. bilem detrahit oboli ponder⟨e⟩, saluberrime cum mulso. est altera hippophaes sine caule, sine flore, foliis tantum minutis. huius quoque sucus hydropicis mire prodest. debent adcommodatae esse et equorum naturae neque ex alia causa nomen accepisse. quippe quaedam animalium remediis nascuntur locupleti divinitate ad generanda praesidia, ut non sit mirari satis ingenium eius disponentis auxilia in genera, in causas, in tempora, ut aliis prosit⟨a⟩liud horis diesque nullus prope sine praesidiis reperiatur.", "st": "22.14"}, {"sp": "N", "t": "Urtica quid esse invisius potest? at illa praeter oleum, quod in Aegypto ex ea fieri diximus, vel plurimis scatet remediis. semen eius cicutae contrarium esse Nicander adfirmat, item fungis vel argento vivo, Apollodorus et salamandris cum iure coctae testudinis, item adversari hyoscyamo et serpenti⟨b⟩us et scorpionibus. quin ipsa illa amaritudo mordax uvas in ore procidentesque vulvas et infantium sedes tactu resilire cogit, lethargicos expergisci tactis cruribus magisque fronte. eadem canis morsibus addito sale medetur, sanguinem trita naribus indita sistit et magis radice. carcinomata et sordida ulcera sale admixto, item luxata sanat et panos, parotidas carnesque ab ossibus recedentes. semen potum cum sapa vulvam strangulatis aperit. profluvia narium sistit inpositum. vomitiones in aqua mulsa sumptum a cena faciles praestat duobus obolis, uno autem in vino poto lassitudines recreat. vulvae vitiis tostum acetabuli mensura, potum in sapa resistit stomachi inflationibus. orthopnoicis prodest cum melle et thoracem purgat eodem ecligmate et lateri medetur cum semine lini. addunt hysopum et piperis aliquid. inlinitur lieni, difficilem ventrem tostum cibo emollit. Hippocrates vulvam purgari poto eo pronuntiat, dolore levari tosto acetabuli mensura, dulci poto et inposito cum suco malvae, intestinorum animalia pelli cum hydromelite et sale, defluvia capitis semine inlito cohonestari. articulariis morbis et podagricis plurimi cum oleo vetere aut folia cum ursino adipe trita inponunt. ad eadem radix tusa cum aceto non minus utilis, item lieni, et cocta in vino discutit panos cum axungia vetere salsa. eadem psilotrum est sicca. condidit laudes eius Phanias physicus, utilissimam cibis coctam conditamve professus arteriae, tussi, ventris destillationi, stomacho, panis, parotidibus, pernionibus, cum oleo sudorem, coctam cum conchyliis ciere alvum, cum tisana pectus purgare mulierumque menses, cum sale ulcera, quae serpant, cohibere. suco quoque in usu est. expressus inlitus fronti sanguinem narium sistit, potus urinam ciet, calculos rumpit, uvam gargarizatus reprimit. semen colligi messibus oportet. Alexandrinum maxime laudatur. ad omnia haec et mitiores quidem teneraeque efficaces, sed praecipue silvestris illa, et hoc amplius lepras e facie tollit in vino pota. si quadripes fetum non admittat, urtica naturam fricandam monstrant.", "st": "22.15"}, {"sp": "N", "t": "Ea quoque, quam lamium inter genera earum appellavimus, mitissima et foliis non mordentibus, medetur cum mica salis contusis incussisque, ustis et strumis, tumoribus, podagris, vulneribus. album habet in medio folio, quod ignibus sacris medetur.", "st": "22.16"}, {"sp": "N", "t": "Quidam e nostris tempore discrevere genera, et autumnalis urticae radicem adalligatam in tertianis ita, ut aegri nuncupentur, cum eruatur ea radix, dicaturque cui et quorum filio eximatur, liberare morbo tradiderunt; hoc idem et contra quartanas pollere. iidem urticae radice addito sale infixa corpori extrahi, foliis cum axungia strumas discuti vel, si suppuraverint, erodi, compleri.", "st": "22.16"}, {"sp": "N", "t": "Ex argumento nomen accepit scorpio herba. semen enim habet ad similitudinem caudae scorpionis, folia pauca. valet adversus animal nominis sui. est et alia eiusdem nominis effectusque, sine foliis, asparagi caule, in cacumine aculeum habens et inde nomen.", "st": "22.17"}, {"sp": "N", "t": "Leucacantham alii phy⟨ll⟩on, alii ischada, alii polygonaton appellant, radice cypiri, quae commanducata dentium dolores sedat, item laterum et lumborum, ut Hicesius tradit, semine poto drachmis octo aut suco. eadem ruptis, convulsis medetur.", "st": "22.18"}, {"sp": "N", "t": "Helxinen aliqui perdicium vocant, quoniam perdices ea praecipue vescantur, alii sideritem, nonnulli parthenium. folia habet mixtae similitudinis plantagini et marruvio, cauliculos densos, leviter rubentes, semina in capitibus lappaceis adhaerescentia vestibus, unde et helxinen dictam volunt. sed nos qualis vera esset helxine diximus prior⟨e⟩ libro. haec autem inficit lanas, sanat ignes sacros et tumores collectionesque omnes et adusta, panos. sucus eius cum psi⟨m⟩ithio ignes sacros et guttura incipientia turgescere, item veterem tussim cyat⟨h⟩o hausto et omnia v⟨i⟩ti⟨a⟩ umid⟨a⟩, sicut tonsillas et aures cum rosaceo. inponitur et podagris cum caprino sebo ceraque Cypria.", "st": "22.19"}, {"sp": "N", "t": "Perdicium sive parthenium sive ⟨eti⟩am sideritis alia est; ab nostris herba urceolaris vocatur, a aliis astercum; folio similis ocimo, nigrior tantum, nascens in tegulis parietinisque. medetur cum mica salis trita iisdem omnibus, quibus lamium, et eodem modo, item vomicae calfacto suco pota, sed contra vulsa, rupta lapsusque et praecipitia, ut vehiculorum eversiones, singularis. verna carus Pericli Atheniensium principi, cum is in arce templum aedificaret repsiss⟨e⟩tque super altitudinem fastigii et inde cecidisset, hac herba dicitur sanatus, monstrata Pericli somnio a Minerva, quare parthenium vocari coepta est adsignaturque ei deae. hic est vernula, cuius effigies ex aere fusa est et nobilis ille splanchnoptes.", "st": "22.20"}, {"sp": "N", "t": "Chamaeleonem aliqui ixian vocant. duo genera eius: candidior asperiora habet folia, serpit in terra echini modo spinas erigens, radice dulci, odore gravi. quibusdam in locis viscum gignit album sub alis foliorum, maxime circa canis ortum, quo modo tura nasci dicuntur, unde et ⟨i⟩xia appellatur. hac mastiche utuntur mulieres. quare et chamaeleon vocetur, varietate foliorum evenit; mutat enim cum terra colores, hic niger, illic viridis, aliubi cyaneus, aliubi croceus atque aliis coloribus. ex his candidus hydropicos sanat suco radicis decoctae; bibitur drachma in passo. pellit et interaneorum animalia acetabuli mensura suci eiusdem in vino austero cum origani scopis. facitad difficultatem urinae. hic sucus occidit et canes suesque in polenta addita aqua et oleo, contrahit in se mures ac necat, nisi protinus aquam sorbeant. radicem eius aliqui concisam servari iubent funiculis pendentem decoque⟨re⟩que in cibo contra fluctiones, quas Graeci rheumatismos vocant. ex nigris aliqui marem dixere, cui flos purpureus esset, et feminam, cui violaceus; set una nascuntur caule cubitali, crassitudine digitali. radicibus e⟨o⟩rum lichenes curantur cum sulpure et bitumine una coctis, conmanducatis vero dentes mobiles aut in aceto decoctis. suco scabiem et quadripedum sanant. et ricinos canum necat, iuvencos quoque anginae modo, quare a quibusdam ulophyton vocatur, set et cynozolon propter gravitatem odoris. ferunt et haec viscum ulceribus utilissimum. omnium autem generum eorum radices scorpionibus adversantur.", "st": "22.21"}, {"sp": "N", "t": "Coronopus oblonga herba est cum fissuris. seritur interim, quoniam radix coeliacis praeclare facit in cinere tosta.", "st": "22.22"}, {"sp": "N", "t": "Et anchusae radix in usu est, digitali crassitudine. finditur papyri modo manusque inficit sanguineo colore, praeparat lanas pretiosis coloribus. sanat ulcera in cerato, praecipue senum, item adusta. liquari non potest in aqua, oleo dissolvitur; idque sincerae experimentum est. datur et ad renium dolores drachma eius potui in vino aut, si febris sit, in decocto balani; item iocinerum vitiis et lienis et bile subfusis. lepris et lentigini inlinitur ex aceto. folia trita cum melle et farina luxatis inponuntur, et pota drachmis duabus in mulso alvum sistunt. pulices necare radix in aqua decocta traditur.", "st": "22.23"}, {"sp": "N", "t": "Est et alia similis pseudoanchusa ob id appellata, a quibusdam vero echis aut doris et multis aliis nominibus, lanuginosior et minus pinguis, tenuioribus foliis, languidioribus. radix in ole⟨o⟩ non fundit rubentem sucum, et hoc ab anchusa discernitur. contra serpentes efficacissima potu foliorum vel seminis. folia ictibus inponuntur. virus serpentes fugat. bibitur et propter spina⟨m⟩. folium eius sinistra decerpi iubent Magi et, cuius causa sumatur, dici tertianisque febribus adalligari.", "st": "22.24"}, {"sp": "N", "t": "Est et alia herba proprio nomine onochilon, quam aliqui anchusam vocant, alii archebion, alii onochelim, aliqui rhexiam, multi enchrysam, parvo frutice, flore purpureo, asperis foliis et ramis, radice messibus sanguinea, cetero nigra, in sabulosis nascens, efficax contra serpentes maximeque viperas et radice et foliis, aeque cibo ac potu. vires habet messibus. folia trita odorem cucumeris reddunt. datur in cyathis tribus vulva procidente. pellit et taenias cum hysopo, et in dolore renium aut iocineris ex aqua mulsa, si febris sit, sin aliter, e vino bibitur. lentigini ac lepris radix inlinitur. habentes eam a serpentibus feriri negantur. est et alia huic similis flore rubro, minor, et ipsa ad eosdem usus, traduntque, conmanducata ea si inspuat⟨ur⟩, mori serpentem.", "st": "22.25"}, {"sp": "N", "t": "Anthemis magnis laudibus celebratur ab Asclepiade. aliqui leucanthemida vocant, alii leucanthemum, alii eranthemida, quoniam vere floreat; alii chamaemelon, quoniam odorem mali habeat. nonnulli melanthion vocant. genera eius tria fronde tantum distant, palmum non excedentia, parvis foliis… rutae candidis aut malinis aut purpureis. in macro solo aut iuxta semitas colligitur vere et in coronamenta reponitur. eodem tempore et medici folia tusa in pastillos digerunt, item florem et radicem. dantur omnia mixta drachmae unius pondere contra serpentium omnium ictus. pellunt mortuos partus, item menstrua in potu et urinam calculosque, inlita inflationes, iocinerum vitia, bilem subfusam, aegilopia, conmanducata ulcerum eruptiones manantes sana⟨n⟩t. ex omnibus his generibus ad calculos efficacissima est quae florem purpureum habet, cuius et foliorum et fruticis amplitudo maiuscula est. hanc proprie quidam eranthemim vocant.", "st": "22.26"}, {"sp": "N", "t": "Loton qui arborem putant tantum esse, vel Homero auctore coargui possunt. is enim inter herbas subnascentes deorum voluptati loton primam nominavit. folia eius cum melle oculorum cicatrices, argema, nubeculas discutiunt.", "st": "22.27"}, {"sp": "N", "t": "Est et lotometra, quae fit ex loto sata, ex cuius semine simili mil⟨i⟩o p⟨ut⟩ri fiunt panes in Aegypto a pastoribus, maxime aqua vel lacte subacti. negatur quicquam illo pane salubrius esse aut levius, dum caleat. refrigeratus difficilius concoquitur fitque ponderosus. constat eos, qui illo vivant, nec dysinteria nec tenesmo neque aliis morbis ventris infestari. itaque inter remedia eorum habetur.", "st": "22.28"}, {"sp": "N", "t": "Heliotropii miraculum saepius diximus cum sole se⟨s⟩e circumagentis etiam nubilo die; tantus sideris amor est. noctu velut desiderio contrahit caeruleum florem. genera eius duo, tricoccum et helioscopium. hoc altius, quamquam utrumque semipedalem altitudinem non excedit, ab im⟨a⟩ radice ramosum. semen in folliculo messibus colligitur. nascitur nonnisi in pingui solo cultoque maxime, tricoccum ubique. si decoquatur, invenio cibis placere et in lacte iucundius alvum molliri et, si decocti sucus bibatur, efficacissime exinaniri. maioris sucus excipitur aestate hora sexta, miscetur cum vino, sic firmior. capitis dolores sedat rosaceo admixto. verrucas cum sale tollit sucus e folio, unde nostri verrucariam herbam appellavere, aliis cognominari effectibus digniorem. namque et serpentibus et scorpionibus resistit ex vino aut aqua mulsa, ut Apollophanes et Apollodorus tradunt. folia infantium destillationibus, quod siriasim vocant, inlita medentur, item contractionibus, etiam si id comitialiler accidat. decocto quoque foveri os saluberrimum est. potum id pellit taenias et renium harenas. si cuminum adiciatur, calculos frangit. decoqui cum radice oportet, quae cum foliis et hircino sebo podagris inlinitur. alterum genus, quod tricoccum appellavimus et alio nomine scorpiuron vocatur, foliis non solum minoribus, sed etiam in terram vergentibus. semen ei est effigie scorpionis caudae, quare nomen. vis ad omnia venenata et phalangia, sed contra scorpiones praecipue inlita. non feriuntur habentes, et si terram surculo heliotropii circumscribat aliquis, negant scorpionem egredi, inposita vero herba aut uda omnino respersum protinus mori. seminis grana quattuor pota quartanis prodesse dicuntur, tria vero tertianis, vel si herba ipsa ter circumlata subiciatur capiti. semen et venerem stimulat, cum melle panos discutit. verrucas hoc utique heliotropium radicitus extrahit et excrescentia in sedibus. spinae quoque ac lumborum sanguinem corruptum trahit inlitum semen et potum in iure gallinacei decoctum aut cum beta et lente. cortex seminis liventibus colorem reddit. Magi heliotropium in quartanis quater, in tertianis ter adligari iubent ab ipso aegro precarique eum, soluturum se nodos liberatum, et ⟨i⟩acere non exempta herba.", "st": "22.29"}, {"sp": "N", "t": "Aliud adianto miraculum: aestate viret, bruma non marcescit, aquas respuit, perfusum mersumve sicco simile est—tanta dissociatio deprehenditur—, unde et nomen a Graecis alioqui frutici topiario. quidam callitrichon vocant, alii polytric⟨hon⟩, utrumque ab effectu. tinguit enim capillum et ad hoc decoquitur in vino cum semine apii adiecto oleo copios⟨o⟩, ut crispum densumque faciat; et defluere autem prohibet. duo genera eius: candidius et nigrum breviusque. id, quod maius est, polytrichon, aliqui trichomanes vocant. utrique ramuli nigro colore nitent, foliis felicis, ex quibus inferiora aspera ac fusca sunt, omnia autem contrariis pediculis, densa ex adverso inter se, radix nulla. umbrosas petras parietumque aspergines ac fontium maxime specus sequitur et saxa manantia, quod miremur, cum aquas non sentiat. calculos e corpore mire pellit frangitque, utique nigrum, qua de causa potius quam quod in saxis nasceretur a nostris saxifragum appellatum crediderim. bibitur e vino qua⟨nt⟩um terni decerpsere digiti. urinam cient, serpentium et araneorum venenis resistunt, in vino decocti alvum sistunt. capitis dolores corona ex his sedat. contra scolopendrae morsus inlinuntur, crebro auferendi, ne peru⟨ra⟩nt; hoc et in alopeciis. strumas discutiunt furfuresque in facie et capitis manantia ulcera. decoctum ex his prodest suspiriosis et iocineri et lieni et felle subfusis et hydropicis. stranguriae inlinuntur et renibus cum absinthio. secundas cient et menstrua. sanguinem sistunt ex aceto aut rubi suco poti. infantes quoque exulcerati perunguntur ex iis cum rosaceo et vino.—(⟨V⟩irus foliiin urina pueri inpubis tritum quidem cum aphronitro et inlitum ventri mulierum, ne rugosus fiat, praestare dicitur.) - perdices et gallinaceos pugnaciores fieri putant in cibum eorum additis, pecorique esse utilissimos.", "st": "22.30"}, {"sp": "N", "t": "Picris ab insigni amaritudine cognominatur, ut diximus, folio rotundo. tollit eximie verrucas. thesium quoque non dissimili amaritudine est, sed purgat alvum, in quem usum teritur ex aqua.", "st": "22.31"}, {"sp": "N", "t": "Asphodelum de clarissimis herbarum, ut quod hero⟨i⟩on aliqui appellaverint, Hesiodus et in silvis nasci dixit, Dionysius marem ac feminam esse. defectis corporibus et phthisicis constat bulbos eius cum tisana decoctos aptissime dari, panemque ex his cum farina subactis saluberrimum esse. Nicander et contra serpentes ac scorpiones vel caulem, quem anthericum vocavimus, vel semen vel bulbos dedit in vino tribus drachmis substravitque somno contra hos metus. datur et contra venenata marina et contra scolopendras terrestres. cocleae mire in Campania caulem eum persequuntur et sugendo arefaciunt. folia quoque inlinuntur venenatorum vulneribus ex vino. bulbi nervis articulisque cum polenta tunsi inlinuntur. prodest et concisis ex aceto lichenas fricare, item ulceribus putrescentibus ex aqua inponere, mammarum quoque et testium inflanmationibus. decocti in faece vini oculorum epiphoris supposito linteolo medentur. fere in quocumque morbo magis decoctis utuntur, item ad tibiarum taetra ulcera rimasque corporum quacumque in parte farina arefactorum. autumno autem colliguntur, cum plurimum valent. sucus quoque ex tusis expressus aut decoctis utilis fit corporis dolori cum melle, idem odorem corporis iucundum affectantibus cum iri arida et salis exiguo. folia et supra dictis medentur et strumis, panis, ulceribus in facie decocta in vino. cinis e radice alopecias emendat et rimas pe⟨dum⟩⟨se⟩disque, decoctae radicis in oleo sucus perniones et amlbusta et gravitatem aurium; infunditur a contraria aure in dolore dentium. prodest et urinae pota modice radix et menstruis et lateris doloribus, item ruptis, convulsis, tussibus, drachmae pondere in vino pota. eadem et vomitiones adiuvatcommanducata. semine sumpto turbatur venter. Chrysermus et parotidas in vino decocta radice curavit, item strumas admixta cachry ex vino. quidam aiunt, si inposita radice pars eius in fumo suspendatur quartoque die solvatur, una cum radice arescere strumam. ⟨Di⟩ocles ad podagras utroque modo, cocta crudaque, usus est, ad perniones decocta ex oleo; dedit et suffusis felle in vino et hydropicis. venerem quoque concitari cum vino et melle perunctis aut bibentibus tradidere. Xenocrates et lichenas, psoras, lepras radice in aceto decocta tolli dicit, item s⟨u⟩co cum hyoscyamo et pice liquida alarum quoque et feminum vitia; et capillum crispiorem fieri, raso prius capite, si radice ea fricetur, ⟨S⟩imos lapides renium in vino decocta potaque eximi. Hippocrates semine ad impetus lienis dari censet. iumentorum quoque ulcera ac scabiem radix inlita aut decocta⟨e⟩ sucus ad pilum reducit. mures eadem fugantur, caverna praeclusa moriuntur.", "st": "22.32"}, {"sp": "N", "t": "Asphodelum ab Hesiodo quidam halimon appellari existimavere, quod falsum arbitror; est enim suo nomine halimon, non parvi et ipsum erroris inter auctores. alii enim fruticem esse dicunt densum, candidum, sine spina, foliis oleae, sed mollioribus; coqui haec ciborum gratia, radice tormina discuti drachmae pondere in aqua mulsa pota, item rupta, convulsa. alii olus maritimum esse dixere salsum et inde nomen, foliis in rotunditatem longis, laudatum in cibis. duorum praeterea generum, silvestre et mitius, utrumque prodesse dysintericis etiamn exulceratis cum pane, stomacho vero ex aceto. ulceribus vetustis inlini crudum et vulnerum recentium impetus lenire et luxatorum pedum ac vesicae dolores. silvestri tenuiora folia, sed in iisdem remediis effectus maiores et in sananda hominum ac pecorum scabie. praeterea nitorem corpori fieri dentibusque candorem, si fricentur radice ea, semine linguae subdito sitim non sentiri. hoc quoque mandi et utraque etiam condiri. Crateuas tertium quoque genus tradidit longioribus foliis et hirsutioribus, odore cupressi, nasci sub hedera maxime, prodesse opisthotonis, contractionibus nervorum tribus obolis in sextarium aquae.", "st": "22.33"}, {"sp": "N", "t": "Acanthi, topiariae et urbanae herbae lato longoque folio crepidines marginum adsurgentiumque pulvinorum toros vestientis, duo genera sunt: aculeatum et crispum, quod brevius, alterum leve, quod aliqui paederota vocant, alii melamphyllum. huius radices ustis luxatisque mire prosunt, item ruptis, convulsis, et phthisin metuentibus, id coctae cibo, maxime tisana. podagris quoque inlinuntur tritae et calefactae, e sale calidis.", "st": "22.34"}, {"sp": "N", "t": "Bupleuron in sponte nascentium olerum numero Graeci habent, caule cubitali, foliis multis longisque, capite aneti, laudatum in cibis ab Hip⟨p⟩ocrate, in medicina Glaucone et Nicandro. semen contra serpentes valet. folia ad secundas feminarum vel sucum ex vino inlinunt, et strumis folia cum sale et vino. radix contra serpentes datur in vino et urinae ciendae.", "st": "22.35"}, {"sp": "N", "t": "Buprestim magna inconstantia Graeci in laudibus ciborum etiam habuere, iidemque remedia tamquam contra venenum prodiderunt. et ipsum nomen indicio est bourn certe venenum esse, quos dissilire degustata fatentur. quapropter nec de hac plura dicemus. est vero causa, quare venena monstremus inter gramineas coronas! nisi libidinis causa expetenda alicui videtur, quam non aliter magis accendi putant quam pota ea.", "st": "22.36"}, {"sp": "N", "t": "Elaphoboscon ferulaceum est, geniculatum digiti crassitudine, semine corymbis dependentibus silis effigie, set non amaris, foliis olusatri. et hoc laudatum in cibis —quippe etiam conditum prorogatur—, ad urinam ciendam, lateris dolores sedandos, rupta, convulsa sananda, inflationes discutiendas colique tormenta, contra serpentium omniumque aculeatorum ictus, quippe fama est, hoc pabulo cervos resistere serpentibus. fistulas quoque radix nitro addito inlita sanat, siccanda autem in eo usu prius est, ne suco suo madeat, qui contra serpentium ictus non facit deteriorem eam.", "st": "22.37"}, {"sp": "N", "t": "Scandix quoque in olere silvestri a Graecis ponitur, ut Ophion et Erasistratus tradunt. item decocta alvum sistit, semine singultus confestim ex aceto sedat. inlinitur ambustis, urinas ciet. decoctae sucus prodest stomacho, iocineri, renibus, vesicae. haec est quam Aristophanes Euripidi poetae obicit ioculariter: matrem eius ne olus quidem legitimum venditasse, sed scandicem. eadem erat enthr⟨y⟩scum, si teneriora folia et odoratiora haberet. peculiaris laus eius, quod fatigato venere corpori succurrit marcentesque iam senio coitus excitat. sistit profluvia alba feminarum.", "st": "22.38"}, {"sp": "N", "t": "Et ⟨i⟩asine olus silvestre habetur, in terra repens, cum lacte multo, florem fert candidum; conchylium vocant. et huius eadem commendatio ad stimulandos coitus. cruda ex aceto in cibis et mulieribus lactis ubertatem praestat. Salutary⟨is⟩ e⟨st⟩ phthisin sentientibus. infantium capiti inlita nutrit capillum tenacioremque eius cutem efficit.", "st": "22.39"}, {"sp": "N", "t": "Estur et caucalis feniculo similis, brevi caule, flore candido, cordi utilis. sucus quoque eius bibitur, stomacho perquam commendatus et urinae calculisque et harenis pellendis et vesicae pruritibus. extenuat et lienis, iocineris ⟨r⟩eniumque pituitas. semen menses feminarum adiuvat bilemque a partu siccat. datur et contra profluvia geniturae viris. Chrysippus et conceptionibus earn putat conferre multum. bibitur in vino ieiunis. inlinitur et contra venena marinorum, sicut Petrichus in carmine suo significat.", "st": "22.40"}, {"sp": "N", "t": "His adnumerant et sium latius apio, in aqua nascens, pinguius nigriusque, copiosum semine, sapore nasturtii. prodest urinis, renibus, lienibus mulierumque mensibus, sive ipsum in cibo sumptum sive ius decocti sive semine in vino drachmis duabus. calculos rumpit aquisque, quae gignunt eos, resistit. dysintericis prodest infusum, item inlitum lentigini et mulierum vitiis in facie noctu inlitum, ⟨l⟩omentoque cutem emendat et ramices lenit, equorum etiam scabiem.", "st": "22.41"}, {"sp": "N", "t": "Sillybum chamaeleonti albo similem, aeque spinosam, ne in Cilicia quidem aut Syria aut Phoenice, ubi nascitur, coquere tanti est. ita operosa eius culina traditur. in medicina nullum usum habet.", "st": "22.42"}, {"sp": "N", "t": "Scolymum quoque in cibos recipit oriens et alio nomine limoniam appellat. frutex est numquam cubitali altior tristisque foliorum acu⟨leis⟩, radice nigra, sed dulci, Eratostheni quoque laudata in pauperis cena. urinam ciere praecipue traditur, sanare lichenas et lepras ex aceto, venerem stimulare in vino Hesiodo et Alcaeo testibus, qui florente ea cicadas acerriini cantus esse et mulieres libidinis avidissimas virosque in coitum pigerrimos scripsere, velut providentia naturae hoc adiumento tunc valentissimo. item graveolentiam alarum emendat radicis emedullatae uncia, in vini Falerni heminis tribus decocta ad tertias et a balineo ieiuno itemque post cibum cyathis singulis pota. mirum est, quod Xenocrates promittit experimento, vitium id ex alis per urinam effluere.", "st": "22.43"}, {"sp": "N", "t": "Estur et soncos—ut quem Theseo apud Callimachum adponat Hecale—uterque, albus et niger. lactucae similes ambo, nisi spinosi essent, caule cubitali, anguloso, intus cavo, sed qui fractus copioso lacte manet. albus, cui e lacte nitor, utilis orthopnoicis lactucarum modo ex embammate. Erasistratus calculos per urinam pelli eo monstrat et oris graveolentiam commanducato corrigi. sucus trium cyathorum mensura in vino albo et oleo calefactus adiuvat partus ita, ut a potu ambulent gravidae. datur et in sorbitione. ipse caulis decoctus facit lactis abundantiam nutricibus coloremque meliorem infantium, utilissimus his, quae lac sibi coire sentiant. instillatur auribus sucus, calidusque in stranguria bibitur cyathi mensura et in stomachi rosionibus cum semine cucumeris nucleisque pineis. inlinitur et sedis collectionibus. bibitur contra serpentes scorpionesque, radix vero inlinitur. eadem decocta in oleo et punici mali calyce, aurium morbis praesidium est. haec omnia ex albo. Cleemporus nigro prohibet vesci ut morbos faciente, de albo consentiens. Agathocles etiam contra sanguinem tauri demonstrat sucum eius, refrigeratoriam tamen vim esse convenit nigro et hac causa inponendum cum polenta. Zenon radicem albi in stranguria suadet.", "st": "22.44"}, {"sp": "N", "t": "Condrion sive condril⟨l⟩e folia habet intubi, circumrosis similia, caulem minus pedalem, suco madentem amaro, radice fabae simili, aliquando numerosa. habet proximam terrae mastichen tuberculo fabae, quae adposita feminarum menses trahere dicitur. tusa cum radicibus tota dividitur in pastillos contra serpentes, argumento probabili, siquidem mures agrestes laesi ab his hanc esse dicuntur. sucus ex vino coctae alvum sistit. eadem palpebrarum pilos inordinatissimos pro cummi efficacissime regit. Dorotheus stomacho et concoctionibus utilem carminibus suis pronuntiavit. alioqui feminis et oculis generationique virorum contrariam putavere.", "st": "22.45"}, {"sp": "N", "t": "Inter ea, quae temere manduntur, et boletos merito posuerim, opimi quidem hos cibi, sed inmenso exemplo in crimen adduct⟨o⟩s, veneno Tiberio Claudio principi per hanc occasionem ab coniuge Agrippina dato, quo facto illa terris venenum alterum sibique ante omnes Neronem suum dedit. quorundam ex iis facile noscuntur venena diluto rubore, rancido aspectu, livido intus colore, rimosa stria, pallido per ambitum labro. non sunt haec in quibusdam, siccique et veris similes, veluti guttas in vertice albas ex tunica sua gerunt. vulvam enim terra ob hoc prius gignit, ipsum postea in vulva, ceu in ovo est luteum. nec tunicae minor gratia in cibo infantis boleti. rumpitur haec primo nascente, mox increscente in pediculi corpus absumitur, rarumque ut gemin⟨u⟩s ex uno pede. origo prima causaque e limo et acescente suco madentis terrae ant radicis fere g⟨l⟩andiferae, initioque spuma lentior, dein corpus membranae simile, mox partus, ut diximus. illa pernicialia quo⟨t⟩ probandi alia all⟨i⟩s signa! si caligaris clavus ferrive aliqua robigo aut panni marcor adfuerit nascenti, omnem ilico sucum alienum saporemque in venenum concoqui deprehendisse qui nisi agrestes possunt atque qui colligunt ipsi? alia vitia ne hi quidem, si serpentis caverna iuxta fuerit, si patescentem primo adhalaverit, capaci venenorum cognatione ad virus accipiendum. itaque caveri conveniat prius, quam se condant serpentes. signa erunt tot herbae, tot arbores fruticesque ab emersu earum ad latebram usque vernantes et vel fraxini tantum folia nec postea nascentia nec ante decidentia. et boletis quidem ortus occasusque omnis intra dies septem est.", "st": "22.46"}, {"sp": "N", "t": "Fungorum lentior natura et numerosa genera, sed origo non nisi ex pituita arborum. tutissimi qui rubent callo, minus diluto rubore quam boleti; mox candidi, velut apice flaminis insignibus pediculis; tertium genus suilli, venenis accommodatissimi. familias nuper interemere et tota convivia, Annaeum Serenum, praefectum Neronis vigilum, et tribunos centurionesque. quae voluptas ta⟨m⟩ ancipitis cibi? quidam discrevere arborum generibus, fico ferulave et cummim ferentibus, non item taxo aut robore, cupresso, ut diximus. sed ista quis spondet in venalibus? omnium colos lividus; hic habebit veneni argumentum, quo similior fuerit arborum cor⟨t⟩ici. adversus haec diximus remedia dicemusque; interim sunt aliqua et in iis. Glaucias stomacho utiles putat boletos. siccantur pendentes suilli, iunco transfixi, quales e Bithynia veniunt. hi fluctionibus alvi, quas rheumatismos vocant, medentur excrescentibusque in sede carnibus; minuunt enim eas et tempore absumunt, item lentiginem et mulierum in facie vitia. lavantur etiam, ut plumbum, in oculorum medicamenta. sordidis ulceribus et capitis eruptionibus, canum morsibus ex aqua inlinuntur. libet et coquendi dare aliquas communes in omni eo genere observationes, quando ipsae suis manibus deliciae praeparant hunc cibum solum et cogitatione ante pascuntur sucinis novaculis aut argenteo apparatu comitante. noxii erunt fungi, qui in coquendo duriores fient; innocentiores, qui nitro addito coquentur, utique si percoquantur. tutiores fiunt cum carne cocti aut cum pediculo piri; prosunt et pira confestim sumpta. debellat eos et aceti natura contraria iis.", "st": "22.47"}, {"sp": "N", "t": "Imbribus proveniunt omnia haec, imbre et silphium venit primo, ut dictum est. ex Syria nunc hoc maxime inportatur, deterius Parthico, sed Medico melius, extincto omni Cyrenaico, ut diximus. usus silphii in medicina foliorum ad purgandas vulvas pellendosque emortuos partus; decocuntur in vino albo et odorato, ut bibatur mensura acetabuli a balineis. radix prodest arteriis exasperatis, collectionibus sanguinis inlinitur. sed in cibis concoquitur aegre, inflationes facit et ructus. urinae quoque noxia est, suggillatis cum vino et oleo amicissima et cum cera strumis. verrucae sedis crebriore eius suffitu cadunt.", "st": "22.48"}, {"sp": "N", "t": "Laser e silphio profluens quo diximus modo inter eximia naturae dona numeratum plurimis compositionibus inseritur, per se autem algores excalfacit, potum nervorum vitia extenuat. feminis datur in vino et lanis mollibus admovetur vulvae ad menses ciendos. pedum o clavos circumscariphatos ferro mixtum cerae extrahit. urinam ciet ciceris magnitudine dilutum. Andreas spondet copiosius sumptum nec inflationes facere et concoctioni plurimum conferre senibus et feminis, item hieme quam aestate utilius, et tum aquam bibentibus. cavendum, ne qua sit exulceratio intus. ab aegritudine recreationi efficax in cibo; tempestive enim datum cauteri⟨i⟩ v⟨i⟩m optinet, adsuetis etiam utilius quam expertibus. extera corporum indubitatas confessiones habent: venena telorum et serpentium extinguit potum; ex aqua vulneribus his circumlinitur, scorpionum tantum plagis ex oleo, ulceribus vero non maturescentibus cum farina hordeacia vel fico sicca, carbunculis cum ruta vel cum melle vel per se visco superlitum, ut haereat; sic ⟨e⟩t ad canis morsus; excrescentibus circa se⟨d⟩em cum ⟨t⟩egmine punici mali ex aceto decoctum, clavis, qui volgo morticini appellantur, nitro mixto. alopecias nitro ante subactas replet cum vino et croco aut pipere ac murium fimo et aceto. perniones ex vino fovet et ex oleo coctum; inponitur sic et callo, clavis pedum superrasis; praecipuae utilitatis contra aquas malas, pestilentes tractus vel dies; in tussi, uva; fellis veteri suffusioni, hydropicis, raucitatibus; confestim enim purgat fauces vocemque reddit. podagras in spongea dilutum posca lenit. pleuriticis in sorbitione vinum poturis datur, contractionibus, opisthotonicis ciceris magnitudine cera to circumlitum. in angina gargarizatur. anhelatoribus et in tussi vetusta cum porro ex aceto datur; a⟨t⟩ ex aceto his, qui coagulum lactis sorbuerint, praecordiorum vitiis syntecticis, comitialibus cum vino, in aqua mulsa linguae paralysi. coxendicibus et lumborum doloribus cum decocto melle inlinitur. non censuerim, quod auctores suadent, cavernis dentium in dolore inditum cera includi, magno experimento hominis, qui se ea de causa praecipitavit ex alto. quippe tauros inflammat naribus inlitis, serpentes avidissimas vini admixtum rumpit; ideo nec inungui suaserim, cum Attico licet melle praecipiant. quas habeat utilitates admixtum aliis, inmensum est referre, et nos simplicia tractamus, quoniam in his naturam esse apparet, in illis coniecturam saepius fallacem, nulli satis custodita in mixturis concordia naturae ac repugnantia. qua de re mox plura.", "st": "22.49"}, {"sp": "N", "t": "Non esset mellis auctoritas in pretio minor quam laseris, ni ubique nasceretur. illud ipsa fabricata ⟨e⟩st natura, sed huic gignendo animal, ut diximus, innumeros ad usus, si quotiens misceatur aestimemus. prima propolis alvorum, de qua diximus, aculeos et omnia infixa corpori extrahit, tubera discutit, dura concoquit, dolores nervorum mulcet ulceraque iam desperantia cicatricem cludit. mellis quidem ipsius natura talis est, ut putrescere corpora non sinat. iucundo sapore atque non aspero, alia quam salis natura, faucibus, tonsillis, anginae omnibusque oris desideriis utilissimum arescentique in febribus linguae, iam vero peripneumonicis, pleuriticis decoctum, item vulneribus, a serpente percussis et contra venena, fungos, paralytic⟨i⟩s in mulso, quamquam suae mulso dotes constant. mel auribus instillatur cum rosaceo, lendes et foeda capitis animalia necat. usus despumati semper aptior, stomachum tamen inflat, bilem auget, fastidium creat. et oculis per se inutile aliqui arbitrantur; rursus quidam angulos exulceratos melle tangi suadent. mellis causas atque differentias nationesque et i⟨n⟩dicationem in apium ac deinde florum natura diximus, cum ratio operis dividi cogeret miscenda rursus naturam rerum pernoscere volentibus.", "st": "22.50"}, {"sp": "N", "t": "In mellis operibus et aqua mulsa debet tractari. duo genera eius, subitae ac recentis, alterum inveteratae. repentina despumato melle praeclaram utilitatem habet in cibo aegrotantium levi, hoc est alica eluta, viribus recreandis, ore stomachoque mulcendo, ardores refrigerando. frigidam enim dari utilius ventri molliendo. invenio apud auctores, ⟨de⟩co⟨c⟩tum bibendum alsiosis, item animi humilis et praeparci, quos illi dixere micropsyc⟨h⟩os. ut est ratio subtilitatis inmensae a Platone descendens, corpusculis rerum levibus scabris, angulosis rotundis, magis aut minus ad aliorum naturam accedentibus, ideo non eadem omnibus amara aut dulcia esse; sic et in lassitudine proniores esse ad iracundiam et in siti. ergo et haec animi asperitas, seu potius animae, dulciore suco mitigatur lenito transitu spiritus et molliore facto meatu, ne scindat euntem redeuntemque. experimenta in se cuique: nullius non ira luctusque, tristitia et omnis animi impetus cibo mollitur, ideoque observanda sunt quae non solum corporum medicinam, sed et morum habent.", "st": "22.51"}, {"sp": "N", "t": "Aqua mulsa et tussientibus utilis traditur, calefacta invitat vomitiones, contra venenum psimithii salutaris addito oleo, item contra hyoscyam⟨i⟩ cum lacte maxime asinino, et contra halicacabi, ut diximus. infunditur et auribus et genitalium fistulae. vulvis inponitur cum pane molli, subitis tumoribus, luxatis leniendisque omnibus. inveteratae usum damnavere posteri, minus innocentem aqua minusque vino firmum; longa tamen vetustate transit in vinum, ut constat inter omnes, stomacho inutilissimum nervisque contrarium.", "st": "22.52"}, {"sp": "N", "t": "Semper mulsum ex vetere vino utilissimum, facillimeque cum melle concorporatur, quod in dulci numquam evenit. ex austero factum non inflat stomachum, neque ex decocto melle, minusque implet, quod fere evenit; adpetendi quoque revocat aviditatem cibi. alvum mollit frigido potu, pluribus calido sistit, corpora auget. multi senectam longam mulsi tantum intrita toleravere, neque alio ullo cibo, celebri Pollionis Romili exemplo. centensimum annum excedentem eum divus Augustus hospes interrogavit, ⟨q⟩u⟨a⟩nam maxime ratione vigorem illum animi corporisque custodisset. at ille respondit: intus mulso, foris oleo. Varro regium cognominatum arquatorum morbum tradit, quoniam mulso curetur.", "st": "22.53"}, {"sp": "N", "t": "Melitites quo fieret modo ex musto et melle, docuimus in ratione vini. saeculis iam fieri non arbitror hoc genus, inflationibus obnoxium. solebat tamen inveteratum alvi causa dari in febre, item articulario morbo et nervorum infirmitate laborantibus et mulieribus vini abstem⟨i⟩is.", "st": "22.54"}, {"sp": "N", "t": "Mellis naturae adnexa cera est, de cuius origine, bonitate, nationibus suis locis diximus. omnis autem mollit, calefacit, explet corpora. recens melior. datur in sorbitione dysintericis, favique ipsi in pulte alicae prius tostae. adversatur lactis naturae, ac milii magnitudine decem grana cerae hausta non patiuntur coagulari lact in stomacho. si inguen tumeat, albam ceram in pube fixisse remedio est.", "st": "22.55"}, {"sp": "N", "t": "Nec huius usus, quos mixta aliis praestat, enumerare possit medicina, sicuti nec ceterorum, quae cum aliis prosunt. ista, ut diximus, ingeniis constant. non fecit ceratum, malagmata, emplastra, collyria, antidota parens illa ac divina rerum artifex; officinarum haec, immo verius avaritiae commenta sunt. naturae quidem opera absoluta atque perfecta gignuntur, paucis ex causa, non ex coniectura rebus adsumptis, ut suco aliquo sicca temperentur ad meatus aut corpore alio umnentia ad nexus. scripulatim quidem colligere ac miscere vires non coniecturae humanae opus, sed inpudentiae est. nos nec Indicarum Arabicarumque mercium aut externi orbis adtingimus medicinas. non placent remediis tam longe nascenlia, non nobis gignuntur, immo ne illis quidem; alioqui non venderent. odorum causa unguentorumque et deliciarum, si place, etiam superstitionis gratia emantur, quoniam ture supplicamus et costo. salutem quidem sine istis posse constare, vel ob id probabiimus, ut tanto magis sui delicias pudeat.", "st": "22.56"}, {"sp": "N", "t": "Sed medicinas e floribus coronamentisque et hortensiis quaeque mandantur herbae persecuti quonam modo frugum omittimus? Nimirum et has indicare conveniat.", "st": "22.57"}, {"sp": "N", "t": "in primis sapientissima animalium esse constat, quae fruge vescantur. siliginis grana combusta et trita in vino Am⟨m⟩ineo, oculis inlita epiphoras sedant, tritici vero ferro combusta iis, quae frigus usserit, praesentaneo sunt remedio. farina tritici ex aceto cocta nervorum contractionibus, cum rosaceo vero et fico sicca myxisque decoctis furfures tonsillis faucibusque gargarizatione prosunt. Sex. Pomponius, praetorii viri pater, Hispaniae citerioris princeps, cum horreis suis ventilandis praesideret, correptus dolore podagrae mersit in triticum super genua sese, levatusque siccatis pedibus mirabilem in modum hoc postea remedio usus est. vis tanta est, ut cados plenos siccet. paleam quoque tritici vel hordei calidam inponi ramicum incommodis experti iubent, quaque decoctae sint aqua fovere. est in farre vermiculus teredini similis, quo cavis dentium cera incluso cadere vitiati dicuntur, etiam si fricentur. olyram arincam diximus vocari. hac decocta fit medicamentum, quod Aegyptii atheram vocant, infantibus utilissimum, sed et adultos inlinunt eo.", "st": "22.57"}, {"sp": "N", "t": "Farina ex hordeo et cruda et decocta collectiones impetusque discutit, lenit concoquitque. decoquitur alias in mulsa aqua aut fico sicca; ⟨a⟩t iocineris doloribus, cum pus concoqui opus est, in vino; cum inter coquendum discutiendumque cura est, tune in aceto melius aut in faece aceti aut cotoneis pirisve decoctis; ad multipedae morsus cum melle, ad serpentium in aceto et contra suppurantia, ad extrahendas suppurationes ex posca addita resina Gallica; ad concoctiones vero et ulcera vetera cum resina, ad duritias cum fimo columbarum aut fico sicca aut cinere, ad nervorum inflammationes aut intestinorum vel ⟨late⟩rum dolores cum papavere aut meliloto, et quotiens ab ossibus caro recedit, ad strumas cum pice et inpubis pueri urina, cum oleo. cum Graeco feno contra praecordiorum tumores vel in febribus cum melle vel adipe vetusto. suppuratis triticea farina multo lenior. nervis cum hyoscyami suco inlinitur, ex aceto et melle lentigini. zeae, ex qua alicam fieri diximus, efficacior etiam hordeacea videtur, trimenstris mollior, ex vino rubro ad scorpionum ictus tepida et sanguinem excreantibus, item arteriae, tussi cum caprino sebo aut butyro. ex feno Graeco, mollissima omnium, ulcera manantia sanat et furfures corporis, stomachi dolores, pedes et mammas cum vino et nitro cocta. aerina magis ceteris purgat ulcera vetera et gangraenas cum raphano et sale, e⟨x⟩ aceto lichenas, lepras cum sulpure vivo, et capitis dolores cum adipe anserino inposita fronti. strumas et panos concoquit cum fimo columbino et lini semine decocta in vino.", "st": "22.58"}, {"sp": "N", "t": "De polentae generibus in frugum loco satis diximus. medicorum ratione a farina hordei distat eo, quod torretur, ob id stomacho utilis. alvum sistit impetusque rubicundi tumoris; et oculis inlinitur et capitis dolori cum menta aut alia refrigerante herba, item pernionibus et serpentium plagis, item ambustis ex vino, inhibetque pusulas.", "st": "22.59"}, {"sp": "N", "t": "Farina in pollinem subacta vim extrahendi umoris habet ⟨a⟩deo, ut cruore suffusis in fascias usque sanguinem perducat, efficacius in sapa. inponitur et pedum callo clavisque. nam cum oleo vetere ac pice decocto polline condylomata et alia omnia sedis vitia quam maxime calido mirabilem in modum curantur. pulte corpus augetur. farina, qua chartae glutinantur, sanguinem excreantibus datur tepida sorbenda efficaciter.", "st": "22.60"}, {"sp": "N", "t": "Alica res Romana est et non pridem excogitata; alioqui non tisanae potius laudes scripsissent Graeci. nondum arbitror Pompei Magni aetate in usu fuisse, et ideo vix quicquam de ea scriptum ab Asclepiadis schola. esse quidem eximie utilem nemo dubitat, sive eluta detur ex aqua mulsa sive in sorbitione decocta sive in pulte. eadem in alvo sistenda torretur, dein favorum cera coquitur, ut supra diximus. peculiariter tamen longo morbo ad tabitudinem redactis subvenit ternis eius cyathis in sextarium aquae sensim decoctis, donec omnis aqua consumatur, postea sextario lactis ovilli aut caprini addito per continuos dies…, mox adiecto melle. tali genere sorbitionis emendantur syntexis.", "st": "22.61"}, {"sp": "N", "t": "Milio sistitur alvus, discutiuntur tormina, in quem usum torretur ante. nervorum doloribus et aliis fervens in sacco inponitur, neque aliud utilius, quoniam levissimum mollissimumque est et caloris capacissimum. itaque talis usus eius est ad omnia, quibus calor profuturus est. farina eius cum pice liquida serpentium et multipedae plagis inponitur.", "st": "22.62"}, {"sp": "N", "t": "Panicum Diocles medicus mel frugum appellavit. effectus habet quos milium. in vino potum prodest dysintericis. similiter his, quae vaporanda sunt, excalfactum inponitur. sistit alvum in lacte caprino decoctum et bis die haustum. sic prodest et ad tormina.", "st": "22.63"}, {"sp": "N", "t": "Sesima trita in vino sumpta inhibet vomitiones. aurium inflammationi inlinitur et ambustis. eadem efficit et dum in herba est. hoc amplius oculis inponitur decocta in vino. stomacho inutilis in cibis et animae gravitatem facit. stellionum morsibus resistit, item ulceribus, quae cacoëthe vocant, et auribus oleum, quod ex ea fit, prodesse diximus. sesamoides a similitudine nomen accepit, grano amaro, folio minore. nascitur in glareosis. detrahit bilem in aqua potum semen, inlinitur igni sacro, discutit panos. est etiamnum aliud sesamoides, Anticyrae nascens, quod ideo aliqui Anticyricon vocant, cetera simile erigeronti herbae, de qua dicemus suo loco, grano sesamae. datur in vino dulci ad detractiones quantum tribus digitis capitur. miscent ibi et ellebori albi unum et dimidium obolum, purgationem eam adhibentes maxime insaniae melancholicae,comitialibus, podagris. et per se drachmae pondere exinanit.", "st": "22.64"}, {"sp": "N", "t": "Hordeum optimum quod candidissimum. sucus decocti in aqua caelesti digeritur in pastillos, ut infundantur exulceratis interaneis et vulvis. cinis eius ambustis inlinitur et carnibus, quae recedunt ab ossibus, et eruptionibus pituitae, muris aranei morsibus. idem adsperso sale ac melle candorem dentibus, suavitatem oris facit. eos, qui pane hordeacio utuntur, morbo pedum temptari negant. novem granis furunculum si quis. circumducat, singulis ter manu sinistra, et omnia in ignem abiciat, confestim sanari aiunt. est et herba ph⟨oe⟩nice appellata a Graecis, nostris vero hordeum murinum; haec trita e vino pota praeclare ciet menses.", "st": "22.65"}, {"sp": "N", "t": "Tisanae, quae ex hordeo fit, laudes uno volumine condidit Hippocrates, quae nunc omnes in alicam transeunt. quanto innocentior alica! Hi p p o c r ates tamen sorbitionis gratia laudavit, quoniam lubrica ex facili hauriretur, quoniam sitim arce⟨re⟩t, quoniam in alvo non intumesceret, quoniam facile redderetur et. adsuetis hic cibus solus in febri bis die posset dari, tantum remotus ab istis, qui medicinam fame exercent. sorbitionem tamen dari totam vetuit aliudve quam sucum tisanae; item vetuit, quamdiu pedes frigidi essent, tune quidem nec potionem dandam. fit et ex tritico glutinosior arteriaeque exulceratae utilior.", "st": "22.66"}, {"sp": "N", "t": "Am⟨y⟩lon hebetat oculos, et gulae inutile, contra quam creditur. item alvum sistit, epiphoras oculorum inhibet et ulcera sanat, item pusulas et fluctiones sanguinis. genas duras emollit. datur cum ovo iis, qui sanguinem reiecerint, in vesicae vero dolore semuncia amyli cum ovo et passi tribus ovis subfervefacta a balineo. quin et avena⟨c⟩ea farina decocta in aceto naevos tollit.", "st": "22.67"}, {"sp": "N", "t": "Panis hic ipse, quo vivitur, innumeras paene continet medicinas. ex aqua et oleo aut rosaceo mollit collectiones; ex aqua mulsa ad duritias valde mitigandas, ex vino ad discutienda aut quae praestringi opus sit et, si magis etiamnum, ex aceto, adversus acutas pituitae fluctiones, quas Graeci rheumatismos vocant, item ad percussa, luxata, ad omnia autem fermentatus, qui vocatur autopyrus, utilior. inlinitur et paronychiis et callo pedum in aceto. vetus aut nauticus panis tusus atque iterum coctus sistit alvum. vocis studiosis et contra destillationes siccum esse primo cibo utilissimum est. sitanius, hoc est e trimestri, incussa in facie aut desquamata cum melle aptissime curat. candidus aegris aqua calida frigidave madefactus levissimum cibum praebet. oculorum tumori ex vino inponitur; sic et pusulis capitis aut adiecta arida myrto. tremulis panem ex aqua esse ieiunis statim a balineis demonstrant. quin et gravitatem odorum in cubiculis ustus emendat et vini in saccos additus.", "st": "22.68"}, {"sp": "N", "t": "Et faba auxiliatur. namque solida fricta fervensque in acre acetum coniecta torminibus medetur. in cibo fresa et cum alio cocta contra deploratas tusses suppurationesque pectorum cotidiano cibo sumitur, et commanducata ieiuno ore et ad furunculos maturandos discutiendosve inponitur, et in vino decocta ad testium tumores, ad genitalia. lomento quoque ex aceto decocto tumores maturat atque aperit, item livoribus, combustis medetur. voci eam prodesse auctor est M. Varro. fabalium etiam siliquarumque cinis ad coxendices, ad nervorum veteres dolores cum adipis suilli vetustate prodest. et per se cortices decocti ad tertias sistunt alvum.", "st": "22.69"}, {"sp": "N", "t": "Lens optima quae facillime coquitur et ea, quae maxime aquam absorbet. aciem quidem oculorum obtundit et stomachum inflat, sed alvum sistit in cibo magisque caelesti aqua discocta; eadem solvit minus percocta. pusulas ulcerum rumpit; ea, quae intra os sunt, purgat et adstringit. collectiones omnes inposita sedat maximeque exulceratas et rimosas; oculorum autem epiphoras cum meli⟨lo⟩to aut cotoneo. contra suppurantia cum polenta inponitur. decoctae sucus ad oris exulcerationes et genitalium adhibetur, ad sedem cum rosaceo aut cotoneo, in iis, quae acrius remedium exigant, cum putamine punici melle modico adiecto. ad id demum, ne celeriter inarescat, adiciunt et betae folia. inponitur et strumis, panis vel maturis vel maturescentibus ex aceto discocta, rimis ex aqua mulsa et gangraenis cum punici tegmine; item podagris cum polenta et vulvis et renibus, pernionibus, ulceribus difficile cicatricem trahentibus. propter dissolutionem stomachi XXX grana lentis devorantur. in chol⟨e⟩ris quoque et dysinteria efficacior est in tribus aquis cocta, in quo usu melius semper eam torrere ante et tundere, ut quam tenuissima detur vel per se vel cum cotoneo malo aut piris aut myrto aut intubo erratico aut beta nigra aut plantagine. pulmonie⟨s⟩t inutilis et capitis dolori nervosisque omnibus et felli, nec somno facilis, at pusulis utilis ignique sacro et mammis in aqua marina decocta, in aceto autem duritias et strumas discutit. stomachi quidem causa polentae modo potionibus inspergitur. quae sint ambusta, aqua semicocta cura⟨n⟩t, postea trita et per cribrum effuso furfure, mox procedente curatione addito melle. ex posca coquitur ad guttura. est et palustris lens, per se nascens in aqua non profluenti, refrigeratoriae naturae, propter quod collectionibus inlinitur et maxime podagris et per se et cum polenta. glutinat et interanea procidentia.", "st": "22.70"}, {"sp": "N", "t": "Est silvestris elelisphacos dicta a Graecis, aliis ⟨sph⟩acos dicta, sativa lente leviore et folio minore atque sicciore et odoratiore. est et alterum genus eius silvestrius, odore gravi; haec mitior folia habet cotonei mali effigie, set minora et candida, quae cum ramis decocuntur. menses ciet et urinas, et pastinacae marinae ictus sanat, torporem autem obducit percusso loco. bibitur cum absinthio et dysinteriae. cum vino eadem commorantes menses trahit, abundantes sistit decocto eius poto. per se inposita herba vulnerum sanguinem cohibet. purgat et serpentium morsus et, si in vino decoquatur, pruritus testium sedat. nostri, qui nunc sunt, herbarii elelisphacum Graece, salviam Latine vocant, mentae similem, canam, odoratam. partus emortuos ea adposita extrahunt, item vermes ulcerum auriumque.", "st": "22.71"}, {"sp": "N", "t": "Cicer et silvestre est, foliis simile, odore gravi. si largius sumatur, alvus solvitur et inflatio contrahitur et tormina.tostum salubrius habetur. cicercula etiamnum magis in alvo proficit. farina utriusque ulcera manantia capitis sanat, efficacius silvestris, item comitiales et iocinerum tumores et serpentium ictus. ciet menses et urinas, grano maxime. emendat et lichenas et testium inflammationes, regium morbum, hydropicos. laedunt omnia haec genera exulceratam vesicam et renes. gangraenis utiliora cum melle et his, quae cacoëthe vocantur. verrucarum in omni genere prima luna singulis granis singulas tangunt, eaque grana in linteolo deligata post se abiciunt, ita fugari vitium arbitrantes. nostri praecipiunt arietinum in aqua cum sale discoquere, ex eo bibere cyathos binos in difficultatibus urinae; sic et calculos pelli.morbumque regium. eiusdem foliis sarmentisque decoctis aqua quam maxime calida morbos pedum lenit, et ipsum calidum tritumque inlitum. columbini decocti aqua horrorem tertianae et quartanae minuere creditur. nigrum autem cum gallae dimidi⟨o⟩ tritum oculorum ulceribus ex passo medetur.", "st": "22.72"}, {"sp": "N", "t": "De ervo quaedam in mentione eius diximus, nec potentiam ei minorem veteres quam brassicae tribuere contra serpentium ictus ex aceto, ad crocodilorum hominumque morsum. si quis ervum cotidie ieiunus edit, lienem eius absumi certissimi auctores adfirmant. farina eius varos, sed et maculas cutis toto corpore emendat. serpere ul⟨c⟩era non patitur, in mammis efficacissimum. carbunculos rumpit ex vino. urinae difficultates, inflationem, vitia iocineris, tenesmon et quae cibum non sentiant, atropha appellata, tostum et in nucis abellanae magnitudinem melle collectum devoratumque corrigit; item impetigines ex aceto coctum et quarto die solutum. panos in melle inpositum suppurare prohibet. aqua decocti perniones et pruritus sanat fovendo. quin et universo corpori, si quis cotidie ieiunus biberit, meliorem fieri colorem existumant. cibis idem hominis alienum. vomitiones movet, alvum turbat, capiti et stomacho onerostim; genua quoque degravat. sed madefactum pluribus diebus mitescit, bubus iumentisque utilissimum. siliquae eius virides prius, quam indurescant, cum suo caule foliisque contrit⟨ae⟩ capillos nigro colore inficiunt.", "st": "22.73"}, {"sp": "N", "t": "Lupini quoque silvestres sunt, omni modo minores praeterquam amaritudine. ex omnibus, quae eduntur, sicco nulli minus ponderis est nec plus utilitatis. mitescunt cinere aut aqua calidis. colorem hominis frequentiores in cibo exhilarant, amari contra aspidas valent. ulcera atra aridi decorticatique triti supposito linteolo ad vivum corpus redigunt. strumas, parotidas in aceto cocti discutiunt. sucus decoctorum cum ruta et pipere vel in febri datur ad ventris animalia pellenda minoribus XXX annorum, pueris vero etiam inpositi in ventrem ieiunis prosunt, et alio genere tosti vel in defruto poti vel ex melle sumpti. iidem aviditatem cibi faciunt, fastidium detrahunt. farina eorum aceto subacta papulas pruritusque in balneis inlita cohibet et per se siccat ulcera. livores emendat, inflammationes cum polenta sedat. silvestrium efficacior vis contra coxendicum et lumborum debilitatem. ex iisdem decocta lentigines et cutem foventium corrigunt, si vero ad mellis crassitudinem decoquantur, vel [sativi] vitiligines nigras et lepras emendant. sativi quoque rumpunt carbunculos inpositi, panos, strumas minuunt aut maturant cocti ex aceto, cicatricibus candidum colorem reddunt; si vero caelesti aqua discoquantur, sucus ille zmegma fit, quo fovere gangraenas, eruptiones pituitae, ulcerum manantia expediat, ad lienem bibere et cum melle haerentibus menstruis. lieni crudi cum fico sicca triti ex aceto inponuntur. radix quoque in aqua decocta urinas pellit. medentur pecori cum chamaeleone herba decocti, aqua in potum col⟨a⟩ta. sanant et scabiem quadripedum omnium in amurca decocti vel utroque liquore postea mixto. fumus crematorum culices necat.", "st": "22.74"}, {"sp": "N", "t": "Irionem inter fruges sesamae similem esse diximus et a Graecis erysimon vocari, Galli velam appellant. est autem fruticosum, foliis erucae, angustioribus paulo, semine nasturtii, utilissimum tussientibus cum melle et in thoracis purulentis excreationibus. datur et regio morbo et lumborum vitiis, pleuriticis, torminibus, coeliacis. inlinitur vero parotidum et carcinomatum malis, testium ardoribus ex aqua, alias cum melle, infantibus quoque utilissimum, item sedis vitiis et articulariis morbis cum melle et fico, contra venena etiam efficax potu. medetur et suspiriosis, item fistulis cum axungia vetere ita, ne intus addatur.", "st": "22.75"}, {"sp": "N", "t": "Horminum semine, ut diximus, cumino simile est, cetero porro, dodrantali altitudine, duorum generum: alteri semen nigrius et oblongum—hoc ad venerem stimulandam et ad oculorum'.argema, albugines—, alteri candidius semen et rotundius. utroque tuso extrahuntur aculei ex corpore per se inlitovel ex aqua, folia ex aceto inposita panos per se vel cum melle discutiunt, item furunculos, priusquam capita faciant, omnesque acrimonias.", "st": "22.76"}, {"sp": "N", "t": "Quin et ipsae frugum pestes in aliquo sunt usu. infelix dictum est a Vergilio lolium, hoc tamen molitum, ex aceto coctum inpositumque sanat inpetigines celerius, quo saepius mutatum est. medetur et podagrae aliisque doloribus cum oxymelite. ratio haec: aceti sextario uno diluuntur mellis unciae duae. iustum est ita temperatis sextariis tribus decoctae farinae lolii sextarios… usque ad crassitudinem, calidumque inponi dolentibus membris. eadem farina extrahit ossa fracta.", "st": "22.77"}, {"sp": "N", "t": "Miliaria appellatur herba, quae necat milium. haee trita et cornu cum vino infusa podagras iumentorum dicitur sanare.", "st": "22.78"}, {"sp": "N", "t": "Bromos semen est spicam ferentis herbae. nascitur inter vitia segetis avenae genere, folio et stipula triticum imitatur; in cacuminibus dependentes parvolas veluti locustas habet. semen utile ad cataplasmata, a⟨d⟩ qu⟨a⟩e hordeum et similia. prodest tussientibus sucus.", "st": "22.79"}, {"sp": "N", "t": "Orobanchen appellavimus necantem ervum et legumina; alii cynomorion eam appellant a similitudine canini genitalis. cauliculus est sine foliis, pinguis, rubens. estur et per se et in patinis, cum tenera est, decocta.", "st": "22.80"}, {"sp": "N", "t": "Et leguminibus ⟨in⟩nascuntur bestiolae venenatae, quae manus pungunt et periculum vitae adferunt, solipugarum generis. adversus has omnia eademmedentur, quae contra araneos et phalangia demonstrantur. et frugum quidem haec sunt in usu medico.", "st": "22.81"}, {"sp": "N", "t": "Ex iisdem fiunt et potus, zyt⟨h⟩um in Aegypto, caelia et cerea in Hispania, cervesia et plura genera in Gallia aliisque provinciis, quorum omnium spuma cutem feminarum in facie nutrit. nam quod ad potum ipsum attinet, praestat ad vini transire mentionem atque a vite ordiri medicinas arborum.", "st": "22.82"}], []);})();
